/* Heap copy of a NUL-terminated string (strdup is a POSIX extension not
   declared under -std=c99). Returns NULL on allocation failure or NULL
   input. */
static char* msvg__dupstr(const char* s)
{
	size_t n;
	char* d;
	if (s == NULL)
		return NULL;
	n = strlen(s) + 1;
	d = (char*)malloc(n);
	if (d != NULL)
		memcpy(d, s, n);
	return d;
}



#define MSVG_PI (3.14159265358979323846264338327f)
#define MSVG_KAPPA90 (0.5522847493f)	// Length proportional to radius of a cubic bezier handle for 90deg arcs.
#define MSVG_KAPPA45 (0.2652164898f)	// 4/3·tan(45°/4): handle for 45° arcs. A single 90° KAPPA90
									// cubic dips ~2.7% of the radius inside the true arc at its
									// midpoint; splitting to 45° segments cuts that to ~0.17%
									// (sub-pixel for typical sizes). Used for circles, ellipses
									// and rounded-rect corners so rasterization matches the true
									// SVG 2 conic (circles/ellipses are exact conics, not beziers).

#define MSVG_ALIGN_MIN 0
#define MSVG_ALIGN_MID 1
#define MSVG_ALIGN_MAX 2
#define MSVG_ALIGN_NONE 0
#define MSVG_ALIGN_MEET 1
#define MSVG_ALIGN_SLICE 2

#define MSVG_NOTUSED(v) do { (void)(1 ? (void)0 : ( (void)(v) ) ); } while(0)
#define MSVG_RGB(r, g, b) (((unsigned int)(r)) | ((unsigned int)(g) << 8) | ((unsigned int)(b) << 16))
#define MSVG_RGBA(r, g, b, a) (((unsigned int)(r)) | ((unsigned int)(g) << 8) | ((unsigned int)(b) << 16) | ((unsigned int)(a) << 24))

// Packs a paint color with its opacity into a 32-bit ARGB pixel: the color
// may carry an alpha channel (rgba()/hsla()/...), which multiplies the
// explicit *-opacity per CSS Color 4. 'cc' marks a currentColor-derived
// color (opaque RGB only).
static unsigned int msvg__packPaint(unsigned int color, float opacity, int cc)
{
	int a = cc ? 255 : (int)((color >> 24) & 0xff);
	return (color & 0xffffff) | ((unsigned int)(opacity * (float)a + 0.5f) << 24);
}

