static MSVGpatternData* msvg__findPatternData(MSVGparser* p, const char* id)
{
	MSVGpatternData* pat = p->patterns;
	if (id == NULL || *id == '\0')
		return NULL;
	while (pat != NULL) {
		if (strcmp(pat->id, id) == 0)
			return pat;
		pat = pat->next;
	}
	return NULL;
}

// Applies a transform to a single shape's control points and bounds
// WITHOUT touching shape->xform or stroke geometry — for recomputing clip
// geometry clones (whose gradients are irrelevant and whose stroke is not
// rendered). See msvg__transformClipGeometry / transformMaskGeometry.
// Applies a transform to every control point of a shape, recomputes all
// bounds, premultiplies the transform into shape->xform (for gradient
// resolution) and rescales stroke geometry by the transform's average scale.
static void msvg__transformShape(MSVGshape* shape, float* t)
{
	MSVGpath* path;
	float scale = msvg__getAverageScale(t);
	int i;

	/* non-scaling-stroke / non-scaling-size: the stroke outline is computed
	   in host space, so extra transforms (viewBox, pattern rebase,
	   use/marker/clip/mask bakes) must not scale the stroke geometry. */
	if (shape->vectorEffect == MSVG_VECTOR_EFFECT_NONE) {
		shape->strokeWidth *= scale;
		shape->strokeDashOffset *= scale;
		for (i = 0; i < shape->strokeDashCount; i++)
			shape->strokeDashArray[i] *= scale;
	}

	msvg__xformPremultiply(shape->xform, t);

	for (path = shape->paths; path != NULL; path = path->next) {
		float curve[4*2], cb[4];
		int first = 1;
		for (i = 0; i < path->npts; i++)
			msvg__xformPoint(&path->pts[i*2], &path->pts[i*2+1],
				path->pts[i*2], path->pts[i*2+1], t);
		for (i = 0; i < path->npts-1; i += 3) {
			memcpy(&curve[0], &path->pts[i*2], 2*sizeof(float));
			memcpy(&curve[2], &path->pts[(i+1)*2], 2*sizeof(float));
			memcpy(&curve[4], &path->pts[(i+2)*2], 2*sizeof(float));
			memcpy(&curve[6], &path->pts[(i+3)*2], 2*sizeof(float));
			msvg__curveBounds(cb, curve);
			if (first) {
				path->bounds[0] = cb[0]; path->bounds[1] = cb[1];
				path->bounds[2] = cb[2]; path->bounds[3] = cb[3];
				first = 0;
			} else {
				path->bounds[0] = msvg__minf(path->bounds[0], cb[0]);
				path->bounds[1] = msvg__minf(path->bounds[1], cb[1]);
				path->bounds[2] = msvg__maxf(path->bounds[2], cb[2]);
				path->bounds[3] = msvg__maxf(path->bounds[3], cb[3]);
			}
		}
	}
	if (shape->paths != NULL) {
		shape->bounds[0] = shape->paths->bounds[0];
		shape->bounds[1] = shape->paths->bounds[1];
		shape->bounds[2] = shape->paths->bounds[2];
		shape->bounds[3] = shape->paths->bounds[3];
		for (path = shape->paths->next; path != NULL; path = path->next) {
			shape->bounds[0] = msvg__minf(shape->bounds[0], path->bounds[0]);
			shape->bounds[1] = msvg__minf(shape->bounds[1], path->bounds[1]);
			shape->bounds[2] = msvg__maxf(shape->bounds[2], path->bounds[2]);
			shape->bounds[3] = msvg__maxf(shape->bounds[3], path->bounds[3]);
		}
	}
}

// Builds the matrix that maps a pattern content shape's baked document-space
// coordinates into the pattern's content coordinate space. Content is never
// scaled by x/y/width/height here: patternContentUnits=objectBoundingBox
// content is expressed as fractions of the *referencing element's* bounding
// box (scaled into user space per-shape at tile-render time), and
// patternContentUnits=userSpaceOnUse content is in the user space in effect
// at the place of reference. The viewBox viewport (when present) maps content
// into the tile rectangle, and the inverse of the transform in effect at the
// <pattern> element strips the parser's baked-in ancestor transforms.
static void msvg__patternBakeTransform(MSVGpatternData* pat, float* out)
{
	msvg__xformIdentity(out);

	// viewBox viewport: map the viewBox rectangle into the tile rectangle
	// honoring preserveAspectRatio (default xMidYMid meet). The result is
	// TILE-RELATIVE: the tile bitmap's origin IS the tile rect origin
	// (sampling maps user point P to bitmap (P - tileOrigin)/tileSize),
	// so the viewBox corner maps to bitmap (0,0) — the T(x,y) tile-rect
	// translation is deliberately NOT applied here.
	// P_tile = S(s,s) * T(-vbx,-vby) * P_vb.
	if (pat->hasViewBox && pat->viewBox[2] > 0.0f && pat->viewBox[3] > 0.0f) {
		float vbw = pat->viewBox[2], vbh = pat->viewBox[3];
		float tw = pat->w.value, th = pat->h.value;
		float s = (pat->alignType == MSVG_ALIGN_SLICE)
			? msvg__maxf(tw / vbw, th / vbh)
			: msvg__minf(tw / vbw, th / vbh);
		float t[6];
		msvg__xformSetTranslation(t, -pat->viewBox[0], -pat->viewBox[1]);
		msvg__xformMultiply(out, t);
		msvg__xformSetScale(t, s, s);
		msvg__xformMultiply(out, t);
	}

	// Undo the transform in effect at the <pattern> element (the parser bakes
	// it into every content shape's coordinates).
	{
		float inv[6];
		msvg__xformInverse(inv, pat->baseXform);
		msvg__xformMultiply(out, inv);
	}
}

// Bakes the content of a pattern into pattern space. Called when the
// <pattern> element closes (all child shapes are already parsed).
static void msvg__bakePatternContent(MSVGpatternData* pat)
{
	MSVGshape* shape;
	float t[6];
	msvg__patternBakeTransform(pat, t);
	memcpy(pat->bakeXform, t, sizeof(float)*6);
	for (shape = pat->shapes; shape != NULL; shape = shape->next)
		msvg__transformShape(shape, t);
}

// Parses a <pattern> element: registers the paint server and its attributes.
// The element's transform context is captured so child shapes (which are
// baked into document space by the parser) can be rebased into pattern space
// when the element closes.
static void msvg__parsePattern(MSVGparser* p, const char** attr)
{
	int i;
	MSVGpatternData* pat = (MSVGpatternData*)malloc(sizeof(MSVGpatternData));
	if (pat == NULL) return;
	memset(pat, 0, sizeof(MSVGpatternData));
	pat->units = MSVG_OBJECT_SPACE;		// patternUnits default
	pat->contentUnits = MSVG_USER_SPACE;	// patternContentUnits default
	pat->x = msvg__coord(0.0f, MSVG_UNITS_PX);
	pat->y = msvg__coord(0.0f, MSVG_UNITS_PX);
	pat->w = msvg__coord(0.0f, MSVG_UNITS_PX);
	pat->h = msvg__coord(0.0f, MSVG_UNITS_PX);
	msvg__xformIdentity(pat->xform);
	pat->alignX = MSVG_ALIGN_MID;
	pat->alignY = MSVG_ALIGN_MID;
	pat->alignType = MSVG_ALIGN_MEET;
	memcpy(pat->baseXform, msvg__getAttr(p)->xform, sizeof(float) * 6);

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			strncpy(pat->id, attr[i + 1], 63);
			pat->id[63] = '\0';
		} else if (strcmp(attr[i], "x") == 0) {
			pat->x = msvg__parseCoordinateRaw(attr[i + 1]);
			pat->setMask |= MSVG_PATTERN_SET_X;
		} else if (strcmp(attr[i], "y") == 0) {
			pat->y = msvg__parseCoordinateRaw(attr[i + 1]);
			pat->setMask |= MSVG_PATTERN_SET_Y;
		} else if (strcmp(attr[i], "width") == 0) {
			pat->w = msvg__parseCoordinateRaw(attr[i + 1]);
			pat->setMask |= MSVG_PATTERN_SET_W;
		} else if (strcmp(attr[i], "height") == 0) {
			pat->h = msvg__parseCoordinateRaw(attr[i + 1]);
			pat->setMask |= MSVG_PATTERN_SET_H;
		} else if (strcmp(attr[i], "patternUnits") == 0) {
			pat->units = strcmp(attr[i + 1], "userSpaceOnUse") == 0
				? MSVG_USER_SPACE : MSVG_OBJECT_SPACE;
			pat->setMask |= MSVG_PATTERN_SET_UNITS;
		} else if (strcmp(attr[i], "patternContentUnits") == 0) {
			pat->contentUnits = strcmp(attr[i + 1], "objectBoundingBox") == 0
				? MSVG_OBJECT_SPACE : MSVG_USER_SPACE;
			pat->setMask |= MSVG_PATTERN_SET_CONTENT_UNITS;
		} else if (strcmp(attr[i], "patternTransform") == 0) {
			float xf[6];
			msvg__parseTransform(xf, attr[i + 1]);
			msvg__xformMultiply(pat->xform, xf);
			pat->setMask |= MSVG_PATTERN_SET_XFORM;
		} else if (strcmp(attr[i], "href") == 0 || strcmp(attr[i], "xlink:href") == 0) {
			const char* v = attr[i + 1];
			if (v[0] == '#')
				v++;
			strncpy(pat->ref, v, 63);
			pat->ref[63] = '\0';
		} else if (strcmp(attr[i], "viewBox") == 0) {
			const char* s = attr[i + 1];
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			pat->viewBox[0] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			pat->viewBox[1] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			pat->viewBox[2] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			pat->viewBox[3] = msvg__atof(buf);
			pat->hasViewBox = 1;
			pat->setMask |= MSVG_PATTERN_SET_VIEWBOX;
		} else if (strcmp(attr[i], "preserveAspectRatio") == 0) {
			if (msvg__parseAspectRatio(attr[i + 1], &pat->alignX, &pat->alignY, &pat->alignType))
				pat->setMask |= MSVG_PATTERN_SET_ALIGN;
		}
	}

	if (p->patternsTail)
		p->patternsTail->next = pat;
	else
		p->patterns = pat;
	p->patternsTail = pat;
}

// Parses a <clipPath> element: registers the template and its attributes.
// The transform context in effect at the element (baseXform) is captured so
// child shapes (whose coordinates the parser bakes into document space) can
// be rebased into the referencing element's user space when the element
// closes: content = clipTransform * inverse(baseXform) * document coords.
static void msvg__parseClip(MSVGparser* p, const char** attr)
{
	int i;
	MSVGclipData* clip = (MSVGclipData*)malloc(sizeof(MSVGclipData));
	if (clip == NULL) return;
	memset(clip, 0, sizeof(MSVGclipData));
	clip->elemSeq = p->ctx[p->ctxHead].seq;
	clip->units = MSVG_USER_SPACE;	// clipPathUnits default
	clip->animResolved = 0;
	clip->animBbox[0] = clip->animBbox[1] = -1.0f;
	msvg__xformIdentity(clip->bakeXform);
	{
		float base[6], inv[6];
		memcpy(base, msvg__getAttr(p)->xform, sizeof(float)*6);
		msvg__xformInverse(inv, base);
		msvg__xformMultiply(clip->bakeXform, inv);
	}

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			strncpy(clip->id, attr[i + 1], 63);
			clip->id[63] = '\0';
		} else if (strcmp(attr[i], "clipPathUnits") == 0) {
			clip->units = strcmp(attr[i + 1], "objectBoundingBox") == 0
				? MSVG_OBJECT_SPACE : MSVG_USER_SPACE;
		} else if (strcmp(attr[i], "transform") == 0) {
			float xf[6];
			msvg__parseTransform(xf, attr[i + 1]);
			msvg__xformMultiply(clip->bakeXform, xf);
		} else if (strcmp(attr[i], "clip-path") == 0) {
			/* CSS Masking §9.2: the clip-path property applies to <clipPath>
			   itself; the clip region becomes the intersection of the
			   element's own content with the referenced clip's region. */
			const char* v = attr[i + 1];
			if (strncmp(v, "url(#", 5) == 0) {
				const char* e = strchr(v + 5, ')');
				size_t len = e != NULL ? (size_t)(e - (v + 5)) : 0;
				if (len > 0 && len < sizeof clip->outerClipRef) {
					memcpy(clip->outerClipRef, v + 5, len);
					clip->outerClipRef[len] = '\0';
				}
			}
		} else if (strcmp(attr[i], "href") == 0 || strcmp(attr[i], "xlink:href") == 0) {
			const char* v = attr[i + 1];
			if (v[0] == '#')
				v++;
			strncpy(clip->ref, v, 63);
			clip->ref[63] = '\0';
		}
	}

	if (p->clipsTail)
		p->clipsTail->next = clip;
	else
		p->clips = clip;
	p->clipsTail = clip;
}

// Rebases a clip's content shapes into the referencing element's user space
// (or bbox-fraction space for objectBoundingBox). Called when the <clipPath>
// element closes (all child shapes are already parsed).
static void msvg__bakeClipContent(MSVGclipData* clip)
{
	MSVGshape* shape;
	for (shape = clip->shapes; shape != NULL; shape = shape->next)
		msvg__transformShape(shape, clip->bakeXform);
}

static MSVGclipData* msvg__findClipData(MSVGparser* p, const char* id)
{
	MSVGclipData* clip;
	if (id == NULL || id[0] == '\0')
		return NULL;
	for (clip = p->clips; clip != NULL; clip = clip->next)
		if (strcmp(clip->id, id) == 0)
			return clip;
	return NULL;
}

// Parses a <mask> element: registers the template and its attributes. Like
// <clipPath>, the transform context in effect at the element (baseXform) is
// captured so child shapes (baked into document space) can be rebased into
// the referencing element's user space when the element closes.
// Defaults per SVG 1.1: maskUnits=objectBoundingBox,
// maskContentUnits=userSpaceOnUse, x/y = -10%, w/h = 120%, mask-type=
// luminance.
static void msvg__parseMask(MSVGparser* p, const char** attr)
{
	int i;
	MSVGmaskData* mask = (MSVGmaskData*)malloc(sizeof(MSVGmaskData));
	if (mask == NULL) return;
	memset(mask, 0, sizeof(MSVGmaskData));
	mask->units = MSVG_OBJECT_SPACE;	// maskUnits default
	mask->contentUnits = MSVG_USER_SPACE;	// maskContentUnits default
	mask->maskType = MSVG_MASK_LUMINANCE;	// mask-type default
	mask->x = msvg__coord(-10.0f, MSVG_UNITS_PERCENT);
	mask->y = msvg__coord(-10.0f, MSVG_UNITS_PERCENT);
	mask->w = msvg__coord(120.0f, MSVG_UNITS_PERCENT);
	mask->h = msvg__coord(120.0f, MSVG_UNITS_PERCENT);
	msvg__xformIdentity(mask->bakeXform);
	{
		float base[6], inv[6];
		memcpy(base, msvg__getAttr(p)->xform, sizeof(float)*6);
		msvg__xformInverse(inv, base);
		msvg__xformMultiply(mask->bakeXform, inv);
	}

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			strncpy(mask->id, attr[i + 1], 63);
			mask->id[63] = '\0';
		} else if (strcmp(attr[i], "x") == 0) {
			mask->x = msvg__parseCoordinateRaw(attr[i + 1]);
		} else if (strcmp(attr[i], "y") == 0) {
			mask->y = msvg__parseCoordinateRaw(attr[i + 1]);
		} else if (strcmp(attr[i], "width") == 0) {
			mask->w = msvg__parseCoordinateRaw(attr[i + 1]);
		} else if (strcmp(attr[i], "height") == 0) {
			mask->h = msvg__parseCoordinateRaw(attr[i + 1]);
		} else if (strcmp(attr[i], "maskUnits") == 0) {
			mask->units = strcmp(attr[i + 1], "userSpaceOnUse") == 0
				? MSVG_USER_SPACE : MSVG_OBJECT_SPACE;
		} else if (strcmp(attr[i], "maskContentUnits") == 0) {
			mask->contentUnits = strcmp(attr[i + 1], "objectBoundingBox") == 0
				? MSVG_OBJECT_SPACE : MSVG_USER_SPACE;
		} else if (strcmp(attr[i], "mask-type") == 0) {
			mask->maskType = strcmp(attr[i + 1], "alpha") == 0
				? MSVG_MASK_ALPHA : MSVG_MASK_LUMINANCE;
		} else if (strcmp(attr[i], "clip-path") == 0) {
			/* CSS Masking §9.2: clip-path on the <mask> element itself —
			   the mask's effect is intersected with the referenced clip. */
			const char* v = attr[i + 1];
			if (strncmp(v, "url(#", 5) == 0) {
				const char* e = strchr(v + 5, ')');
				size_t len = e != NULL ? (size_t)(e - (v + 5)) : 0;
				if (len > 0 && len < sizeof mask->outerClipRef) {
					memcpy(mask->outerClipRef, v + 5, len);
					mask->outerClipRef[len] = '\0';
				}
			}
		} else if (strcmp(attr[i], "transform") == 0) {
			float xf[6];
			msvg__parseTransform(xf, attr[i + 1]);
			msvg__xformMultiply(mask->bakeXform, xf);
		} else if (strcmp(attr[i], "href") == 0 || strcmp(attr[i], "xlink:href") == 0) {
			const char* v = attr[i + 1];
			if (v[0] == '#')
				v++;
			strncpy(mask->ref, v, 63);
			mask->ref[63] = '\0';
		}
	}

	if (p->masksTail)
		p->masksTail->next = mask;
	else
		p->masks = mask;
	p->masksTail = mask;
}

// Rebases a mask's content shapes into the referencing element's user space
// (or bbox-fraction space for objectBoundingBox content). Called when the
// <mask> element closes (all child shapes are already parsed).
static void msvg__bakeMaskContent(MSVGmaskData* mask)
{
	MSVGshape* shape;
	for (shape = mask->shapes; shape != NULL; shape = shape->next)
		msvg__transformShape(shape, mask->bakeXform);
	/* The <mask> element's own clip-path property (CSS Masking §9.2)
	   applies in the mask's USER coordinate system — the coordinate system
	   in effect for the element referencing this mask. Record the composed
	   transform (like msvg__bakeClipContent) so the intersection gate can
	   map the outer clip's region into referencing user space. */
}

static MSVGmaskData* msvg__findMaskData(MSVGparser* p, const char* id)
{
	MSVGmaskData* mask;
	if (id == NULL || id[0] == '\0')
		return NULL;
	for (mask = p->masks; mask != NULL; mask = mask->next)
		if (strcmp(mask->id, id) == 0)
			return mask;
	return NULL;
}

/* ------------------------------------------------------------------ */
/* Filter parsing (CSS Filter Effects 1)                              */
/* ------------------------------------------------------------------ */

static MSVGfilterData* msvg__findFilterData(MSVGparser* p, const char* id)
{
	MSVGfilterData* f;
	if (id == NULL || id[0] == '\0')
		return NULL;
	for (f = p->filters; f != NULL; f = f->next)
		if (strcmp(f->id, id) == 0)
			return f;
	return NULL;
}

// Parses a <filter> element: registers the template and its attributes.
// The filter region defaults to -10%/-10%/120%/120% of the referencing
// element's bounding box (filterUnits=objectBoundingBox default).
static void msvg__parseFilter(MSVGparser* p, const char** attr)
{
	int i;
	MSVGfilterData* f = (MSVGfilterData*)malloc(sizeof(MSVGfilterData));
	if (f == NULL) return;
	memset(f, 0, sizeof(MSVGfilterData));
	f->units = MSVG_OBJECT_SPACE;		// filterUnits default
	f->primitiveUnits = MSVG_USER_SPACE;	// primitiveUnits default
	f->x = msvg__coord(-10.0f, MSVG_UNITS_PERCENT);
	f->y = msvg__coord(-10.0f, MSVG_UNITS_PERCENT);
	f->w = msvg__coord(120.0f, MSVG_UNITS_PERCENT);
	f->h = msvg__coord(120.0f, MSVG_UNITS_PERCENT);

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			strncpy(f->id, attr[i + 1], 63);
			f->id[63] = '\0';
		} else if (strcmp(attr[i], "href") == 0 || strcmp(attr[i], "xlink:href") == 0) {
			const char* v = attr[i + 1];
			if (v[0] == '#')
				v++;
			strncpy(f->ref, v, 63);
			f->ref[63] = '\0';
		} else if (strcmp(attr[i], "filterUnits") == 0) {
			f->units = strcmp(attr[i + 1], "userSpaceOnUse") == 0
				? MSVG_USER_SPACE : MSVG_OBJECT_SPACE;
			f->setMask |= MSVG_FILTER_SET_UNITS;
		} else if (strcmp(attr[i], "primitiveUnits") == 0) {
			f->primitiveUnits = strcmp(attr[i + 1], "objectBoundingBox") == 0
				? MSVG_OBJECT_SPACE : MSVG_USER_SPACE;
			f->setMask |= MSVG_FILTER_SET_PUNITS;
		} else if (strcmp(attr[i], "x") == 0) {
			f->x = msvg__parseCoordinateRaw(attr[i + 1]);
			f->setMask |= MSVG_FILTER_SET_X;
		} else if (strcmp(attr[i], "y") == 0) {
			f->y = msvg__parseCoordinateRaw(attr[i + 1]);
			f->setMask |= MSVG_FILTER_SET_Y;
		} else if (strcmp(attr[i], "width") == 0) {
			f->w = msvg__parseCoordinateRaw(attr[i + 1]);
			f->setMask |= MSVG_FILTER_SET_W;
		} else if (strcmp(attr[i], "height") == 0) {
			f->h = msvg__parseCoordinateRaw(attr[i + 1]);
			f->setMask |= MSVG_FILTER_SET_H;
		}
	}

	if (p->filtersTail)
		p->filtersTail->next = f;
	else
		p->filters = f;
	p->filtersTail = f;
}

// Parses an 'in'/'in2' attribute value. Returns the input kind; for named
// results the name is copied into 'name' (resolved to an index in
// resolveFilters) and the kind is MSVG_FILTER_IN_RESULT.
static char msvg__parseFilterInput(const char* value, char* name, int nameSize)
{
	name[0] = '\0';
	if (value == NULL || value[0] == '\0')
		return MSVG_FILTER_IN_SOURCE_GRAPHIC;
	if (strcmp(value, "SourceGraphic") == 0)
		return MSVG_FILTER_IN_SOURCE_GRAPHIC;
	if (strcmp(value, "SourceAlpha") == 0)
		return MSVG_FILTER_IN_SOURCE_ALPHA;
	if (strcmp(value, "BackgroundImage") == 0)
		return MSVG_FILTER_IN_BACKGROUND_IMAGE;
	if (strcmp(value, "BackgroundAlpha") == 0)
		return MSVG_FILTER_IN_BACKGROUND_ALPHA;
	if (strcmp(value, "FillPaint") == 0)
		return MSVG_FILTER_IN_FILL_PAINT;
	if (strcmp(value, "StrokePaint") == 0)
		return MSVG_FILTER_IN_STROKE_PAINT;
	strncpy(name, value, nameSize - 1);
	name[nameSize - 1] = '\0';
	return MSVG_FILTER_IN_RESULT;
}

/* ---- xml:base (XML Base, SVG 1.1 §5.10.1) --------------------------------
   xml:base was removed in SVG 2 but remains a core attribute for SVG 1.1
   backward compatibility. Per XML Base, the base URI of an element is its
   own xml:base value resolved against its parent's base URI, recursively,
   with the document URI at the root. The document base is supplied by the
   application (the image loader resolves final relative paths against the
   document directory); here we fold only the xml:base chain. */

// True if 's' is an absolute URI reference ("scheme:"), e.g. "data:",
// "file:", "http:".
static int msvg__hasScheme(const char* s)
{
	int i;
	if (s == NULL || !((s[0] >= 'a' && s[0] <= 'z') || (s[0] >= 'A' && s[0] <= 'Z')))
		return 0;
	for (i = 1; s[i] != '\0'; i++) {
		char c = s[i];
		if (c == ':')
			return 1;
		if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			  (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.'))
			return 0;
	}
	return 0;
}

// Resolves the URI reference 'rel' against base 'base', writing the result
// into 'out' (always NUL-terminated, truncated to outsz). Absolute
// references (scheme:, /path, #fragment) and references with no base
// resolve to themselves. A relative reference merges with base up to its
// last '/' (base with no separator is treated as a directory). The result
// is passed to the image loader as-is: the loader prepends the document
// directory when the result is still relative, and the OS filesystem
// resolves any "."/".." segments.
static void msvg__resolveURIRef(const char* rel, const char* base, char* out, size_t outsz)
{
	size_t blen, keep;
	char* slash;
	if (outsz == 0)
		return;
	out[0] = '\0';
	if (rel == NULL || rel[0] == '\0')
		return;
	if (rel[0] == '/' || rel[0] == '#' || msvg__hasScheme(rel) ||
		base == NULL || base[0] == '\0') {
		snprintf(out, outsz, "%s", rel);
		return;
	}
	blen = strlen(base);
	if (blen >= outsz) blen = outsz - 1;
	memcpy(out, base, blen);
	out[blen] = '\0';
	slash = strrchr(out, '/');
	if (slash != NULL) {
		keep = (size_t)(slash - out) + 1;	// up to and including last '/'
	} else {
		/* base has no path separator: treat it as a directory */
		if (blen + 1 < outsz) {
			out[blen] = '/';
			out[blen + 1] = '\0';
			keep = blen + 1;
		} else {
			keep = blen;
		}
	}
	snprintf(out + keep, outsz - keep, "%s", rel);
}

// Folds the xml:base chain of the element at context level 'level' into
// 'out': each ancestor/own xml:base value is resolved against the folded
// base of the element above it. An absolute value resets the chain. The
// document base is NOT part of the fold (the loader adds it later).
static void msvg__foldXmlBase(const MSVGparser* p, int level, char* out, size_t outsz)
{
	char bufA[2048], bufB[2048];
	const char* base = "";
	char* cur = bufA;
	int i;
	bufA[0] = bufB[0] = '\0';
	if (outsz == 0)
		return;
	out[0] = '\0';
	for (i = 1; i <= level && i < MSVG_MAX_ATTR; i++) {
		if (p->xmlBaseStack[i] == NULL || p->xmlBaseStack[i][0] == '\0')
			continue;
		msvg__resolveURIRef(p->xmlBaseStack[i], base, cur, 2048);
		base = cur;
		cur = (cur == bufA) ? bufB : bufA;
	}
	snprintf(out, outsz, "%s", base);
}

// Resolves 'href' against the effective xml:base chain of the element
// currently being parsed (p->ctxHead). Writes into 'out'.
static void msvg__resolveXmlBaseHref(const MSVGparser* p, const char* href, char* out, size_t outsz)
{
	char folded[2048];
	msvg__foldXmlBase(p, p->ctxHead, folded, sizeof(folded));
	msvg__resolveURIRef(href, folded, out, outsz);
}

// <style type="..."> gate (SVG 1.1 §6.4 / SVG 2 §CSS-Links): the element's
// style language defaults to text/css; any other declared type means the
// content is NOT CSS and must be ignored. Case-insensitive per the CSS
// media-type registry. NULL/empty type -> CSS.
static int msvg__styleTypeOk(const char** attr)
{
	int i;
	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "type") == 0) {
			const char* v = attr[i + 1];
			char buf[64];
			size_t n = 0;
			while (v[n] && n < sizeof(buf) - 1) {
				char c = v[n];
				if (c >= 'A' && c <= 'Z') c = (char)(c + 32);
				buf[n++] = c;
			}
			buf[n] = 0;
			/* Leading parameters (charset=...) may precede — compare the
			   media type proper, then require no non-parameter junk. */
			return strncmp(buf, "text/css", 8) == 0 &&
				   (buf[8] == '\0' || buf[8] == ';');
		}
	}
	return 1;
}

// Parses a common filter primitive subregion attribute (x/y/width/height).
static void msvg__parseSubRegion(MSVGfilterPrimitive* prim, const char* name,
								 const char* value)
{
	if (strcmp(name, "x") == 0) {
		prim->sx = msvg__parseCoordinateRaw(value);
		prim->hasSub = 1;
		prim->hasSubX = 1;
	} else if (strcmp(name, "y") == 0) {
		prim->sy = msvg__parseCoordinateRaw(value);
		prim->hasSub = 1;
		prim->hasSubY = 1;
	} else if (strcmp(name, "width") == 0) {
		prim->sw = msvg__parseCoordinateRaw(value);
		prim->hasSub = 1;
		prim->hasSubW = 1;
	} else if (strcmp(name, "height") == 0) {
		prim->sh = msvg__parseCoordinateRaw(value);
		prim->hasSub = 1;
		prim->hasSubH = 1;
	}
}

// Parses one filter primitive element (fe* child of <filter>) and appends it
// to the current filter's primitive list. 'el' is the element name.
static void msvg__parseFilterPrimitive(MSVGparser* p, const char* el,
									   const char** attr)
{
	MSVGfilterData* f = p->curFilter;
	MSVGfilterPrimitive* prim;
	int i;
	if (f == NULL)
		return;

	prim = (MSVGfilterPrimitive*)malloc(sizeof(MSVGfilterPrimitive));
	if (prim == NULL)
		return;
	memset(prim, 0, sizeof(MSVGfilterPrimitive));
	prim->elemSeq = (p->ctxHead >= 0) ? p->ctx[p->ctxHead].seq : -1;
	prim->type = MSVG_FILTER_GAUSSIAN_BLUR;	// set below
	prim->in = MSVG_FILTER_IN_SOURCE_GRAPHIC;
	prim->in2 = MSVG_FILTER_IN_SOURCE_GRAPHIC;
	prim->inRef = -1;
	prim->in2Ref = -1;
	prim->targetX = -1;
	prim->targetY = -1;
	prim->surfaceScale = 1.0f;
	prim->diffuseConstant = 1.0f;
	prim->specularConstant = 1.0f;
	prim->specularExponent = 1.0f;
	prim->light.limitingConeAngle = 0.0f;
	prim->light.hasLimitingCone = 0;
	prim->light.elemSeq = -1;	/* no limiting cone (§15.23 default) */
	prim->numOctaves = 1;
	prim->baseFreqX = prim->baseFreqY = 0.0f;
	prim->light.type = MSVG_LIGHT_DISTANT;
	prim->light.azimuth = 0.0f;
	prim->light.elevation = 0.0f;
	prim->light.x = prim->light.y = prim->light.z = 0.0f;
	prim->light.specularExponent = 1.0f;
	prim->light.limitingConeAngle = -1.0f;
	prim->lightColor = 0x00ffffff;	// lighting-color default white
	prim->edgeMode = 0;	// duplicate

	if (strcmp(el, "feGaussianBlur") == 0)
		prim->type = MSVG_FILTER_GAUSSIAN_BLUR;
	else if (strcmp(el, "feOffset") == 0)
		prim->type = MSVG_FILTER_OFFSET;
	else if (strcmp(el, "feColorMatrix") == 0) {
		prim->type = MSVG_FILTER_COLOR_MATRIX;
		/* identity matrix default */
		prim->colorMatrix[0]=1; prim->colorMatrix[5]=1;
		prim->colorMatrix[10]=1; prim->colorMatrix[15]=1;
	} else if (strcmp(el, "feBlend") == 0)
		prim->type = MSVG_FILTER_BLEND;
	else if (strcmp(el, "feComposite") == 0)
		prim->type = MSVG_FILTER_COMPOSITE;
	else if (strcmp(el, "feMerge") == 0)
		prim->type = MSVG_FILTER_MERGE;
	else if (strcmp(el, "feFlood") == 0) {
		prim->type = MSVG_FILTER_FLOOD;
		prim->floodColor = 0xff000000;	// default black, opaque
		prim->floodOpacity = 1.0f;
	} else if (strcmp(el, "feTile") == 0)
		prim->type = MSVG_FILTER_TILE;
	else if (strcmp(el, "feMorphology") == 0)
		prim->type = MSVG_FILTER_MORPHOLOGY;
	else if (strcmp(el, "feComponentTransfer") == 0)
		prim->type = MSVG_FILTER_COMPONENT_TRANSFER;
	else if (strcmp(el, "feDropShadow") == 0) {
		prim->type = MSVG_FILTER_DROP_SHADOW;
		prim->floodColor = 0xff000000;
		prim->floodOpacity = 1.0f;
	} else if (strcmp(el, "feDisplacementMap") == 0) {
		prim->type = MSVG_FILTER_DISPLACEMENT_MAP;
		prim->xChannel = 0;	// R
		prim->yChannel = 1;	// G
	} else if (strcmp(el, "feTurbulence") == 0)
		prim->type = MSVG_FILTER_TURBULENCE;
	else if (strcmp(el, "feImage") == 0) {
		prim->type = MSVG_FILTER_IMAGE;
		/* preserveAspectRatio defaults to xMidYMid meet (SVG 2 §5.11.1).
		   imageAlignType 0 is MSVG_ALIGN_NONE (non-uniform stretch);
		   without these defaults an feImage with no preserveAspectRatio
		   attribute would stretch instead of meet-scale. */
		prim->imageAlignX = MSVG_ALIGN_MID;
		prim->imageAlignY = MSVG_ALIGN_MID;
		prim->imageAlignType = MSVG_ALIGN_MEET;
	}
	else if (strcmp(el, "feDiffuseLighting") == 0)
		prim->type = MSVG_FILTER_DIFFUSE_LIGHTING;
	else if (strcmp(el, "feSpecularLighting") == 0)
		prim->type = MSVG_FILTER_SPECULAR_LIGHTING;
	else if (strcmp(el, "feConvolveMatrix") == 0) {
		prim->type = MSVG_FILTER_CONVOLVE_MATRIX;
		/* SVG 1.1 §15.13.2: default 'order' is 3 (a 3x3 kernel).
		   The attribute, when present, overrides this. */
		prim->orderX = 3;
		prim->orderY = 3;
	}
	else {
		free(prim);
		return;
	}

	for (i = 0; attr[i]; i += 2) {
		const char* name = attr[i];
		const char* value = attr[i + 1];
		if (strcmp(name, "in") == 0) {
			prim->in = msvg__parseFilterInput(value, prim->inName,
										  (int)sizeof(prim->inName));
			prim->inSet = 1;
		} else if (strcmp(name, "in2") == 0) {
			prim->in2 = msvg__parseFilterInput(value, prim->in2Name,
										   (int)sizeof(prim->in2Name));
			prim->in2Set = 1;
		} else if (strcmp(name, "result") == 0) {
			strncpy(prim->result, value, sizeof(prim->result) - 1);
		} else if (strcmp(name, "x") == 0 || strcmp(name, "y") == 0 ||
				   strcmp(name, "width") == 0 || strcmp(name, "height") == 0) {
			msvg__parseSubRegion(prim, name, value);
		} else if (strcmp(name, "stdDeviation") == 0) {
			const char* s = value;
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			prim->stdDevX = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == ',')) s++;
			if (*s) {
				s = msvg__parseNumber(s, buf, 64);
				prim->stdDevY = msvg__atof(buf);
			} else {
				prim->stdDevY = prim->stdDevX;
			}
		} else if (strcmp(name, "dx") == 0) {
			prim->dx = msvg__atof(value);
		} else if (strcmp(name, "dy") == 0) {
			prim->dy = msvg__atof(value);
		} else if (strcmp(name, "flood-color") == 0 || strcmp(name, "flood_color") == 0) {
			int ok = 0;
			unsigned int c;
			if (strcmp(value, "currentColor") == 0 || strcmp(value, "currentcolor") == 0) {
				c = msvg__getAttr(p)->color;
				prim->floodColor = (c & 0x00ffffff) | 0xff000000;
			} else {
				c = msvg__parseColorFull(value, &ok);
				prim->floodColor = ok ? c : 0xff000000;
			}
		} else if (strcmp(name, "flood-opacity") == 0 || strcmp(name, "flood_opacity") == 0) {
			prim->floodOpacity = msvg__parseOpacity(value);
		} else if (strcmp(name, "mode") == 0) {
			prim->blendMode = (char)msvg__parseBlendMode(value);
		} else if (strcmp(name, "operator") == 0) {
			if (prim->type == MSVG_FILTER_MORPHOLOGY) {
				prim->morphOp = (char)(strcmp(value, "dilate") == 0);
			} else if (strcmp(value, "in") == 0) prim->compositeOp = 1;
			else if (strcmp(value, "out") == 0) prim->compositeOp = 2;
			else if (strcmp(value, "atop") == 0) prim->compositeOp = 3;
			else if (strcmp(value, "xor") == 0) prim->compositeOp = 4;
			else if (strcmp(value, "lighter") == 0) prim->compositeOp = 5;
			else if (strcmp(value, "arithmetic") == 0) prim->compositeOp = 6;
			else prim->compositeOp = 0;	// over
		} else if (strcmp(name, "k1") == 0) {
			prim->k1 = msvg__atof(value);
		} else if (strcmp(name, "k2") == 0) {
			prim->k2 = msvg__atof(value);
		} else if (strcmp(name, "k3") == 0) {
			prim->k3 = msvg__atof(value);
		} else if (strcmp(name, "k4") == 0) {
			prim->k4 = msvg__atof(value);
		} else if (strcmp(name, "type") == 0) {
			if (prim->type == MSVG_FILTER_COLOR_MATRIX) {
				if (strcmp(value, "saturate") == 0) prim->colorMatrixType = 1;
				else if (strcmp(value, "hueRotate") == 0) prim->colorMatrixType = 2;
				else if (strcmp(value, "luminanceToAlpha") == 0) prim->colorMatrixType = 3;
				else prim->colorMatrixType = 0;
			} else if (prim->type == MSVG_FILTER_TURBULENCE) {
				prim->turbType = (char)(strcmp(value, "turbulence") == 0);
			} else if (prim->type == MSVG_FILTER_MORPHOLOGY) {
				prim->morphOp = (char)(strcmp(value, "dilate") == 0);
			}
		} else if (strcmp(name, "values") == 0) {
			if (prim->type == MSVG_FILTER_COLOR_MATRIX) {
				if (prim->colorMatrixType == 0) {
					/* 20 matrix values */
					int k = 0;
					const char* s = value;
					char buf[64];
					while (k < 20) {
						while (*s && (msvg__isspace(*s) || *s == ',')) s++;
						if (!*s) break;
						s = msvg__parseNumber(s, buf, 64);
						prim->colorMatrix[k++] = msvg__atof(buf);
					}
				} else if (prim->colorMatrixType == 1) {
					prim->saturate = msvg__atof(value);
				} else if (prim->colorMatrixType == 2) {
					prim->saturate = msvg__atof(value);	// hueRotate angle (degrees)
				}
			}
		} else if (strcmp(name, "radius") == 0) {
			const char* s = value;
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			prim->morphRX = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == ',')) s++;
			if (*s) {
				s = msvg__parseNumber(s, buf, 64);
				prim->morphRY = msvg__atof(buf);
			} else {
				prim->morphRY = prim->morphRX;
			}
		} else if (strcmp(name, "scale") == 0) {
			prim->dispScale = msvg__atof(value);
		} else if (strcmp(name, "xChannelSelector") == 0) {
			prim->xChannel = (char)(value[0] == 'R' ? 0 : value[0] == 'G' ? 1
				: value[0] == 'B' ? 2 : 3);
		} else if (strcmp(name, "yChannelSelector") == 0) {
			prim->yChannel = (char)(value[0] == 'R' ? 0 : value[0] == 'G' ? 1
				: value[0] == 'B' ? 2 : 3);
		} else if (strcmp(name, "baseFrequency") == 0) {
			const char* s = value;
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			prim->baseFreqX = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == ',')) s++;
			if (*s) {
				s = msvg__parseNumber(s, buf, 64);
				prim->baseFreqY = msvg__atof(buf);
			} else {
				prim->baseFreqY = prim->baseFreqX;
			}
		} else if (strcmp(name, "numOctaves") == 0) {
			prim->numOctaves = (int)msvg__atof(value);
		} else if (strcmp(name, "seed") == 0) {
			prim->seed = (int)msvg__atof(value);
		} else if (strcmp(name, "stitchTiles") == 0) {
			prim->stitchTiles = (char)(strcmp(value, "stitch") == 0);
		} else if (strcmp(name, "surfaceScale") == 0) {
			prim->surfaceScale = msvg__atof(value);
		} else if (strcmp(name, "diffuseConstant") == 0) {
			prim->diffuseConstant = msvg__atof(value);
		} else if (strcmp(name, "specularConstant") == 0) {
			prim->specularConstant = msvg__atof(value);
		} else if (strcmp(name, "specularExponent") == 0) {
			prim->specularExponent = msvg__atof(value);
		} else if (strcmp(name, "lighting-color") == 0 || strcmp(name, "lighting_color") == 0) {
			int ok = 0;
			unsigned int c;
			/* 'currentColor' resolves against the inherited 'color'
			   property (SVG 1.1 §11.2: lighting-color takes <color>,
			   currentColor = computed value of 'color' on the
			   primitive; the <defs color="#0f0"> ancestor supplies
			   it — filters-light-05-f). */
			if (strcmp(value, "currentColor") == 0 || strcmp(value, "currentcolor") == 0) {
				c = msvg__getAttr(p)->color;
				prim->lightColor = c & 0x00ffffff;
			} else {
				c = msvg__parseColorFull(value, &ok);
				prim->lightColor = ok ? (c & 0x00ffffff) : 0x00ffffff;
			}
		} else if (strcmp(name, "kernelUnitLength") == 0) {
			const char* s = value;
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			prim->kernelUnitLengthX = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == ',')) s++;
			if (*s) {
				s = msvg__parseNumber(s, buf, 64);
				prim->kernelUnitLengthY = msvg__atof(buf);
			} else {
				prim->kernelUnitLengthY = prim->kernelUnitLengthX;
			}
		} else if (strcmp(name, "order") == 0) {
			const char* s = value;
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			prim->orderX = (int)msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == ',')) s++;
			if (*s) {
				s = msvg__parseNumber(s, buf, 64);
				prim->orderY = (int)msvg__atof(buf);
			} else {
				prim->orderY = prim->orderX;
			}
		} else if (strcmp(name, "kernelMatrix") == 0) {
			const char* s = value;
			char buf[64];
			int cap = 0, n = 0;
			float* k = NULL;
			while (*s) {
				while (*s && (msvg__isspace(*s) || *s == ',')) s++;
				if (!*s) break;
				s = msvg__parseNumber(s, buf, 64);
				if (n >= cap) {
					cap = cap ? cap * 2 : 16;
					k = (float*)realloc(k, (size_t)cap * sizeof(float));
					if (k == NULL) break;
				}
				k[n++] = msvg__atof(buf);
			}
			prim->kernel = k;
			prim->divisor = 0.0f;	// default divisor = kernel sum (set later)
		} else if (strcmp(name, "divisor") == 0) {
			prim->divisor = msvg__atof(value);
		} else if (strcmp(name, "bias") == 0) {
			prim->bias = msvg__atof(value);
		} else if (strcmp(name, "targetX") == 0) {
			prim->targetX = (int)msvg__atof(value);
		} else if (strcmp(name, "targetY") == 0) {
			prim->targetY = (int)msvg__atof(value);
		} else if (strcmp(name, "edgeMode") == 0) {
			if (strcmp(value, "wrap") == 0) prim->edgeMode = 1;
			else if (strcmp(value, "none") == 0) prim->edgeMode = 2;
			else prim->edgeMode = 0;
		} else if (strcmp(name, "preserveAlpha") == 0) {
			prim->preserveAlpha = (char)(strcmp(value, "true") == 0);
		} else if (strcmp(name, "href") == 0 || strcmp(name, "xlink:href") == 0) {
			if (prim->type == MSVG_FILTER_IMAGE) {
				/* Resolve against the element's effective xml:base chain
				   (SVG 1.1 §5.10.1); the loader adds the document base. */
				char hrefbuf[2048];
				msvg__resolveXmlBaseHref(p, value, hrefbuf, sizeof(hrefbuf));
				strncpy(prim->imageHref, hrefbuf, sizeof(prim->imageHref) - 1);
				prim->imageHref[sizeof(prim->imageHref) - 1] = '\0';
				/* Same-document fragment reference: feImage renders the
				   referenced SVG ELEMENT (§15.8.1) rather than a raster
				   file. Record the bare id; resolveFilterFeImages
				   pre-rasterizes it after the document is fully parsed. */
				if (value[0] == '#') {
					strncpy(prim->feImageFrag, value + 1, sizeof(prim->feImageFrag) - 1);
					prim->feImageFrag[sizeof(prim->feImageFrag) - 1] = '\0';
				} else {
					const char* frag = strchr(value, '#');
					if (frag != NULL && strncmp(value, "data:", 5) != 0) {
						strncpy(prim->feImageFrag, frag + 1, sizeof(prim->feImageFrag) - 1);
						prim->feImageFrag[sizeof(prim->feImageFrag) - 1] = '\0';
					}
				}
			}
		} else if (strcmp(name, "preserveAspectRatio") == 0) {
			if (prim->type == MSVG_FILTER_IMAGE) {
				int ax = prim->imageAlignX, ay = prim->imageAlignY, at = prim->imageAlignType;
				if (msvg__parseAspectRatio(value, &ax, &ay, &at)) {
					prim->imageAlignX = (char)ax;
					prim->imageAlignY = (char)ay;
					prim->imageAlignType = (char)at;
				}
			}
		} else if (strcmp(name, "azimuth") == 0) {
			prim->light.azimuth = msvg__atof(value);
		} else if (strcmp(name, "elevation") == 0) {
			prim->light.elevation = msvg__atof(value);
		} else if (strcmp(name, "pointsAtX") == 0) {
			prim->light.pointsAtX = msvg__atof(value);
		} else if (strcmp(name, "pointsAtY") == 0) {
			prim->light.pointsAtY = msvg__atof(value);
		} else if (strcmp(name, "pointsAtZ") == 0) {
			prim->light.pointsAtZ = msvg__atof(value);
		} else if (strcmp(name, "limitingConeAngle") == 0) {
			prim->light.limitingConeAngle = msvg__atof(value);
			prim->light.hasLimitingCone = 1;
		} else if (strcmp(name, "id") == 0) {
			/* ignore (primitives don't need ids for rendering) */
		}
	}

	/* Adjust defaults that depend on other attributes. */
	if (prim->type == MSVG_FILTER_CONVOLVE_MATRIX) {
		/* divisor default = sum of kernel values (0 if sum is 0) */
		float sum = 0.0f;
		int n = prim->orderX * prim->orderY;
		int k;
		if (prim->kernel == NULL)
			prim->divisor = 0.0f;
		else if (prim->divisor == 0.0f || (prim->kernel[0] == 0.0f && n == 0)) {
			/* divisor defaults to the sum when 'divisor' was not given
			   (0.0 default); recompute only when not explicitly set */
		}
		for (k = 0; k < n && prim->kernel != NULL; k++)
			sum += prim->kernel[k];
		if (prim->kernel != NULL && sum == 0.0f)
			sum = 1.0f;
		if (prim->divisor == 0.0f)
			prim->divisor = sum;
	}

	if (f->primitivesTail)
		f->primitivesTail->next = prim;
	else
		f->primitives = prim;
	f->primitivesTail = prim;
}

// Parses a feMergeNode / feFuncR/G/B/A / light source child element. These
// modify the current primitive (p->curPrim).
static void msvg__parseFilterChild(MSVGparser* p, const char* el,
								   const char** attr)
{
	MSVGfilterPrimitive* prim = p->curPrim;
	int i;
	if (prim == NULL)
		return;

	if (strcmp(el, "feMergeNode") == 0) {
		if (prim->nMerge < 16) {
			MSVGfilterChild* c = &prim->mergeNodes[prim->nMerge++];
			memset(c, 0, sizeof(*c));
			c->in = MSVG_FILTER_IN_SOURCE_GRAPHIC;
			c->inRef = -1;
			for (i = 0; attr[i]; i += 2)
				if (strcmp(attr[i], "in") == 0)
					c->in = msvg__parseFilterInput(attr[i + 1], c->inName,
												  (int)sizeof(c->inName));
		}
	} else if (strcmp(el, "feFuncR") == 0 || strcmp(el, "feFuncG") == 0 ||
			   strcmp(el, "feFuncB") == 0 || strcmp(el, "feFuncA") == 0) {
		int ci = (el[6] == 'R') ? 0 : (el[6] == 'G') ? 1 : (el[6] == 'B') ? 2 : 3;
		MSVGtransferFunc* fn = &prim->funcs[ci];
		for (i = 0; attr[i]; i += 2) {
			const char* name = attr[i];
			const char* value = attr[i + 1];
			if (strcmp(name, "type") == 0) {
				if (strcmp(value, "table") == 0) fn->type = 1;
				else if (strcmp(value, "discrete") == 0) fn->type = 2;
				else if (strcmp(value, "linear") == 0) fn->type = 3;
				else if (strcmp(value, "gamma") == 0) fn->type = 4;
				else fn->type = 0;	// identity
			} else if (strcmp(name, "tableValues") == 0) {
				const char* s = value;
				char buf[64];
				int cap = 0, n = 0;
				float* t = NULL;
				while (*s) {
					while (*s && (msvg__isspace(*s) || *s == ',')) s++;
					if (!*s) break;
					s = msvg__parseNumber(s, buf, 64);
					if (n >= cap) {
						cap = cap ? cap * 2 : 8;
						t = (float*)realloc(t, (size_t)cap * sizeof(float));
						if (t == NULL) break;
					}
					t[n++] = msvg__atof(buf);
				}
				if (fn->table) free(fn->table);
				fn->table = t;
				fn->ntable = n;
			} else if (strcmp(name, "slope") == 0) {
				fn->slope = msvg__atof(value);
			} else if (strcmp(name, "intercept") == 0) {
				fn->intercept = msvg__atof(value);
			} else if (strcmp(name, "amplitude") == 0) {
				fn->amplitude = msvg__atof(value);
			} else if (strcmp(name, "exponent") == 0) {
				fn->exponent = msvg__atof(value);
			} else if (strcmp(name, "offset") == 0) {
				fn->offset = msvg__atof(value);
			}
		}
	} else if (strcmp(el, "feDistantLight") == 0) {
		prim->light.type = MSVG_LIGHT_DISTANT;
		for (i = 0; attr[i]; i += 2) {
			if (strcmp(attr[i], "azimuth") == 0)
				prim->light.azimuth = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "elevation") == 0)
				prim->light.elevation = msvg__atof(attr[i + 1]);
		}
	} else if (strcmp(el, "fePointLight") == 0) {
		prim->light.type = MSVG_LIGHT_POINT;
		for (i = 0; attr[i]; i += 2) {
			if (strcmp(attr[i], "x") == 0) prim->light.x = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "y") == 0) prim->light.y = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "z") == 0) prim->light.z = msvg__atof(attr[i + 1]);
		}
	} else if (strcmp(el, "feSpotLight") == 0) {
		prim->light.type = MSVG_LIGHT_SPOT;
		prim->light.elemSeq = (p->ctxHead >= 0) ? p->ctx[p->ctxHead].seq : -1;
		for (i = 0; attr[i]; i += 2) {
			if (strcmp(attr[i], "x") == 0) prim->light.x = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "y") == 0) prim->light.y = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "z") == 0) prim->light.z = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "pointsAtX") == 0) prim->light.pointsAtX = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "pointsAtY") == 0) prim->light.pointsAtY = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "pointsAtZ") == 0) prim->light.pointsAtZ = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "specularExponent") == 0) prim->light.specularExponent = msvg__atof(attr[i + 1]);
			else if (strcmp(attr[i], "limitingConeAngle") == 0) {
				prim->light.limitingConeAngle = msvg__atof(attr[i + 1]);
				prim->light.hasLimitingCone = 1;
			}
		}
	}
}

// Parses an angle value for 'orient': <number> (degrees), <number>deg,
// <number>grad, <number>rad or <number>turn. Returns degrees.
static float msvg__parseAngle(const char* str)
{
	float v = msvg__atof(str);
	const char* s = str;
	while (*s && (msvg__isspace(*s) || *s == '+' || *s == '-' ||
				  (*s >= '0' && *s <= '9') || *s == '.'))
		s++;
	if (strcmp(s, "deg") == 0)
		return v;
	if (strcmp(s, "grad") == 0)
		return v * 0.9f;
	if (strcmp(s, "rad") == 0)
		return v * 57.29577951308232f;
	if (strcmp(s, "turn") == 0)
		return v * 360.0f;
	return v;	// plain <number>: degrees
}

// Parses a <marker> element: registers the template and its attributes. Like
// <clipPath>/<mask>, the transform context at the element (baseXform) is
// captured so child shapes (baked into document space) can be rebased into
// the marker's user space when the element closes.
static void msvg__parseMarker(MSVGparser* p, const char** attr)
{
	int i;
	MSVGmarkerData* mk = (MSVGmarkerData*)malloc(sizeof(MSVGmarkerData));
	if (mk == NULL) return;
	memset(mk, 0, sizeof(MSVGmarkerData));
	mk->markerWidth = 3.0f;		// markerWidth/markerHeight default
	mk->markerHeight = 3.0f;
	mk->units = MSVG_MARKER_UNITS_STROKEWIDTH;	// markerUnits default
	mk->orient = MSVG_ORIENT_ANGLE;	// SVG 1.1 §11.6.2/SVG 2: orient defaults to "0" (fixed, no rotation)
	mk->orientAngle = 0.0f;
	mk->alignX = MSVG_ALIGN_MID;
	mk->alignY = MSVG_ALIGN_MID;
	mk->alignType = MSVG_ALIGN_MEET;
	/* Markers are only ever used by reference (marker-* properties); they
	   are never rendered directly, so 'display' never gates marker
	   rendering: a marker with display:none (own or inherited) is still
	   rendered when referenced (SVG 1.1 §11.6.2, painting-marker-07-f
	   pass criteria). */
	mk->hidden = 0;
	msvg__xformIdentity(mk->bakeXform);
	{
		float base[6], inv[6];
		memcpy(base, msvg__getAttr(p)->xform, sizeof(float)*6);
		msvg__xformInverse(inv, base);
		msvg__xformMultiply(mk->bakeXform, inv);
	}

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			strncpy(mk->id, attr[i + 1], 63);
			mk->id[63] = '\0';
		} else if (strcmp(attr[i], "refX") == 0) {
			const char* v = attr[i + 1];
			if (strcmp(v, "left") == 0) mk->refX = 0.0f;
			else if (strcmp(v, "center") == 0) mk->refX = 0.5f;
			else if (strcmp(v, "right") == 0) mk->refX = 1.0f;
			else mk->refX = msvg__atof(v);
		} else if (strcmp(attr[i], "refY") == 0) {
			const char* v = attr[i + 1];
			if (strcmp(v, "top") == 0) mk->refY = 0.0f;
			else if (strcmp(v, "center") == 0) mk->refY = 0.5f;
			else if (strcmp(v, "bottom") == 0) mk->refY = 1.0f;
			else mk->refY = msvg__atof(v);
		} else if (strcmp(attr[i], "markerWidth") == 0) {
			mk->markerWidth = msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "markerHeight") == 0) {
			mk->markerHeight = msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "markerUnits") == 0) {
			mk->units = strcmp(attr[i + 1], "userSpaceOnUse") == 0
				? MSVG_MARKER_UNITS_USERSPACE : MSVG_MARKER_UNITS_STROKEWIDTH;
		} else if (strcmp(attr[i], "overflow") == 0) {
			/* SVG 1.1 §11.6.2 leaves 'auto' UA-defined (CSS2 §11.1.1: "user
			   agent-dependent"), and the suite's reference treats it as
			   'visible' for markers — painting-marker-05-f's own pass
			   criteria say "the columns labeled 'visible' and 'auto' show
			   markers without clipping them". So does the override, which
			   is presented as a token list. */
			mk->overflowVisible = (char)(msvg__hasTokCI(attr[i + 1], "visible") ||
									 msvg__hasTokCI(attr[i + 1], "auto"));
		} else if (strcmp(attr[i], "orient") == 0) {
			const char* v = attr[i + 1];
			if (strcmp(v, "auto") == 0) {
				mk->orient = MSVG_ORIENT_AUTO;
			} else if (strcmp(v, "auto-start-reverse") == 0) {
				mk->orient = MSVG_ORIENT_AUTO_START_REVERSE;
			} else {
				mk->orient = MSVG_ORIENT_ANGLE;
				mk->orientAngle = msvg__parseAngle(v);
			}
		} else if (strcmp(attr[i], "viewBox") == 0) {
			const char* s = attr[i + 1];
			char buf[64];
			s = msvg__parseNumber(s, buf, 64);
			mk->viewBox[0] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			mk->viewBox[1] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			mk->viewBox[2] = msvg__atof(buf);
			while (*s && (msvg__isspace(*s) || *s == '%' || *s == ',')) s++;
			if (!*s) continue;
			s = msvg__parseNumber(s, buf, 64);
			mk->viewBox[3] = msvg__atof(buf);
			mk->hasViewBox = 1;
		} else if (strcmp(attr[i], "preserveAspectRatio") == 0) {
			msvg__parseAspectRatio(attr[i + 1], &mk->alignX, &mk->alignY, &mk->alignType);
		} else if (strcmp(attr[i], "transform") == 0) {
			float xf[6];
			msvg__parseTransform(xf, attr[i + 1]);
			msvg__xformMultiply(mk->bakeXform, xf);
		}
	}

	if (p->markersTail)
		p->markersTail->next = mk;
	else
		p->markers = mk;
	p->markersTail = mk;
}

// Rebases a marker's content shapes into the marker's user space. Called when
// the <marker> element closes (all child shapes are already parsed).
static void msvg__bakeMarkerContent(MSVGmarkerData* mk)
{
	MSVGshape* shape;
	for (shape = mk->shapes; shape != NULL; shape = shape->next)
		msvg__transformShape(shape, mk->bakeXform);
}

static MSVGmarkerData* msvg__findMarkerData(MSVGparser* p, const char* id)
{
	MSVGmarkerData* mk;
	if (id == NULL || id[0] == '\0')
		return NULL;
	for (mk = p->markers; mk != NULL; mk = mk->next)
		if (strcmp(mk->id, id) == 0)
			return mk;
	return NULL;
}

/* ------------------------------------------------------------------ */
/* SVG fonts (SVG 1.1 §20): <font>, <font-face>, <glyph>,             */
/* <missing-glyph>, <hkern>. REMOVED in SVG 2 — kept for backward     */
/* compatibility (SVG 1.1 features removed by SVG 2 must still work). */
/* ------------------------------------------------------------------ */

static char* msvg__fontStrdup(const char* s)
{
	size_t n;
	char* r;
	if (s == NULL) return NULL;
	n = strlen(s);
	r = (char*)malloc(n + 1);
	if (r == NULL) return NULL;
	memcpy(r, s, n);
	r[n] = '\0';
	return r;
}

static void msvg__fontFree(MSVGfont* f)
{
	while (f != NULL) {
		MSVGfont* next = f->next;
		MSVGglyph* g = f->glyphs;
		MSVGkern* k;
		while (g != NULL) {
			MSVGglyph* gnext = g->next;
			free(g->unicode);
			free(g->glyphName);
			free(g->elId);
			msvg__deletePaths(g->paths);
			free(g);
			g = gnext;
		}
		if (f->missingGlyph != NULL) {
			free(f->missingGlyph->unicode);
			free(f->missingGlyph->glyphName);
			free(f->missingGlyph->elId);
			msvg__deletePaths(f->missingGlyph->paths);
			free(f->missingGlyph);
		}
		for (k = f->kerns; k != NULL; ) {
			MSVGkern* knext = k->next;
			free(k->u1); free(k->u2); free(k->g1); free(k->g2);
			free(k);
			k = knext;
		}
		free(f->family);
		free(f->weight);
		free(f->style);
		free(f);
		f = next;
	}
}

// Parses a glyph 'd' path into an MSVGpath list in FONT units with an
// identity transform (save/restore the parser's path buffer like textPath
// does). The glyph path data uses y-UP coordinates with the baseline at
// 0 (SVG 1.1 §20.2), while the text shaper contract delivers outlines
// y-DOWN with the baseline at 0 — so y is flipped here.
static MSVGpath* msvg__parseGlyphPath(MSVGparser* p, const char* d)
{
	MSVGpath* savedPlist = p->plist;
	float* savedPts = p->pts;
	int savedNpts = p->npts;
	int savedCpts = p->cpts;
	float savedXform[6];
	MSVGpath* res;
	MSVGpath* pp;

	memcpy(savedXform, msvg__getAttr(p)->xform, sizeof(float) * 6);
	msvg__xformIdentity(msvg__getAttr(p)->xform);
	p->plist = NULL;
	p->pts = NULL;
	p->npts = 0;
	p->cpts = 0;
	msvg__parsePathData(p, d);
	res = p->plist;
	p->plist = savedPlist;
	free(p->pts);
	p->pts = savedPts;
	p->npts = savedNpts;
	p->cpts = savedCpts;
	memcpy(msvg__getAttr(p)->xform, savedXform, sizeof(float) * 6);

	/* y-up -> y-down: flip every y, then recompute bounds. */
	for (pp = res; pp != NULL; pp = pp->next) {
		int i;
		for (i = 0; i < pp->npts; i++)
			pp->pts[i * 2 + 1] = -pp->pts[i * 2 + 1];
		pp->bounds[0] = pp->bounds[1] = 1e30f;
		pp->bounds[2] = pp->bounds[3] = -1e30f;
		for (i = 0; i < pp->npts; i++) {
			if (pp->pts[i * 2] < pp->bounds[0]) pp->bounds[0] = pp->pts[i * 2];
			if (pp->pts[i * 2 + 1] < pp->bounds[1]) pp->bounds[1] = pp->pts[i * 2 + 1];
			if (pp->pts[i * 2] > pp->bounds[2]) pp->bounds[2] = pp->pts[i * 2];
			if (pp->pts[i * 2 + 1] > pp->bounds[3]) pp->bounds[3] = pp->pts[i * 2 + 1];
		}
		if (pp->bounds[0] > pp->bounds[2])
			pp->bounds[0] = pp->bounds[1] = pp->bounds[2] = pp->bounds[3] = 0.0f;
	}
	return res;
}

// <font> element: starts a new font, sets the default advance.
static void msvg__parseFont(MSVGparser* p, const char** attr)
{
	MSVGfont* f;
	int i;

	f = (MSVGfont*)calloc(1, sizeof(MSVGfont));
	if (f == NULL) return;
	f->unitsPerEm = 1000.0f;
	f->ascent = 800.0f;
	f->descent = -200.0f;

	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "horiz-adv-x") == 0)
			f->horizAdvX = (float)msvg__atof(attr[i + 1]);
		else if (strcmp(attr[i], "horiz-origin-x") == 0 || strcmp(attr[i], "horiz-origin-y") == 0)
			{ /* origin hints; not needed for horizontal layout */ }
	}
	if (p->fontsTail != NULL)
		p->fontsTail->next = f;
	else
		p->fonts = f;
	p->fontsTail = f;
	p->curFont = f;
}

// <font-face> element: font family/metrics/weight/style.
static void msvg__parseFontFace(MSVGparser* p, const char** attr)
{
	MSVGfont* f = p->curFont;
	int i;
	if (f == NULL) {
		/* A LOCAL <font-face> with no sibling <font> (the font comes from
		   a <font-face-uri> child): record its family descriptor so the
		   loaded file's faces are registered under THIS family (SVG 1.1
		   §20.4 — the local face's family is authoritative for matching;
		   the file's own weight/style classify its glyphs). */
		for (i = 0; attr[i]; i += 2) {
			if (strcmp(attr[i], "font-family") == 0) {
				free(p->ffLocalFamily);
				p->ffLocalFamily = msvg__fontStrdup(attr[i + 1]);
			}
		}
		return;
	}
	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "font-family") == 0) {
			free(f->family);
			f->family = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "units-per-em") == 0) {
			f->unitsPerEm = (float)msvg__atof(attr[i + 1]);
			if (f->unitsPerEm <= 0.0f) f->unitsPerEm = 1000.0f;
		} else if (strcmp(attr[i], "ascent") == 0) {
			f->ascent = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "descent") == 0) {
			f->descent = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "x-height") == 0) {
			f->xHeight = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "cap-height") == 0) {
			f->capHeight = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "font-weight") == 0) {
			free(f->weight);
			f->weight = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "font-style") == 0) {
			free(f->style);
			f->style = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "font-variant") == 0) {
			f->variant = (strncmp(attr[i + 1], "small-caps", 10) == 0) ? 1 : 0;
		}
	}
}

// <font-face-uri> (SVG 1.1 §20.4 / CSS webfonts): the href of an
// external font document referenced by a local <font-face>. The document
// is loaded after parsing (msvg__loadFontFaceUris); the local element's
// family descriptor travels with the href so the loaded faces register
// under the requesting family (see msvg__loadFontFaceUris for why
// weight/style are intentionally NOT overridden).
static void msvg__parseFontFaceUri(MSVGparser* p, const char** attr)
{
	int i;
	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "xlink:href") == 0 || strcmp(attr[i], "href") == 0) {
			struct MSVGfontFaceUri* u;
			if (attr[i+1] == NULL || attr[i+1][0] == '\0') continue;
			u = (struct MSVGfontFaceUri*)malloc(sizeof(*u));
			if (u == NULL) return;
			u->href = msvg__fontStrdup(attr[i+1]);
			/* Snapshot the enclosing <font-face>'s descriptors (set just
		   before by msvg__parseFontFace's no-font branch). */
			u->family = msvg__fontStrdup(p->ffLocalFamily ? p->ffLocalFamily : "");
			if (u->href == NULL || u->family == NULL) {
				free(u->href); free(u->family);
				free(u);
				return;
			}
			if (u->href == NULL) { free(u); return; }
			u->next = NULL;
			if (p->fontFaceUrisTail != NULL)
				p->fontFaceUrisTail->next = u;
			else
				p->fontFaceUris = u;
			p->fontFaceUrisTail = u;
		}
	}
}

// Loads every collected <font-face-uri> target into the image (each is a
// font SVG document; msvgLoadSVGFontFile appends its faces to
// image->fonts). Relative hrefs resolve against the DOCUMENT BASE (the
// loader data the doc loader uses, SVG 1.1 §5.8); fragment identifiers
// select a face within the document and are stripped for file access.
/* Case-insensitive bounded compare (ASCII): 1 when the first n bytes
   match the prefix ignoring case. */
static int msvg__strncasecmp(const char* a, const char* b, size_t n)
{
	size_t i;
	for (i = 0; i < n; i++) {
		char ca = a[i], cb = b[i];
		if (ca >= 'A' && ca <= 'Z') ca += 32;
		if (cb >= 'A' && cb <= 'Z') cb += 32;
		if (ca != cb) return (unsigned char)ca < (unsigned char)cb ? -1 : 1;
		if (ca == '\0') return 0;
	}
	return 0;
}

/* CSS @font-face rule (CSS Fonts / SVG 1.1 SE §20.4 webfonts): parse the
   at-rule body for font-family / font-weight / font-style / src:url() and
   load the referenced font document NOW (the parser is alive and the doc
   loader's base is set). The loaded faces register under the @font-face
   family with the DECLARED weight/style as matching descriptors — the
   farm's Batik did load suite SVG-font webfonts (text-fonts-204-t's five
   ZC weight faces; its ref shows the real ZC glyphs). */
static void msvg__cssFontFace(MSVGparser* p, const char* body, const char* bodyEnd)
{
	char family[128] = "";
	char href[1024] = "";
	int weight = -1;
	int style = -1;
	char path[2048];
	const char* base;
	const char* frag;
	size_t n;
	MSVGfont* before;
	MSVGfont* f;
	const char* s = body;
	fprintf(stderr, "[FF] cssFontFace entry body='%.40s'\n", body);

	while (s < bodyEnd) {
		const char* key0;
		const char* key1;
		const char* val0;
		const char* val1;
		while (s < bodyEnd && (msvg__isspace(*s) || *s == ';')) s++;
		if (s >= bodyEnd) break;
		key0 = s;
		while (s < bodyEnd && *s != ':' && *s != ';') s++;
		if (s >= bodyEnd || *s != ':') { if (getenv("MSVG_DBG_FF")) fprintf(stderr, "[FF] key no-colon: '%.20s'\n", key0); s++; continue; }
		key1 = s;
		s++;
		while (s < bodyEnd && msvg__isspace(*s)) s++;
		val0 = s;
		while (s < bodyEnd && *s != ';') s++;
		val1 = s;
		while (val1 > val0 && msvg__isspace(val1[-1])) val1--;
		if (key1 - key0 == 11 && msvg__strncasecmp(key0, "font-family", 11) == 0) {
			const char* a = val0;
			const char* b = val1;
			while (b > a && (msvg__isspace(b[-1]) || b[-1] == '"' || b[-1] == '\'')) b--;
			while (a < b && (msvg__isspace(*a) || *a == '"' || *a == '\'')) a++;
			n = (size_t)(b - a);
			if (n >= sizeof(family)) n = sizeof(family) - 1;
			memcpy(family, a, n); family[n] = '\0';
		} else if (key1 - key0 == 11 && msvg__strncasecmp(key0, "font-weight", 11) == 0) {
			if (val1 - val0 == 6 && msvg__strncasecmp(val0, "normal", 6) == 0) weight = 400;
			else if (val1 - val0 == 4 && msvg__strncasecmp(val0, "bold", 4) == 0) weight = 700;
			else weight = (int)msvg__atof(val0);
		} else if (key1 - key0 == 10 && msvg__strncasecmp(key0, "font-style", 10) == 0) {
			if (val1 - val0 == 6 && msvg__strncasecmp(val0, "italic", 6) == 0) style = 1;
			else if (val1 - val0 == 7 && msvg__strncasecmp(val0, "oblique", 7) == 0) style = 2;
			else style = 0;
		} else if (key1 - key0 == 3 && msvg__strncasecmp(key0, "src", 3) == 0) {
			const char* u0 = val0;
			while (u0 < val1 && *u0 != '(') u0++;
			if (u0 < val1) {
				const char* u1;
				u0++;
				while (u0 < val1 && msvg__isspace(*u0)) u0++;
				if (u0 < val1 && (*u0 == '"' || *u0 == '\'')) {
					char q = *u0++;
					const char* st = u0;
					while (u0 < val1 && *u0 != q) u0++;
					u1 = u0;
					n = (size_t)(u1 - st);
					if (n >= sizeof(href)) n = sizeof(href) - 1;
					memcpy(href, st, n); href[n] = '\0';
				} else {
					/* unquoted url token: runs to ')' (CSS Syntax §3.4) */
					const char* st = u0;
					while (u0 < val1 && *u0 != ')') u0++;
					while (u0 > st && msvg__isspace(u0[-1])) u0--;
					n = (size_t)(u0 - st);
					if (n >= sizeof(href)) n = sizeof(href) - 1;
					memcpy(href, st, n); href[n] = '\0';
				}
			}
		}
		s = val1;
	}
	if (family[0] == '\0' || href[0] == '\0') {
		if (getenv("MSVG_DBG_FF"))
			fprintf(stderr, "[FF] bail: family='%s' href='%.60s'\n", family, href);
		return;
	}
	/* Resolve the font document path against the document base. */
	base = (const char*)p->image->docLoaderData;
	frag = strchr(href, '#');
	n = frag ? (size_t)(frag - href) : strlen(href);
	while (n > 0 && (href[n-1] == ' ' || href[n-1] == '\t')) n--;
	if (n >= sizeof(path)) n = sizeof(path) - 1;
	if (base != NULL && base[0] != '\0' && href[0] != '/')
		snprintf(path, sizeof(path), "%s/%.*s", base, (int)n, href);
	else
		snprintf(path, sizeof(path), "%.*s", (int)n, href);
	/* Register the webfont for the HOST's font machinery (CSS Fonts §4):
	   data: URIs pass through as-is, file paths were resolved against the
	   document base above. The engine's embedded SVG-font path must not
	   shape a family listed here (see MSVGimage.webfonts). */
	if (p->image != NULL) {
		MSVGwebfont* wf = (MSVGwebfont*)malloc(sizeof(MSVGwebfont));
		if (wf != NULL) {
			MSVGwebfont** wtail = &p->image->webfonts;
			char wb[16];
			memset(wf, 0, sizeof(*wf));
			wf->family = msvg__fontStrdup(family);
			if (weight > 0) {
				snprintf(wb, sizeof(wb), "%d", weight);
				wf->weight = msvg__fontStrdup(wb);
			}
			if (style >= 0)
				wf->style = msvg__fontStrdup(style == 1 ? "italic" : style == 2 ? "oblique" : "normal");
			wf->file = msvg__fontStrdup((strncmp(href, "data:", 5) == 0) ? href : path);
			while (*wtail != NULL) wtail = &(*wtail)->next;
			*wtail = wf;
			if (getenv("MSVG_DBG_FF"))
				fprintf(stderr, "[FF] webfont fam='%s' w=%d s=%d file='%.80s'\n",
						family, weight, style, wf->file);
		}
	}
	before = p->image->fonts;
	while (before != NULL && before->next != NULL) before = before->next;
	if (!msvgLoadSVGFontFile(p->image, path))
		return;
	f = (before != NULL) ? before->next : p->image->fonts;
	for (; f != NULL; f = f->next) {
		free(f->family);
		f->family = msvg__fontStrdup(family);
		if (weight > 0) {
			char wb[16];
			snprintf(wb, sizeof(wb), "%d", weight);
			free(f->weight);
			f->weight = msvg__fontStrdup(wb);
		}
		if (style >= 0) {
			free(f->style);
			f->style = msvg__fontStrdup(style == 1 ? "italic" : style == 2 ? "oblique" : "normal");
		}
	}
}

static void msvg__loadFontFaceUris(MSVGimage* image, MSVGparser* p)
{
	struct MSVGfontFaceUri* u = p->fontFaceUris;
	const char* base = (const char*)image->docLoaderData;
	MSVGfont* firstNew = NULL;
	MSVGfont* lastNew = NULL;
	while (u != NULL) {
		const char* href = u->href;
		MSVGfont* before = image->fonts;
		while (before != NULL && before->next != NULL) before = before->next;
		if (strncmp(href, "data:", 5) != 0 &&
			strncmp(href, "http://", 7) != 0 &&
			strncmp(href, "https://", 8) != 0) {
			char path[2048];
			size_t n = strlen(href);
			const char* frag = strchr(href, '#');
			if (frag != NULL) n = (size_t)(frag - href);
			while (n > 0 && (href[n-1] == ' ' || href[n-1] == '	')) n--;
			if (n >= sizeof(path)) n = sizeof(path) - 1;
			if (base != NULL && base[0] != '\0' && href[0] != '/')
				snprintf(path, sizeof(path), "%s/%.*s", base, (int)n, href);
			else
				snprintf(path, sizeof(path), "%.*s", (int)n, href);
			if (msvgLoadSVGFontFile(image, path)) {
					/* The faces appended by this load: retarget their FAMILY
					   to the LOCAL <font-face> element's value when it
					   declared one (SVG 1.1 §20.4: the referencing font-face
					   is authoritative for matching; resource files may
					   declare a different family — styling-css-05-b's
					   SVGFreeSansISO-8859-1 oblique face — which would leave
					   the face unreachable under the requested family).
					   Weight/style are NOT overridden: the file's own
					   <font-face> classifies its glyphs (e.g. BoldItalic.svg
					   declares oblique while the referencing element says
					   italic), and CSS distance scoring handles
					   oblique<->italic substitution — stamping those here
					   collided distinct faces (animate-elem-46-t's bold
					   italic A regressed to the weight-400 italic glyphs). */
				MSVGfont* f = (before != NULL) ? before->next : image->fonts;
				for (; f != NULL; f = f->next) {
					if (u->family[0] != '\0') {
						free(f->family);
						f->family = msvg__fontStrdup(u->family);
					}
					lastNew = f;
					if (firstNew == NULL) firstNew = f;
				}
			}
		}
		u = u->next;
	}
	(void)firstNew; (void)lastNew;
}

// <glyph> / <missing-glyph> element.
static void msvg__parseGlyph(MSVGparser* p, const char** attr, int isMissing)
{
	MSVGfont* f = p->curFont;
	MSVGglyph* g;
	const char* d = NULL;
	int i;
	if (f == NULL) return;

	g = (MSVGglyph*)calloc(1, sizeof(MSVGglyph));
	if (g == NULL) return;
	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "id") == 0) {
			g->elId = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "unicode") == 0) {
			g->unicode = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "glyph-name") == 0) {
			g->glyphName = msvg__fontStrdup(attr[i + 1]);
		} else if (strcmp(attr[i], "horiz-adv-x") == 0) {
			g->horizAdvX = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "vert-adv-y") == 0) {
			g->vertAdvY = (float)msvg__atof(attr[i + 1]);
		} else if (strcmp(attr[i], "d") == 0) {
			d = attr[i + 1];
		}
	}
	if (d != NULL)
		g->paths = msvg__parseGlyphPath(p, d);

	if (isMissing) {
		f->missingGlyph = g;
	} else {
		/* SVG 1.1 §20.4: glyph selection is done in the ORDER the glyphs
		   are defined in the <font> (fonts-glyph-04-t). Preserve document
		   order by appending to the tail (prepending would reverse it). */
		if (f->glyphs == NULL) {
			f->glyphs = g;
		} else {
			MSVGglyph* t = f->glyphs;
			while (t->next != NULL) t = t->next;
			t->next = g;
		}
	}
}

// <hkern> / <vkern> element. Vkern is parsed but unused (horizontal text).
static void msvg__parseKern(MSVGparser* p, const char** attr)
{
	MSVGfont* f = p->curFont;
	MSVGkern* k;
	int i;
	if (f == NULL) return;
	k = (MSVGkern*)calloc(1, sizeof(MSVGkern));
	if (k == NULL) return;
	for (i = 0; attr[i]; i += 2) {
		if (strcmp(attr[i], "u1") == 0) k->u1 = msvg__fontStrdup(attr[i + 1]);
		else if (strcmp(attr[i], "u2") == 0) k->u2 = msvg__fontStrdup(attr[i + 1]);
		else if (strcmp(attr[i], "g1") == 0) k->g1 = msvg__fontStrdup(attr[i + 1]);
		else if (strcmp(attr[i], "g2") == 0) k->g2 = msvg__fontStrdup(attr[i + 1]);
		else if (strcmp(attr[i], "k") == 0) k->k = (float)msvg__atof(attr[i + 1]);
	}
	k->next = f->kerns;
	f->kerns = k;
}// Glyph selection (SVG 1.1 §20.4 "Glyph selection"): glyphs are considered
// in the order they appear in the <font>'s definition, and the FIRST glyph
// whose 'unicode' string is a prefix of the text at cps[0..] is used. This is
// definition-order selection, NOT longest-match — ligature glyphs only win
// when they appear before the shorter alternative in the definition
// (fonts-glyph-04-t: SVGFont1 defines 'f' then 'ffl' and text "ffl" must
// render as f+f+l, not the square). *glen = codepoints consumed (1 or the
// ligature length); NULL when no glyph matches.
static MSVGglyph* msvg__fontFindGlyph(MSVGfont* f, const unsigned int* cps, int ncp, int* glen)
{
	MSVGglyph* g;
	if (glen) *glen = 1;
	if (f == NULL || cps == NULL || ncp <= 0) return NULL;
	/* XML whitespace (tab/newline/FF) never resolves to a real glyph in
	   any suite SVG font: the SVG 1.1 spec keeps only ' ' (U+0020) as a
	   glyph-able space. A literal font whose <glyph> list matches one of
	   these is treated as the font NOT covering the char, so the per-char
	   fallback (§20.4 / CSS font matching) applies — the reference farm
	   rendered preserved newlines as zero-width whitespace, not .notdef
	   boxes (text-ws-02-t). */
	if (cps[0] == '\t' || cps[0] == '\n' || cps[0] == '\r' ||
		cps[0] == 0x0B || cps[0] == 0x0C)
		return NULL;
	for (g = f->glyphs; g != NULL; g = g->next) {
		int len;
		if (g->unicode == NULL || g->unicode[0] == '\0') continue;
		len = msvg__utf8Len((const unsigned char*)g->unicode);
		if (len > ncp) continue;
		{
			const unsigned char* u = (const unsigned char*)g->unicode;
			int match = 1;
			int ci;
			for (ci = 0; ci < len; ci++) {
				unsigned int cp;
				int ul = msvg__utf8Decode(u, &cp);
				if (ul <= 0 || cp != cps[ci]) { match = 0; break; }
				u += ul;
			}
			if (match) {
				if (glen) *glen = len;
				return g;
			}
		}
	}
	return NULL;
}

// Hex digit value (-1 for non-hex).
static int msvg__hexDigitVal(char c)
{
	if (c >= '0' && c <= '9') return c - '0';
	if (c >= 'a' && c <= 'f') return c - 'a' + 10;
	if (c >= 'A' && c <= 'F') return c - 'A' + 10;
	return -1;
}

// Matches a glyph against one unicode-range token (SVG 1.1 §20.7 u1/u2,
// which uses the CSS2 §15.3.4 <urange> syntax):
//   U+XXXX       single codepoint (1-6 hex digits)
//   U+XXXX-YYYY  range; when YYYY has fewer digits than XXXX the range ends
//                 at the value formed by replacing XXXX's trailing digits
//                 with YYYY (e.g. U+0031-34 == U+0031-0034)
//   U+XXX?       trailing '?' wildcards expand to a range (U+003? == 0030-003F)
//   <literal>    a plain character (or run of characters) matches its codepoints
// Returns 1 when any codepoint of the glyph's unicode string falls in the set.
static int msvg__kernTokenMatch(const char* tok, MSVGglyph* g)
{
	unsigned int cps[8];
	int ncp = 0, i;
	const unsigned char* u;
	if (tok == NULL || g == NULL || g->unicode == NULL) return 0;
	u = (const unsigned char*)g->unicode;
	while (*u && ncp < 8) {
		unsigned int c;
		int l = msvg__utf8Decode(u, &c);
		if (l <= 0) break;
		cps[ncp++] = c;
		u += l;
	}
	if (ncp == 0) return 0;
	if ((tok[0] == 'U' || tok[0] == 'u') && tok[1] == '+') {
		const char* p = tok + 2;
		unsigned int first = 0, last;
		int nd = 0, hv;
		while ((hv = msvg__hexDigitVal(p[0])) >= 0 && nd < 6) {
			first = first * 16 + (unsigned int)hv;
			p++;
			nd++;
		}
		if (nd == 0) return 0;
		last = first;
		if (*p == '-') {
			const char* q = p + 1;
			int nd2 = 0;
			unsigned int end = 0;
			while ((hv = msvg__hexDigitVal(q[0])) >= 0 && nd2 < 6) {
				end = end * 16 + (unsigned int)hv;
				q++;
				nd2++;
			}
			if (nd2 == 0) return 0;
			if (nd2 < nd) {
				unsigned int base = 1;
				int j;
				for (j = 0; j < nd - nd2; j++) base *= 16;
				last = (first / base) * base + end;
			} else {
				last = end;
			}
			p = q;
		} else if (*p == '?') {
			unsigned int base = 1;
			while (*p == '?') { base *= 16; p++; }
			first = first * base;
			last = first + base - 1;
		}
		if (*p != '\0') return 0;
		for (i = 0; i < ncp; i++)
			if (cps[i] >= first && cps[i] <= last) return 1;
	} else {
		/* Literal character(s): any codepoint of the token matching any of
		   the glyph's codepoints. */
		u = (const unsigned char*)tok;
		while (*u) {
			unsigned int c;
			int l = msvg__utf8Decode(u, &c);
			if (l <= 0) break;
			for (i = 0; i < ncp; i++)
				if (c == cps[i]) return 1;
			u += l;
		}
	}
	return 0;
}

// Splits a u1/u2 value on spaces/commas and matches any token.
static int msvg__kernListMatch(const char* list, MSVGglyph* g)
{
	const char* p = list;
	while (p != NULL && *p) {
		const char* start = p;
		char tok[64];
		int n;
		while (*p && *p != ',' && *p != ' ' && *p != '	') p++;
		n = (int)(p - start);
		if (n > 0) {
			if (n > 63) n = 63;
			memcpy(tok, start, (size_t)n);
			tok[n] = '\0';
			if (msvg__kernTokenMatch(tok, g)) return 1;
		}
		while (*p == ',' || *p == ' ' || *p == '	') p++;
	}
	return 0;
}

// Kerning pair lookup (SVG 1.1 §20.7): a pair (g1,g2) matches when the
// first char's glyph is in u1/g1 and the second's in u2/g2.
//
static float msvg__fontKern(MSVGfont* f, MSVGglyph* g1, MSVGglyph* g2)
{
	MSVGkern* k;
	if (f == NULL || g1 == NULL || g2 == NULL) return 0.0f;
	for (k = f->kerns; k != NULL; k = k->next) {
		int a = 0, b = 0;
		if (k->u1 != NULL)
			a |= msvg__kernListMatch(k->u1, g1);
		if (k->g1 != NULL && g1->glyphName != NULL)
			a |= (msvg__glyphNameInList(k->g1, g1->glyphName));
		if (k->u2 != NULL)
			b |= msvg__kernListMatch(k->u2, g2);
		if (k->g2 != NULL && g2->glyphName != NULL)
			b |= (msvg__glyphNameInList(k->g2, g2->glyphName));
		if (a && b) return k->k;
	}
	return 0.0f;
}

// Parses a font-weight string ("400", "700", "normal", "bold") to a
// numeric weight; -1 when unset.
static int msvg__fontWeightValue(const char* w)
{
	if (w == NULL || w[0] == '\0') return -1;
	if (strcmp(w, "normal") == 0) return 400;
	if (strcmp(w, "bold") == 0) return 700;
	if (strcmp(w, "bolder") == 0 || strcmp(w, "lighter") == 0) return -1;
	{
		int v = (int)msvg__atof(w);
		return (v > 0) ? v : -1;
	}
}

// Parses a font-style string ("normal"/"italic"/"oblique"); -1 unset,
// 0 normal, 1 italic, 2 oblique.
static int msvg__fontStyleValue(const char* s)
{
	if (s == NULL || s[0] == '\0') return -1;
	if (strncmp(s, "italic", 6) == 0) return 1;
	if (strncmp(s, "oblique", 7) == 0) return 2;
	return 0;
}

// Font matching (SVG 1.1 §20.4 / CSS: first available font wins): the
// family list is tried in order; within a family, the face closest in
// weight (then style, then variant) is chosen. Case-insensitive family
// comparison. A face whose font-variant conflicts with the request is
// skipped (CSS: a face is only used if it matches the requested variant,
// except when no face matches — then small-caps falls back to any face).
static MSVGfont* msvg__fontLookup(MSVGimage* img, const char* familyList,
								  int weight, int style, int variant);
static MSVGfont* msvg__fontLookupWithAliases(MSVGimage* img, const char* familyList,
											  int weight, int style, int variant)
{
	MSVGfont* f = msvg__fontLookup(img, familyList, weight, style, variant);
	const struct MSVGfontNamePair* a;
	const char* p;
	char mapped[512];
	if (f != NULL || img == NULL || img->fontAliases == NULL || familyList == NULL)
		return f;
	/* Rewrite each family through the alias table and retry once. */
	mapped[0] = '\0';
	p = familyList;
	while (*p) {
		const char* start = p;
		const char* e;
		const char* rep = NULL;
		int n = 0;
		while (*p && *p != ',') p++;
		e = p;
		while (e > start && (e[-1] == ' ' || e[-1] == '	')) e--;
		while (start < e && (*start == ' ' || *start == '	')) start++;
		if (start < e && (*start == '\'' || *start == '"') && e[-1] == start[0]) {
			start++;
			e--;
		}
		n = (int)(e - start);
		for (a = img->fontAliases; a != NULL; a = a->next) {
			size_t al = strlen(a->from);
			if (al == (size_t)n) {
				/* ASCII case-insensitive compare (CSS family names). */
				size_t ci;
				int eq = 1;
				for (ci = 0; ci < (size_t)n; ci++) {
					char ca = a->from[ci], cb = start[ci];
					if (ca >= 'A' && ca <= 'Z') ca = (char)(ca - 'A' + 'a');
					if (cb >= 'A' && cb <= 'Z') cb = (char)(cb - 'A' + 'a');
					if (ca != cb) { eq = 0; break; }
				}
				if (eq) { rep = a->to; break; }
			}
		}
		if (rep == NULL) rep = start;
		if (strlen(mapped) + strlen(rep) + 2 >= sizeof(mapped))
			break;
		if (mapped[0] != '\0') strcat(mapped, ",");
		strcat(mapped, rep);
		if (*p == ',') p++;
	}
	if (mapped[0] == '\0') return NULL;
	return msvg__fontLookup(img, mapped, weight, style, variant);
}

static MSVGfont* msvg__fontLookup(MSVGimage* img, const char* familyList, int weight, int style, int variant)
{
	char fam[256];
	const char* p;
	MSVGfont* bestOverall = NULL;
	/* Last-resort fallback: when no face in ANY family passes the strict
	   variant filter (e.g. a family exposing only small-caps faces used in
	   a normal-variant run), the best variant-mismatched face is used
	   instead of dropping the family entirely. CSS font matching would
	   move to the next family; if that also fails the request falls back
	   to an arbitrary default anyway, so honoring the user's chosen
	   family with a mismatched variant is strictly more faithful. */
	MSVGfont* fbOverall = NULL;
	int fbScore = 0x7fffffff;
	int fbWscore = 0x7fffffff;
	if (img == NULL || familyList == NULL) return NULL;
	/* CSS @font-face webfont gate (SVG 1.1 SE farm behavior): a family
	   with a registered webfont whose src LOADED was REPLACED by it on the
	   reference farm (Batik's webfont load took over the family), so such
	   families must not match embedded SVG fonts — the run falls through
	   to the next family in the list and the shaper's FreeType path
	   renders the webfont. A webfont whose src file does not exist was
	   NOT loaded on the farm either (its @font-face failed silently and
	   the CSS font-matching continued with the NEXT source for that
	   family — including an embedded <font> of the same name, exactly
	   what text-text-04-t's reference shows: its 'embeded' @font-face
	   src woffs/embeded-text-text-04.woff is absent, so the farm used
	   the <font id="embeded"> element). Gate only on registered
	   webfonts whose file exists. 202/203-t (XML <font-face-uri> SVG
	   faces) keep their path. */
	if (img->webfonts != NULL) {
		const char* wp = familyList;
		char wfam[256];
		while (*wp) {
			const char* wstart = wp;
			const char* we;
			int wn = 0, wmatch = 0;
			MSVGwebfont* wf;
			while (*wp && *wp != ',') wp++;
			we = wp;
			while (we > wstart && (we[-1] == ' ' || we[-1] == '\t')) we--;
			while (wstart < we && (*wstart == ' ' || *wstart == '\t')) wstart++;
			if (wstart < we && (*wstart == '\'' || *wstart == '"') &&
				we[-1] == wstart[0]) {
				wstart++;
				we--;
			}
			wn = (int)(we - wstart);
			if (wn > 0) {
				if (wn >= (int)sizeof(wfam)) wn = (int)sizeof(wfam) - 1;
				memcpy(wfam, wstart, (size_t)wn);
				wfam[wn] = '\0';
				for (wf = img->webfonts; wf != NULL; wf = wf->next) {
					const char* wff = wf->family ? wf->family : "";
					int wi;
					if (strlen(wff) != (size_t)wn) continue;
					/* The farm loaded only webfonts whose src resolved.
					   A missing src file (relative to the document dir,
					   as Batik resolves it) means the @font-face failed
					   there too and must NOT gate the family. */
					{
						FILE* wft = wf->file ? fopen(wf->file, "rb") : NULL;
						if (wft == NULL) continue;
						fclose(wft);
					}
					wmatch = 1;
					for (wi = 0; wi < wn; wi++) {
						char a = wfam[wi], b = wff[wi];
						if (a >= 'A' && a <= 'Z') a = (char)(a - 'A' + 'a');
						if (b >= 'A' && b <= 'Z') b = (char)(b - 'A' + 'a');
						if (a != b) { wmatch = 0; break; }
					}
					if (wmatch) break;
				}
			}
			if (wmatch) {
				if (getenv("MSVG_DBG_FONT"))
					fprintf(stderr, "[FONT] webfont gate: fam=%s\n", wfam);
				return NULL;
			}
			if (*wp) wp++;
		}
	}
	p = familyList;
	while (*p) {
		const char* start = p;
		int n = 0;			MSVGfont* best = NULL;
			int bestScore = 0x7fffffff;
			int bestWscore = 0x7fffffff;
		while (*p && *p != ',') p++;
		{
			const char* e = p;
			while (e > start && (e[-1] == ' ' || e[-1] == '	')) e--;
			while (start < e && (*start == ' ' || *start == '	')) start++;
			/* CSS Font Module §3.1.1: a family name may be quoted
			   ('ZalamanderCaps' / "DejaVu Sans"); the quotes are not part
			   of the name and must be stripped before matching. */
			if (start < e && (*start == '\'' || *start == '"') &&
				e[-1] == start[0]) {
				start++;
				e--;
			}
			n = (int)(e - start);
		}
		if (n > 0) {
			MSVGfont* f;
			if (n >= (int)sizeof(fam)) n = (int)sizeof(fam) - 1;
			memcpy(fam, start, (size_t)n);
			fam[n] = '\0';
			for (f = img->fonts; f != NULL; f = f->next) {
				const char* ff = f->family ? f->family : "";
				size_t fl = strlen(ff);
				int ci, match = 1;
				if (fl != (size_t)n) match = 0;
				for (ci = 0; match && ci < n; ci++) {
					char a = fam[ci], b = ff[ci];
					if (a >= 'A' && a <= 'Z') a = (char)(a - 'A' + 'a');
					if (b >= 'A' && b <= 'Z') b = (char)(b - 'A' + 'a');
					if (a != b) match = 0;
				}
				if (match) {
					int fw = msvg__fontWeightValue(f->weight);
					int fs = msvg__fontStyleValue(f->style);
					int fv = f->variant;									int score = 0;		// style tier: CSS2.1 15.5.2 decides style BEFORE weight
									int wscore = 0;		// weight distance, breaks style ties only

					/* CSS Fonts §5.2: an omitted font-weight/font-style
					   descriptor means the INITIAL value (400 / normal), not
					   "no preference". Scoring an unspecified face as a
					   perfect match made it tie with (and beat, being
					   earlier in the list) an explicitly 700/italic face —
					   animate-elem-46-t's bold-italic marker then fell back
					   to the regular face. */
					if (fw < 0) fw = 400;
					if (fs < 0) fs = 0;									if (weight > 0)
										wscore += (fw - weight) * (fw - weight);									/* CSS2.1 15.5.2 style distance: exact match best; 'oblique'
									   substitutes for 'italic' and vice versa at one step;
									   normal vs italic/oblique is the worst mismatch
									   (styling-css-05-b: :lang(fr-ca){font-style:italic} must
									   select the oblique @font-face, not the normal one).
									   Style is a strict TIER compared before weight, never
									   summed with it: fonts-desc-05-t asks for italic+bold
									   with both an italic/regular and an oblique/bold face
									   present — the weight-exact oblique face must NOT beat
									   the style-exact italic one (weight only breaks ties). */
					if (fs >= 0 && style >= 0) {
						if (fs != style)
							score += ((fs == 1 && style == 2) || (fs == 2 && style == 1)) ? 2 : 4;
					}
					/* Variant is a strict filter, not a scored preference:
					   small-caps requests only match small-caps faces, normal
					   requests only match normal faces (CSS font matching
					   step 7). If no face passes the filter, the family is
					   skipped entirely (CSS step: try next family). */
					if (variant >= 0 && fv != variant) {
						/* Blocked by the strict variant filter: remember as
						   a last-resort fallback (see fbOverall above). */										if (score < fbScore ||
											(score == fbScore && wscore < fbWscore)) {
											fbScore = score;
											fbWscore = wscore;
											fbOverall = f;
										}
						continue;
					}									if (score < bestScore ||
										(score == bestScore && wscore < bestWscore)) {
										bestScore = score;
										bestWscore = wscore;
										best = f;
									}
				}
			}		if (best != NULL) {
			if (getenv("MSVG_DBG_FONT") != NULL)
				fprintf(stderr, "[FONT] fam=%s w=%d s=%d v=%d -> face w=%s s=%s v=%d\n", fam, weight, style, variant,
						best->weight ? best->weight : "-", best->style ? best->style : "-", best->variant);
			if (bestOverall == NULL) bestOverall = best;
			return best;
		}
		}
		if (*p == ',') p++;
	}
	if (bestOverall == NULL && fbOverall != NULL) {
		if (getenv("MSVG_DBG_FONT") != NULL)
			fprintf(stderr, "[FONT] variant-fallback face w=%s s=%s v=%d\n",
					fbOverall->weight ? fbOverall->weight : "-",
					fbOverall->style ? fbOverall->style : "-", fbOverall->variant);
		return fbOverall;
	}
	return bestOverall;
}

// Shapes a run with an embedded SVG font. Mirrors the run-level shaper
// contract: returns the number of glyphs (may exceed max_glyphs -> caller
// retries), glyphs in LOGICAL order with 'cluster' = first source
// codepoint index, advances in FONT units, outlines in font units
// (y-down, baseline at 0). hkern pairs are applied to the left glyph's
// advance (SVG 1.1 §20.7: k decreases the spacing). Returns 0 when no
// embedded font matches (the external shaper handles the run).

// Builds the family list that comes AFTER the matched embedded font's own
// family in the run's family list. SVG 1.1 §20.4: a character the font
// cannot render falls back to the NEXT family in the list, so the per-char
// fallback needs that remainder. Matches the first list entry whose name
// equals the font's family case-insensitively (quotes/whitespace
// stripped, as in msvg__fontLookup); when the font's family is not listed
// (alias-rewritten requests) it falls back to skipping the first entry.
// Returns 1 when a non-empty remainder was produced.
static int msvg__svgFontNextFamily(const char* familyList, const MSVGfont* f,
								   char* out, size_t outSz)
{
	const char* p;
	const char* afterFirst = NULL;
	const char* matchEnd = NULL;
	if (familyList == NULL || out == NULL || outSz == 0) return 0;
	out[0] = 0;
	p = familyList;
	while (*p && *p != ',') p++;
	afterFirst = p;
	p = familyList;
	while (*p) {
		const char* start = p;
		const char* e;
		size_t n;
		int eq = (f != NULL && f->family != NULL);
		while (*p && *p != ',') p++;
		e = p;
		while (e > start && (e[-1] == ' ' || e[-1] == '\t')) e--;
		while (start < e && (*start == ' ' || *start == '\t')) start++;
		if (start < e && (*start == '\'' || *start == '"') && e[-1] == start[0]) {
			start++;
			e--;
		}
		n = (size_t)(e - start);
		if (eq && strlen(f->family) == n) {
			const char* ff = f->family;
			size_t k;
			for (k = 0; k < n; k++) {
				char a = start[k], b = ff[k];
				if (a >= 'A' && a <= 'Z') a = (char)(a - 'A' + 'a');
				if (b >= 'A' && b <= 'Z') b = (char)(b - 'A' + 'a');
				if (a != b) { eq = 0; break; }
			}
		} else {
			eq = 0;
		}
		if (eq) { matchEnd = p; break; }
		if (*p) p++;
	}
	{
		const char* rest = (matchEnd != NULL) ? matchEnd : afterFirst;
		if (rest == NULL || *rest != ',') return 0;
		rest++;
		while (*rest == ' ' || *rest == '\t') rest++;
		if (*rest == 0) return 0;
		strncpy(out, rest, outSz - 1);
		out[outSz - 1] = 0;
		return 1;
	}
}

/* 1 when an embedded SVG font matches the run's family list (same lookup
   as msvg__svgFontShape, which keeps the attribute-based disambiguation;
   weight/style/variant are irrelevant for the presence probe). Used to tag
   chunks shaped by an embedded SVG font so they anchor by glyph-ink bbox. */
static int msvg__svgFontProbe(const char* family, MSVGimage* img)
{
	MSVGfont* f;
	if (img == NULL || img->fonts == NULL || family == NULL)
		return 0;
	f = msvg__fontLookupWithAliases(img, family, -1, -1, -1);
	if (f == NULL || f->unitsPerEm <= 0.0f)
		return 0;
	return 1;
}

static int msvg__svgFontShape(MSVGimage* img, const char* family, float size,
							  int weight, int style, int variant,
							  const unsigned int* cps, int ncp,
							  MSVGshapedGlyph* glyphs, int max_glyphs,
							  float* upem, float* ascent, float* descent)
{
	MSVGfont* f;
	int need = 0;
	int i;
	if (img == NULL || img->fonts == NULL || cps == NULL || ncp <= 0)
		return 0;
	f = msvg__fontLookupWithAliases(img, family, weight, style, variant);
	if (f == NULL || f->unitsPerEm <= 0.0f)
		return 0;
	if (upem) *upem = f->unitsPerEm;
	if (ascent) *ascent = f->ascent;
	if (descent) *descent = f->descent;

	/* Pass 1: count glyphs (longest unicode match; ligatures consume >1). */
	for (i = 0; i < ncp; ) {
		int glen = 1;
		MSVGglyph* g = msvg__fontFindGlyph(f, cps + i, ncp - i, &glen);
		if (g == NULL) glen = 1;
		need++;
		i += glen;
	}
	if (glyphs == NULL || max_glyphs < need)
		return need;

	/* Pass 2: fill. */
	{
		int gi = 0;
		MSVGglyph* prev = NULL;
		/* Per-char fallback decision (SVG 1.1 §20.4): chars the font covers
		   (or covers via a user-assigned <missing-glyph> box) shape from the
		   SVG font; chars that hit the box fall back to the next families
		   in the run's list (the box is drawn only when no family renders
		   the char). Joins are shaped across WHOLE fallback spans: Arabic
		   init/medi/fina forms depend on neighbors, so a run 00AB (ab
		   fallback) must shape "cab" together, not c|a|b one at a time. */
		signed char* spanFb = NULL;
		int nSpanFb = 0;
		char nextFam[256];
		nextFam[0] = 0;
		/* The SVG font's own space advance (font units). Preserved
		   literal \n/\t inside a fallback span advance by THIS amount
		   with no outline — the farm advances whitespace by the primary
		   font's space metrics even when neighboring chars come from
		   the fallback (text-ws-02-t gap1/gap2 measurements). */
		float wsAdv = 0.0f;
		{
			MSVGglyph* sg;
			for (sg = f->glyphs; sg != NULL; sg = sg->next)
				if (sg->unicode != NULL && sg->unicode[0] == ' ' &&
					sg->unicode[1] == '\0') {
					wsAdv = (sg->horizAdvX > 0.0f) ? sg->horizAdvX
						: (f->horizAdvX > 0.0f ? f->horizAdvX : 0.0f);
					break;
				}
		}
		{
			int anyFb = 0;
			for (i = 0; i < ncp; i++) {
				MSVGglyph* g = msvg__fontFindGlyph(f, cps + i, ncp - i, &(int){1});
				if (g == NULL && f->missingGlyph != NULL) anyFb = 1;
			}
			if (anyFb && msvg__svgFontNextFamily(family, f, nextFam, sizeof(nextFam)))
				nSpanFb = 1;
		}
		if (nSpanFb) {
			spanFb = (signed char*)calloc((size_t)ncp, 1);
			if (spanFb != NULL) {
				i = 0;
				while (i < ncp) {
					MSVGglyph* g = msvg__fontFindGlyph(f, cps + i, ncp - i, &(int){1});
					if (g == NULL)
						spanFb[i] = 1;
					i++;
				}
			}
		}
		for (i = 0; i < ncp; ) {
			int glen = 1;
			MSVGglyph* g = msvg__fontFindGlyph(f, cps + i, ncp - i, &glen);
			float adv;
			if (g == NULL) {
				g = f->missingGlyph;
				glen = 1;
			}
			adv = (g != NULL && g->horizAdvX > 0.0f) ? g->horizAdvX
					: (f->horizAdvX > 0.0f ? f->horizAdvX : 0.0f);
			/* hkern: k is "the amount to decrease the spacing between the
			   two glyphs" (SVG 1.1 §20.7), so the second glyph sits at
			   left.advance - k — subtract k from the left glyph's
			   advance (fonts-kern-01-t: (250 - (-1000))/1000*10 = 12.5). */
			if (gi > 0) {
				float k = msvg__fontKern(f, prev, g);
				glyphs[gi - 1].x_advance -= k;
			}
			glyphs[gi].cluster = (unsigned int)i;
			glyphs[gi].x_advance = adv;
			glyphs[gi].x_offset = 0.0f;
			glyphs[gi].y_offset = 0.0f;
			glyphs[gi].outline = NULL;
			if (spanFb != NULL && spanFb[i]) {
				/* The box glyph exists but this char falls back: shape the
				   whole fallback span with the run shaper (next families in
				   the list) and emit the fallback glyphs BEFORE continuing
				   with the SVG font. Clusters keep pointing at the source
				   chars; advance scale = size/upem is applied by the caller
				   using the SVG font's upem, so fallback advances are
				   rescaled from the fallback font's upem into f's. */
				int j = i;
				while (j < ncp && spanFb[j]) j++;
				{
					int span = j - i;
					int maxg = span + 8;
					MSVGshapedGlyph* og = (MSVGshapedGlyph*)
						calloc((size_t)maxg, sizeof(MSVGshapedGlyph));
					float ofupem = 0.0f, ofa = 0.0f, ofd = 0.0f;
					int on;
					img->svgFontFallbackActive = 1;
					on = img->textShaperRun(img, nextFam, size, weight, style,
						0, 0.0f, cps + i, span, og, maxg,
						&ofupem, &ofa, &ofd, img->textShaperRunData);
					if (on > maxg) {
						MSVGshapedGlyph* og2 = (MSVGshapedGlyph*)
							realloc(og, (size_t)on * sizeof(MSVGshapedGlyph));
						if (og2 != NULL) {
							og = og2;
							maxg = on;
							on = img->textShaperRun(img, nextFam, size, weight, style,
								0, 0.0f, cps + i, span, og, maxg,
								&ofupem, &ofa, &ofd, img->textShaperRunData);
						}
					}
					img->svgFontFallbackActive = 0;
					if (on > 0 && ofupem > 0.0f) {
						float r = f->unitsPerEm / ofupem;
						int q;
						for (q = 0; q < on && gi < max_glyphs; q++) {
							MSVGpath* pp;
							unsigned int cl = og[q].cluster;
							if (cl >= (unsigned int)span) cl = 0;
							glyphs[gi].cluster = (unsigned int)(i + (int)cl);
							/* XML whitespace inside a fallback span keeps the SVG
							   font's own space advance with no outline (the farm
							   advances every preserved \n/\t by the primary font's
							   space, not the fallback's: text-ws-02-t gap1 =
							   3x278/1000em, not 3x the fallback space). */
							if (wsAdv > 0.0f && i + (int)cl < ncp &&
								(cps[i + (int)cl] == '\t' || cps[i + (int)cl] == '\n' ||
								 cps[i + (int)cl] == '\r' || cps[i + (int)cl] == 0x0B ||
								 cps[i + (int)cl] == 0x0C)) {
								if (og[q].outline != NULL) {
									msvg__deletePaths(og[q].outline);
									og[q].outline = NULL;
								}
								glyphs[gi].x_advance = wsAdv;
								glyphs[gi].x_offset = 0.0f;
								glyphs[gi].y_offset = 0.0f;
								glyphs[gi].outline = NULL;
								gi++;
								continue;
							}
							glyphs[gi].x_advance = og[q].x_advance * r;
							glyphs[gi].x_offset = og[q].x_offset * r;
							glyphs[gi].y_offset = og[q].y_offset * r;
							glyphs[gi].outline = NULL;
							for (pp = og[q].outline; pp != NULL; pp = pp->next) {
								int pi;
								for (pi = 0; pi < pp->npts; pi++) {
									pp->pts[pi * 2] *= r;
									pp->pts[pi * 2 + 1] *= r;
								}
							}
							glyphs[gi].outline = og[q].outline;
							og[q].outline = NULL;
							gi++;
						}
						for (; q < maxg; q++)
							if (og[q].outline != NULL)
								msvg__deletePaths(og[q].outline);
						free(og);
						/* prev stays: the SVG-font glyph to the left kerned
						   against the box; the next SVG-font glyph (after the
						   span) kerns against its own left neighbor via the
						   g==missingGlyph lookup below (prev==NULL-safe). */
						prev = NULL;
						i = j;
						continue;
					}
					{
						int q;
						for (q = 0; q < maxg; q++)
							if (og[q].outline != NULL)
								msvg__deletePaths(og[q].outline);
					}
					free(og);
					/* Shaper failed: draw the box glyph (set up above). */
				}
			} else if (g != NULL && g->paths != NULL) {
				glyphs[gi].outline = msvg__copyPaths(g->paths);
			} else if (img->textShaperRun != NULL) {
				/* SVG 1.1 §20.4: a character the font can't render (no glyph
				   and no <missing-glyph>) falls back to the next font in the
				   family list for that ONE character (fonts-glyph-04-t: the
				   'l' of SVGFont1 "ffl" is drawn by the sans-serif fallback,
				   keeping the SVG font's advance). Shape just this codepoint
				   with the run shaper and scale its outline/advance into this
				   font's units-per-em space. */
				MSVGshapedGlyph og[1];
				float ofupem = 0.0f, ofa = 0.0f, ofd = 0.0f;
				int on = 0;
				memset(og, 0, sizeof(og));
				on = img->textShaperRun(img, family, size, weight, style, 0, 0.0f,
									 cps + i, 1, og, 1, &ofupem, &ofa, &ofd,
									 img->textShaperRunData);
				if (on > 0 && ofupem > 0.0f && og[0].outline != NULL) {
					MSVGpath* pp;
					float r = f->unitsPerEm / ofupem;
					glyphs[gi].x_advance = og[0].x_advance * r;
					glyphs[gi].x_offset = og[0].x_offset * r;
					glyphs[gi].y_offset = og[0].y_offset * r;
					for (pp = og[0].outline; pp != NULL; pp = pp->next) {
						int pi;
						for (pi = 0; pi < pp->npts; pi++) {
							pp->pts[pi * 2] *= r;
							pp->pts[pi * 2 + 1] *= r;
						}
					}
					glyphs[gi].outline = og[0].outline;
				} else {
					if (og[0].outline) msvg__deletePaths(og[0].outline);
				}
			}
			prev = g;
			gi++;
			i += glen;
		}
		free(spanFb);
	}
	return need;
}

static MSVGgradient* msvg__createGradient(MSVGparser* p, const char* id, const float* localBounds, float *xform, signed char* paintType)
{
	MSVGgradientData* data = NULL;
	MSVGgradientData* ref = NULL;
	MSVGgradientStop* stops = NULL;
	MSVGgradientData* src = NULL;
	MSVGgradient* grad;
	float ox, oy, sw, sh, sl;
	int nstops = 0;
	int refIter;

	data = msvg__findGradientData(p, id);
	if (data == NULL) return NULL;
	if (getenv("MSVG_DBG_C07") != NULL)
		fprintf(stderr, "[G1 ] createGradient id='%s'\n", id);

	// TODO: use ref to fill in all unset values too.
	ref = data;
	refIter = 0;
	while (ref != NULL) {
		MSVGgradientData* nextRef = NULL;
		if (stops == NULL && ref->stops != NULL) {
			stops = ref->stops;
			nstops = ref->nstops;
			src = ref;
			break;
		}
		nextRef = msvg__findGradientData(p, ref->ref);
		if (nextRef == ref) break; // prevent infite loops on malformed data
		ref = nextRef;
		refIter++;
		if (refIter > 32) break; // prevent infite loops on malformed data
	}
	if (getenv("MSVG_DBG_C07") != NULL)
		fprintf(stderr, "[G2 ] id='%s' stops=%s nstops=%d\n", id,
			stops == NULL ? "(null)" : "found", nstops);
	if (stops == NULL) return NULL;

	grad = (MSVGgradient*)malloc(sizeof(MSVGgradient));
	if (grad == NULL) return NULL;
	grad->data = (void*)data;	/* source data for frame-time spread writes */

	// The shape width and height.
	if (data->units == MSVG_OBJECT_SPACE) {
		/* SVG 1.1 §7.11 (keyword objectBoundingBox): "if the geometry of the
		   element has zero width or height, the effect is as if the keyword
		   were not specified" — i.e. the gradient is not applied. Leave the
		   paint UNDEF so the element's <paint> fallback (or nothing) is used
		   (pservers-grad-17-b/20-b: gradient stroked lines have a zero-area
		   bbox unless rotated; official refs use the green fallback). */
			/* Degeneracy uses a small epsilon, not an exact-zero test:
			   float-noise transforms (e.g. rotate(90) stores
			   cos(90deg) ~= -4.4e-8) leave a zero-area bbox ~1e-5 wide
			   in user units, which would wrongly re-validate the
			   gradient. The reference UA computes in double precision
			   where the noise is ~1e-14, i.e. degenerate; any genuine
			   bbox is macroscopic, so 1e-3 user units is safe and
			   matches the fallback semantics of pservers-grad-17-b/20-b
			   (per-line: axis-aligned = fallback green, diagonal =
			   gradient). */
		if (localBounds[2] - localBounds[0] <= 1.0e-3f ||
			localBounds[3] - localBounds[1] <= 1.0e-3f) {
			*paintType = MSVG_PAINT_UNDEF;
			free(grad);	/* degenerate bbox: the allocated gradient
						   shell never reaches the paint — free it
						   (pservers-grad-17-b/20-b, LSan-found) */
			return NULL;
		}
		ox = localBounds[0];
		oy = localBounds[1];
		sw = localBounds[2] - localBounds[0];
		sh = localBounds[3] - localBounds[1];
	} else {
		ox = msvg__actualOrigX(p);
		oy = msvg__actualOrigY(p);
		sw = msvg__actualWidth(p);
		sh = msvg__actualHeight(p);
	}
	sl = sqrtf(sw*sw + sh*sh) / sqrtf(2.0f);

	if (data->type == MSVG_PAINT_LINEAR_GRADIENT) {
		float x1, y1, x2, y2, dx, dy;
		/* objectBoundingBox (SVG 2 §14.2): the gradient's coordinate system
		   is the bounding box itself. Unitless coordinates are fractions of
		   the box (x2="1" spans the full width); percentages resolve against
		   the box; absolute units (px/pt/...) are converted to user units in
		   that space, where one unit equals one box width/height. So resolve
		   everything against a unit box (orig=0, length=1) here, build the
		   base transform in bbox space, and map bbox -> user space (scale by
		   sw/sh, translate by ox/oy) AFTER the gradientTransform, which also
		   lives in bbox space. userSpaceOnUse instead resolves directly in
		   user space. */
		if (data->units == MSVG_OBJECT_SPACE) {
			x1 = msvg__convertToPixels(p, data->linear.x1, 0.0f, 1.0f);
			y1 = msvg__convertToPixels(p, data->linear.y1, 0.0f, 1.0f);
			x2 = msvg__convertToPixels(p, data->linear.x2, 0.0f, 1.0f);
			y2 = msvg__convertToPixels(p, data->linear.y2, 0.0f, 1.0f);
		} else {
			x1 = msvg__convertToPixels(p, data->linear.x1, ox, sw);
			y1 = msvg__convertToPixels(p, data->linear.y1, oy, sh);
			x2 = msvg__convertToPixels(p, data->linear.x2, ox, sw);
			y2 = msvg__convertToPixels(p, data->linear.y2, oy, sh);
		}
		// Calculate transform aligned to the line
		dx = x2 - x1;
		dy = y2 - y1;
		grad->xform[0] = dy; grad->xform[1] = -dx;
		grad->xform[2] = dx; grad->xform[3] = dy;
		grad->xform[4] = x1; grad->xform[5] = y1;
	} else {
		float cx, cy, fx, fy, r;
		if (data->units == MSVG_OBJECT_SPACE) {
			/* objectBoundingBox (SVG 2 §14.2): the rings are circular in
			   bbox space (cx, cy, r resolved against the unit box); the
			   non-uniform bbox -> user-space scale (sw, sh) maps them to
			   ellipses in user space. gradientTransform is applied in bbox
			   space too (below), then the bbox -> user map. */
			cx = msvg__convertToPixels(p, data->radial.cx, 0.0f, 1.0f);
			cy = msvg__convertToPixels(p, data->radial.cy, 0.0f, 1.0f);
			fx = msvg__convertToPixels(p, data->radial.fx, 0.0f, 1.0f);
			fy = msvg__convertToPixels(p, data->radial.fy, 0.0f, 1.0f);
			r = msvg__convertToPixels(p, data->radial.r, 0.0f, 1.0f);
			/* Transform: bbox unit circle. Local space is the unit circle
			   |g| = 1; the bbox -> user scale below makes it an ellipse. */
			grad->xform[0] = r; grad->xform[1] = 0;
			grad->xform[2] = 0; grad->xform[3] = r;
			grad->xform[4] = cx; grad->xform[5] = cy;
		} else {
			/* userSpaceOnUse: resolved in user space; the radius resolves
			   against the normalized diagonal sl, and the rings are circles
			   in user space (uniform scale). */
			cx = msvg__convertToPixels(p, data->radial.cx, ox, sw);
			cy = msvg__convertToPixels(p, data->radial.cy, oy, sh);
			fx = msvg__convertToPixels(p, data->radial.fx, ox, sw);
			fy = msvg__convertToPixels(p, data->radial.fy, oy, sh);
			r = msvg__convertToPixels(p, data->radial.r, 0, sl);
			// Calculate transform aligned to the circle
			grad->xform[0] = r; grad->xform[1] = 0;
			grad->xform[2] = 0; grad->xform[3] = r;
			grad->xform[4] = cx; grad->xform[5] = cy;
		}
		// Focus relative to the circle center, in unit-circle space (the same
		// space the scanline's transformed points live in: g = (p - c) / r).
		// Both the focus and the circle are in the same local space, so any
		// gradientTransform / shape transform cancels out.
		grad->fx = (fx - cx) / r;
		grad->fy = (fy - cy) / r;
	}

	/* gradientTransform applies in the gradient's own coordinate system:
	   bbox space for objectBoundingBox, user space for userSpaceOnUse. For
	   objectBoundingBox, map bbox -> user space (scale sw/sh, translate
	   ox/oy) only after the gradientTransform. The shape transform is
	   outermost. */
	msvg__xformMultiply(grad->xform, data->xform);
	if (data->units == MSVG_OBJECT_SPACE) {
		float b2u[6];
		msvg__xformSetScale(b2u, sw, sh);
		b2u[4] = ox; b2u[5] = oy;
		msvg__xformMultiply(grad->xform, b2u);
	}
	msvg__xformMultiply(grad->xform, xform);

	grad->spread = data->spread;
	/* compiled gradients share the DATA's spread live when the frame-time
	   pass re-bakes it (animate-elem-91-t): read through the back-pointer
	   would double-copy here; instead the cache init (msvg__initPaint) and
	   the data itself both reflect the frozen value because the structural
	   pass writes data->spread and every compiled grad re-reads it at
	   raster via its source pointer below. */
	grad->data = (void*)data;
	grad->colorInterp = data->colorInterp;
	/* BORROW the source gradient data's stop array (see MSVGgradient): the
	   image owns it for its whole lifetime, and sharing it is what lets a
	   per-frame stop-paint recompute reach every referencing shape. */
	grad->stops = stops;
	grad->nstops = nstops;
	grad->stopSrc = (void*)src;	/* stop re-reads (initPaint) follow the
						   BORROWED source, not the referencing
						   data — chain borrowers have no own
						   stops (see MSVGgradient::stopSrc) */

	*paintType = data->type;
	if (getenv("MSVG_DBG_C07") != NULL)
		fprintf(stderr, "[G3 ] id='%s' paintType=%d nstops=%d stop0=%08x stop1=%08x\n", id,
			(int)data->type, (int)nstops, stops[0].color, nstops>1 ? stops[1].color : 0);

	return grad;
}

static float msvg__getAverageScale(const float* t)
{
	float sx = sqrtf(t[0]*t[0] + t[2]*t[2]);
	float sy = sqrtf(t[1]*t[1] + t[3]*t[3]);
	return (sx + sy) * 0.5f;
}

static void msvg__getLocalBounds(float* bounds, MSVGshape *shape, float* xform)
{
	MSVGpath* path;
	float curve[4*2], curveBounds[4];
	int i, first = 1;
	for (path = shape->paths; path != NULL; path = path->next) {
		msvg__xformPoint(&curve[0], &curve[1], path->pts[0], path->pts[1], xform);
		for (i = 0; i < path->npts-1; i += 3) {
			msvg__xformPoint(&curve[2], &curve[3], path->pts[(i+1)*2], path->pts[(i+1)*2+1], xform);
			msvg__xformPoint(&curve[4], &curve[5], path->pts[(i+2)*2], path->pts[(i+2)*2+1], xform);
			msvg__xformPoint(&curve[6], &curve[7], path->pts[(i+3)*2], path->pts[(i+3)*2+1], xform);
			msvg__curveBounds(curveBounds, curve);
			if (first) {
				bounds[0] = curveBounds[0];
				bounds[1] = curveBounds[1];
				bounds[2] = curveBounds[2];
				bounds[3] = curveBounds[3];
				first = 0;
			} else {
				bounds[0] = msvg__minf(bounds[0], curveBounds[0]);
				bounds[1] = msvg__minf(bounds[1], curveBounds[1]);
				bounds[2] = msvg__maxf(bounds[2], curveBounds[2]);
				bounds[3] = msvg__maxf(bounds[3], curveBounds[3]);
			}
			curve[0] = curve[6];
			curve[1] = curve[7];
		}
	}
}

static MSVGdef* msvg__defFind(MSVGparser* p, const char* id)
{
	MSVGdef* d;
	for (d = p->defs; d != NULL; d = d->next)
		if (strcmp(d->id, id) == 0)
			return d;
	return NULL;
}

static MSVGdef* msvg__defCreate(MSVGparser* p, const char* id)
{
	MSVGdef* d = (MSVGdef*)malloc(sizeof(MSVGdef));
	if (d == NULL) return NULL;
	memset(d, 0, sizeof(MSVGdef));
	if (id != NULL)
		strncpy(d->id, id, 63);
	d->id[63] = '\0';
	msvg__xformIdentity(d->xform);
	/* Default context transform: identity. msvg__defOpen overwrites this
	   with the captured ancestor chain for every def it opens; parseSymbol
	   (which pushes onto openDefs directly) captures it explicitly. Without
	   a sane default a def whose context was never captured would carry a
	   zero matrix, whose inverse poisons every clone placement with NaN. */
	msvg__xformIdentity(d->contextXform);
	/* SVG 2 §5.11: preserveAspectRatio defaults to xMidYMid meet (same
	   default as pattern/marker creators). alignType=0 is ALIGN_NONE, so
	   memset alone would non-uniformly stretch symbol viewBoxes. */
	d->alignX = MSVG_ALIGN_MID;
	d->alignY = MSVG_ALIGN_MID;
	d->alignType = MSVG_ALIGN_MEET;
	/* Element-seq range: seeded from the current element-open seq (the def
	   root's own — defCreate runs after startElement pushed the root ctx) and
	   extended as descendants parse (defClose). */
	d->seqStart = d->seqEnd = p->elemSeq - 1;
	if (p->defsTail)
		p->defsTail->next = d;
	else
		p->defs = d;
	p->defsTail = d;
	return d;
}

// Registers a shape under the currently-open definitions (the innermost id
// first, then enclosing ids). A shape may belong to several defs at once.
static void msvg__defRegisterShape(MSVGparser* p, MSVGshape* shape)
{
	int i;
	MSVGdef* d;
	for (i = p->nOpenDefs - 1; i >= 0; i--) {
		d = p->openDefs[i];
		if (d == NULL) continue;
		{
			MSVGdefShape* ds = (MSVGdefShape*)malloc(sizeof(MSVGdefShape));
			if (ds == NULL) return;
			ds->shape = shape;
			/* Hidden state that carries into a <use> clone (SVG 2 §5.11.3:
			   the shadow tree re-inherits from the <use> element) is only
			   the referenced element's OWN display:none / visibility:hidden
			   — hiding applied by an ORIGINAL-tree ancestor does not carry,
			   because the clone does not inherit from the original tree
			   (struct-use-10-f: 'g#g1 {visibility:hidden}' must not hide the
			   used rect; 'g#g2 {display:none}' must not either). Own-hidden
			   = own attr frame computes hidden while the parent frame was
			   visible, i.e. the element specified it itself. */
			{
				MSVGattrib* a = msvg__getAttr(p);
				int ownHidden;
				if (p->attrHead > 0) {
					MSVGattrib* par = &p->attr[p->attrHead - 1];
					ownHidden = !(a->visible && a->visibility) &&
							(par->visible && par->visibility);
				} else
					ownHidden = !(a->visible && a->visibility);
				ds->visHidden = (char)ownHidden;
				/* Conditional-processing failure (requiredFeatures/
				   requiredExtensions/systemLanguage on the element itself):
				   the element is "not rendered" — its <use> instances must
				   also render nothing (SVG 1.1 §5.11). */
				ds->condHidden = (char)(p->switchSkipCtx >= 0);
			}
			ds->next = NULL;
			if (d->shapesTail)
				d->shapesTail->next = ds;
			else
				d->shapes = ds;
			d->shapesTail = ds;
		}
	}
}

// Opens a definition scope for an element that carries an id attribute.
// Returns 1 if a new def was opened (endElement must call msvg__defClose).
// Duplicate ids on nested elements are coalesced so a shape is never
// registered twice for the same def.
// 'el' is the element name of the def root; it is recorded (along with the
// ancestor transform at def-open) so <textPath> references can validate the
// target (path element or basic shape) and strip the defs' ancestor
// transforms (SVG 2 §10.12).
static int msvg__defOpen(MSVGparser* p, const char* id, const char* el)
{
	MSVGdef* d;
	int i;
	if (id == NULL || id[0] == '\0')
		return 0;
	if (p->nOpenDefs >= MSVG_MAX_ATTR)
		return 0;
	d = msvg__defFind(p, id);
	if (d == NULL) {
		d = msvg__defCreate(p, id);
		if (d != NULL) {
			/* Capture the transform context at the def root: the ancestors'
			   transform in effect before the def root's own transform is
			   applied. For shape defs (path/rect/...) defOpen runs before
			   parseAttribs, so this is exactly the inherited chain; textPath
			   geometry = baked points · inv(contextXform) removes it. */
			memcpy(d->contextXform, msvg__getAttr(p)->xform, sizeof(float) * 6);
			strncpy(d->rootName, el ? el : "", sizeof(d->rootName) - 1);
			d->rootName[sizeof(d->rootName) - 1] = '\0';
		}
	}
	// Coalesce if this def is already open (e.g. nested <g> inheriting the id).
	for (i = 0; i < p->nOpenDefs; i++)
		if (p->openDefs[i] == d)
			return 0;
	p->openDefs[p->nOpenDefs++] = d;
	/* Record the (base-relative) chain depth at def-open, before the def
	   root's own opacity group is pushed, so <use> clones can take only the
	   def-internal groups. */
	d->groupChainStart = msvg__getAttr(p)->groupDepth - msvg__groupBase(p);
	/* Attr-stack frame of the def root element: explicit paints specified
	   at this index or deeper live inside the referenced subtree and
	   survive <use> cloning; shallower ones are document-context
	   inheritance and re-inherit from the <use> element. */
	d->attrStart = p->attrHead;
	/* Def-context fill/stroke-opacity (CSS cascade): the alpha baked into
	   the def's shapes' packed colors assumed this opacity. When the def
	   is cloned by a <use> whose shadow tree specifies (or inherits) a
	   DIFFERENT fill/stroke-opacity, the clone's alpha is un-baked (÷
	   def value) and re-baked (× use-site value) — SVG 2 §5.11.3. */
	d->fillOpacity = msvg__getAttr(p)->fillOpacity;
	d->strokeOpacity = msvg__getAttr(p)->strokeOpacity;
	return 1;
}

static void msvg__defClose(MSVGparser* p)
{
	if (p->nOpenDefs > 0) {
		MSVGdef* d = p->openDefs[p->nOpenDefs - 1];
		if (d != NULL && d->seqStart >= 0 && p->elemSeq > d->seqEnd)
			d->seqEnd = p->elemSeq - 1;
		p->nOpenDefs--;
	}
}

// Forward declaration (defined later): applies <style> element rules matching
// the current element to its attributes.
static void msvg__applyStyles(MSVGparser* p);

/* SVG 1.1 §11.1.2: 'currentColor' is a COMPUTED value — it resolves
   against the 'color' of the element where the fill/stroke was DECLARED,
   NOT the current element's own 'color' (color-prop-05-t:
   <g fill="currentColor" color="lime"><rect color="red"/> — the rect
   must paint lime, because it inherits the computed fill, not the
   keyword). The declaring element is the attr-stack frame at specIdx
   (fillSpecIdx/strokeSpecIdx); it is always still on the stack at capture
   time (an ancestor of the shape being built). Falls back to the shape's
   own color if the frame is gone. The inherited hasFillCC/hasStrokeCC
   markers stay set so a SMIL 'color' animation on the declaring element
   can still re-resolve the paint (animate-elem-78-t). */
static unsigned int msvg__ccColor(const MSVGparser* p, const MSVGattrib* attr, int specIdx)
{
	if (specIdx >= 0 && specIdx <= p->attrHead)
		return p->attr[specIdx].color;
	return attr->color;
}

/* Forward: conditional-processing evaluator (defined below with the
   <switch> handling, but used by every shape capture — SVG 1.1 §5.11). */
static int msvg__switchConditionsMatch(const MSVGparser* p, const char** attr);

static void msvg__addShape(MSVGparser* p, const char** elAttr)
{
	MSVGattrib* attr = msvg__getAttr(p);
	float scale = 1.0f;
	MSVGshape* shape;
	MSVGpath* path;
	int i;
	(void)elAttr;	/* conditionals were evaluated at the element-open site */
	// <style> element rules were already applied by parseAttribs in the
	// correct cascade order (presentation attrs < element rules < inline
	// style=""). Re-applying them here would clobber the element's own
	// inline style, which must win per the CSS cascade (SVG 2 styling
	// chapter). See msvg__parseAttribs.

	if (p->plist == NULL) {
		/* No geometry (e.g. malformed path data): release the SMIL capture
		   so the parser stays leak-free on error-tolerant input. */
		if (p->curGeomPoints != NULL) {
			free(p->curGeomPoints);
			p->curGeomPoints = NULL;
		}
		if (p->curGeomPath != NULL) {
			free(p->curGeomPath);
			p->curGeomPath = NULL;
		}
		p->curGeomKind = 0;
		p->curGeomFlags = 0;
		p->nCurGeomPoints = 0;
		return;
	}

	shape = (MSVGshape*)malloc(sizeof(MSVGshape));
	if (shape == NULL) goto error;
	memset(shape, 0, sizeof(MSVGshape));

	memcpy(shape->id, attr->id, sizeof shape->id);
	memcpy(shape->fillGradient, attr->fillGradient, sizeof shape->fillGradient);
	memcpy(shape->strokeGradient, attr->strokeGradient, sizeof shape->strokeGradient);
	memcpy(shape->clipRef, attr->clipId, sizeof shape->clipRef);
	memcpy(shape->clipFunc, attr->clipFunc, sizeof shape->clipFunc);
	/* clip-path on an ENCLOSING container applies to the subtree (SVG 1.1
	   §14.3.3). A shape without its own clip takes the innermost
	   enclosing one (same user space; the clip content maps through the
	   shape's full CTM like any userSpaceOnUse clip). A shape WITH its
	   own clip keeps it and additionally records the enclosing ref — the
	   regions intersect (each user space composes through its own CTM).
	   NOT while parsing a <clipPath>: a clipPath's children establish the
	   clip's geometry and are not part of the ancestor's rendered
	   subtree — they must not inherit the ancestor's clip-path (SVG 1.1
	   §14.3.4 / CSS Masking §8; masking-path-14-f: a clipPath defined
	   inside a clip-path'd <g> otherwise intersects to empty). */
	if (!p->clipFlag && p->attrHead > 0 && p->enclosingClipAt[p->attrHead - 1][0] != '\0') {
		if (shape->clipRef[0] == '\0' && shape->clipFunc[0] == '\0') {
			strncpy(shape->clipRef, p->enclosingClipAt[p->attrHead - 1],
					sizeof shape->clipRef - 1);
			shape->clipRef[sizeof shape->clipRef - 1] = '\0';
			/* The enclosing clip was established by an ancestor element:
			   its CTM (recorded at that element's open) is the clip
			   referencing user space (SVG 1.1 §14.3.4). */
			memcpy(shape->clipRefCTM, p->enclosingClipCTM[p->attrHead - 1],
					sizeof(float) * 6);
			/* Folded provenance marker: the baked clip content is anchored
			   in the CONTAINER's space (clipRefCTM above), so a frame-time
			   viewport conjugation of this element's own mapping (PAR
			   freeze) must not re-map it. */
			shape->flags |= MSVG_FLAGS_ENCSUB_CLIP;
		} else if (shape->clipRef[0] != '\0') {
			strncpy(shape->groupClipRef, p->enclosingClipAt[p->attrHead - 1],
					sizeof shape->groupClipRef - 1);
			shape->groupClipRef[sizeof shape->groupClipRef - 1] = '\0';
		}
	}
	/* Nested <svg> viewport clip (SVG 2 §5.4): when this shape carries no
	   clip-path of its own (and no enclosing container clip), clip it to
	   the innermost enclosing embedded <svg>'s viewport rectangle
	   (registered at parse as a synthetic <clipPath>). Skipped inside a
	   <clipPath>: the children define geometry, not rendered content. */
	if (!p->clipFlag && shape->clipRef[0] == '\0' && shape->clipFunc[0] == '\0') {
		int lvl;
		for (lvl = p->attrHead - 1; lvl >= 0; lvl--) {
			if (p->nestedClipAt[lvl][0] != '\0') {
				strncpy(shape->clipRef, p->nestedClipAt[lvl],
						sizeof shape->clipRef - 1);
				shape->clipRef[sizeof shape->clipRef - 1] = '\0';
				break;
			}
		}
	}
	/* The OWN clip maps through the element's own CTM at parse time
	   (the element is the clip-referencing element). Keyed on the
	   element's own attr frame: shape->clipRef may already hold the
	   INHERITED enclosing-group ref (which stored the group's CTM
	   above) — that one must not be overwritten with the leaf CTM. */
	if (attr->clipId[0] != '\0' || attr->clipFunc[0] != '\0')
		memcpy(shape->clipRefCTM, attr->xform, sizeof(float) * 6);
	memcpy(shape->maskRef, attr->maskRef, sizeof shape->maskRef);
	/* mask="" on the element itself: the element's own CTM is the mask
	   referencing user space (SVG 1.1 §14.9.2). */
	if (attr->maskRef[0] != '\0')
		memcpy(shape->maskRefCTM, attr->xform, sizeof(float) * 6);
	/* Same subtree rule for mask on an enclosing container (SVG 1.1
	   §14.9.2): a shape without its own mask takes the enclosing one;
	   the container's CTM (recorded at its open) is the referencing
	   space. */
	if (shape->maskRef[0] == '\0' && p->attrHead > 0 &&
		p->enclosingMaskAt[p->attrHead - 1][0] != '\0') {
		strncpy(shape->maskRef, p->enclosingMaskAt[p->attrHead - 1],
				sizeof shape->maskRef - 1);
		shape->maskRef[sizeof shape->maskRef - 1] = '\0';
		memcpy(shape->maskRefCTM, p->enclosingMaskCTM[p->attrHead - 1],
				sizeof(float) * 6);
		/* Folded provenance marker (see MSVG_FLAGS_ENCSUB_CLIP). */
		shape->flags |= MSVG_FLAGS_ENCSUB_MASK;
	}
	memcpy(shape->filterRef, attr->filterRef, sizeof shape->filterRef);
	shape->imageRef = (attr->imageRef != NULL && attr->imageRef[0] != '\0') ? msvg__dupstr(attr->imageRef) : NULL;
	shape->elemType = p->curElemType;
	/* marker-start/mid/end references are resolved to pointers after the
	   full parse (forward refs); store the raw ids here for resolution. */
	memcpy(shape->markerStartId, attr->markerStart, sizeof shape->markerStartId);
	memcpy(shape->markerMidId, attr->markerMid, sizeof shape->markerMidId);
	memcpy(shape->markerEndId, attr->markerEnd, sizeof shape->markerEndId);
	shape->imageX = attr->imageX;
	shape->imageY = attr->imageY;
	shape->imageHasW = attr->imageHasW;
	shape->imageHasH = attr->imageHasH;
	shape->imageAlignX = attr->imageAlignX;
	shape->imageAlignY = attr->imageAlignY;
	shape->imageAlignType = attr->imageAlignType;
	/* SMIL: record the ids of the elements containing this shape (the
	   element-context stack already tracks name/id/class per element). */
	{
	int ci;
		shape->nOwnerIds = 0;
		for (i = 0; i <= p->ctxHead && shape->nOwnerIds < 8; i++) {
			if (p->ctx[i].id[0] != '\0')
				strncpy(shape->ownerIds[shape->nOwnerIds++], p->ctx[i].id, 63);
		}
		/* The shape's own element id (current context level) — geometry
		   animations only apply to the shape's own element. */
		shape->ownId[0] = '\0';
		if (p->ctxHead >= 0 && p->ctx[p->ctxHead].id[0] != '\0')
			strncpy(shape->ownId, p->ctx[p->ctxHead].id, 63);
		shape->elemSeq = (p->ctxHead >= 0) ? p->ctx[p->ctxHead].seq : -1;
		shape->ownAttrFrame = (p->ctxHead >= 0) ? p->ctx[p->ctxHead].attrFrame : 0;
		/* Record the element-open sequence of every containing element
		   (innermost-first is fine; the dispatch linear-searches it). */
		shape->nElemSeqs = 0;
		for (ci = p->ctxHead; ci >= 0 && shape->nElemSeqs < 24; ci--)
			shape->elemSeqs[shape->nElemSeqs++] = p->ctx[ci].seq;
	}
	/* SMIL geometry capture: copy the raw base geometry recorded by the
	   element builder (consumed here, then reset so the next shape doesn't
	   inherit it). The shape owns its copies. */
	{
		shape->geomKind = p->curGeomKind;
		if (p->curGeomKind != 0) {
			memcpy(shape->geom, p->curGeom, sizeof(float) * 8);
			shape->geomFlags = p->curGeomFlags;
			if (p->curGeomPoints != NULL && p->nCurGeomPoints > 0) {
				shape->nGeomPoints = p->nCurGeomPoints;
				shape->geomPoints = (float*)malloc(sizeof(float) * 2 * p->nCurGeomPoints);
				if (shape->geomPoints != NULL)
					memcpy(shape->geomPoints, p->curGeomPoints,
						   sizeof(float) * 2 * p->nCurGeomPoints);
			}
			if (p->curGeomPath != NULL) {
				size_t glen = strlen(p->curGeomPath) + 1;
				shape->geomPath = (char*)malloc(glen);
				if (shape->geomPath != NULL)
					memcpy(shape->geomPath, p->curGeomPath, glen);
			}
		}
		if (p->curGeomPoints != NULL) {
			free(p->curGeomPoints);
			p->curGeomPoints = NULL;
		}
		if (p->curGeomPath != NULL) {
			free(p->curGeomPath);
			p->curGeomPath = NULL;
		}
		p->curGeomKind = 0;
		p->curGeomFlags = 0;
		p->nCurGeomPoints = 0;
	}
	memcpy(shape->xform, attr->xform, sizeof shape->xform);
	memcpy(shape->ownXform, attr->ownXform, sizeof shape->ownXform);
	msvg__xformIdentity(shape->defInnerXform);
	shape->hasPathLength = attr->hasPathLength;
	shape->pathLength = attr->pathLength;
	scale = msvg__getAverageScale(attr->xform);
	if (getenv("MSVG_DBG_XF") != NULL && attr->strokeWidth != 0.0f)
		fprintf(stderr, "[XF] strokeW=%.1f xform=[%.2f %.2f %.2f %.2f %.2f %.2f] avg=%.2f baked=%.2f\n",
			attr->strokeWidth, attr->xform[0], attr->xform[1], attr->xform[2], attr->xform[3], attr->xform[4], attr->xform[5], scale, attr->strokeWidth*scale);
	shape->vectorEffect = attr->vectorEffect;
	/* vector-effect: non-scaling-stroke computes the stroke outline in host
	   (screen) space; non-scaling-size keeps the user coordinate system's
	   scale fixed (which also implies non-scaling-stroke). In both cases the
	   stroke width/dashes/offset are NOT scaled by the element transform
	   (and later, in scaleToViewbox, not by the viewBox either). The
	   geometry itself is transformed as usual. */
	if (attr->vectorEffect != MSVG_VECTOR_EFFECT_NONE) {
		shape->strokeWidth = attr->strokeWidth;
		shape->strokeDashOffset = attr->strokeDashOffset;
		shape->strokeDashCount = (char)attr->strokeDashCount;
		for (i = 0; i < attr->strokeDashCount; i++)
			shape->strokeDashArray[i] = attr->strokeDashArray[i];
	} else {
		/* SVG 2 §12.5: under a NON-UNIFORM transform the stroke outline is
		   the transform of the user-space stroke circle — an ellipse. The
		   parse-time bake turns the transform into an average-scale stroke
		   width (too thick along the ellipse's narrow axis, e.g.
		   animate-elem-35-t's blue path under scale(1 2) rotate(90): 15px
		   vs the reference's 10px). When the shape is stroked and its
		   accumulated transform is non-uniform, keep the stroke width in
		   USER units and capture the user-space base geometry so the
		   rasterizer expands the stroke there and transforms the outline
		   by the full xform (the same per-axis path SMIL transform deltas
		   use). Restricted to plain document shapes: pattern/clip/mask/
		   marker/defs content get additional bakes after addShape that
		   would invalidate a capture here (those retain the average-scale
		   approximation). */
		float sx = sqrtf(attr->xform[0]*attr->xform[0] + attr->xform[2]*attr->xform[2]);
		float sy = sqrtf(attr->xform[1]*attr->xform[1] + attr->xform[3]*attr->xform[3]);
		int aniso = (fabsf(sx - sy) > 0.001f);
		if (aniso && attr->hasStroke == 1 && !attr->strokeCtx &&
			attr->strokeWidth > 0.0f && !p->defsFlag && !p->patternFlag &&
			!p->clipFlag && !p->maskFlag && !p->markerFlag) {
			shape->staticAniso = 1;
			shape->strokeWidth = attr->strokeWidth;
			shape->strokeDashOffset = attr->strokeDashOffset;
			shape->strokeDashCount = (char)attr->strokeDashCount;
			for (i = 0; i < attr->strokeDashCount; i++)
				shape->strokeDashArray[i] = attr->strokeDashArray[i];
			/* (the user-space strokeBase capture happens after shape->paths
			   is attached, below) */
		} else {
			shape->strokeWidth = attr->strokeWidth * scale;
			shape->strokeDashOffset = attr->strokeDashOffset * scale;
			shape->strokeDashCount = (char)attr->strokeDashCount;
			for (i = 0; i < attr->strokeDashCount; i++)
				shape->strokeDashArray[i] = attr->strokeDashArray[i] * scale;
		}
	}
	shape->strokeLineJoin = attr->strokeLineJoin;
	shape->strokeLineCap = attr->strokeLineCap;
	shape->miterLimit = attr->miterLimit;
	shape->fillRule = attr->fillRule;
	shape->opacity = attr->opacity;
    shape->paintOrder = attr->paintOrder;
    shape->blendMode = attr->blendMode;

	/* Group-opacity chain: the enclosing groups (opacity < 1, blend mode,
	   or isolation) from the current base (content inside
	   defs/pattern/clip/mask/marker/symbol must not inherit groups from
	   outside that element), plus the shape's own compositing properties
	   as the innermost group when it has opacity < 1 or a blend mode
	   (SVG 2 §3.4.1: a single object's fill/stroke/markers composite
	   together, then fade/blend). */
	{
		int base = msvg__groupBase(p);
		shape->groupDepth = attr->groupDepth - base;
		if (shape->groupDepth > 0)
			memcpy(shape->groupChain, &attr->groupChain[base],
				   (size_t)shape->groupDepth * sizeof(MSVGgroupChain));
		if ((shape->opacity < 1.0f || shape->blendMode != MSVG_BLEND_NORMAL)
			&& shape->groupDepth < MSVG_MAX_GROUP_DEPTH) {
			shape->groupChain[shape->groupDepth].id = ++p->groupCounter;
			shape->groupChain[shape->groupDepth].kind = MSVG_CHAIN_GROUP;
			shape->groupChain[shape->groupDepth].opacity = shape->opacity;
			shape->groupChain[shape->groupDepth].blendMode = shape->blendMode;
			shape->groupDepth++;
		}
		/* The shape's own filter (non-inherited): the shape's rendered
		   fill/stroke/markers are the filter's SourceGraphic. */
		if (shape->filterRef[0] != '\0' && shape->groupDepth < MSVG_MAX_GROUP_DEPTH) {
			shape->groupChain[shape->groupDepth].id = ++p->groupCounter;
			shape->groupChain[shape->groupDepth].kind = MSVG_CHAIN_FILTER;
			strncpy(shape->groupChain[shape->groupDepth].filterRef, shape->filterRef,
					sizeof(shape->groupChain[shape->groupDepth].filterRef) - 1);
			shape->groupChain[shape->groupDepth].filterRef[
				sizeof(shape->groupChain[shape->groupDepth].filterRef) - 1] = '\0';
			shape->groupDepth++;
		}
		shape->opacity = 1.0f;
		shape->blendMode = MSVG_BLEND_NORMAL;
	}

	shape->paths = p->plist;
	p->plist = NULL;

	/* Static non-uniform transform (SVG 2 §12.5 elliptical stroke): the
	   paths are now attached; capture the user-space base for the stroke
	   expansion (set up by the aniso block above). */
	if (shape->staticAniso)
		msvg__captureStaticStrokeBase(shape);

	if (getenv("MSVG_DBG_PTS") != NULL && shape->paths != NULL && shape->paths->npts > 0)
		fprintf(stderr, "[PTS-add] first=(%.2f,%.2f) xf=[%.1f %.1f %.1f %.1f %.1f %.1f]\n",
			shape->paths->pts[0], shape->paths->pts[1],
			shape->xform[0], shape->xform[1], shape->xform[2], shape->xform[3], shape->xform[4], shape->xform[5]);
	// Calculate shape bounds
	shape->bounds[0] = shape->paths->bounds[0];
	shape->bounds[1] = shape->paths->bounds[1];
	shape->bounds[2] = shape->paths->bounds[2];
	shape->bounds[3] = shape->paths->bounds[3];
	for (path = shape->paths->next; path != NULL; path = path->next) {
		shape->bounds[0] = msvg__minf(shape->bounds[0], path->bounds[0]);
		shape->bounds[1] = msvg__minf(shape->bounds[1], path->bounds[1]);
		shape->bounds[2] = msvg__maxf(shape->bounds[2], path->bounds[2]);
		shape->bounds[3] = msvg__maxf(shape->bounds[3], path->bounds[3]);
	}

	/* pathLength (SVG 2 §9.6.1): scale all distance-along-path computations
	   (dash lengths + dash offset) by actualLength/pathLength. The paths and
	   dash values here are in user space (paths transformed by attr->xform at
	   addPath, dashes by the same avg scale), so the factor is computed in
	   local units: (userLength/scale)/pathLength. pathLength=0 is a scaling
	   factor of infinity per the spec: zero-length dashes stay zero, any
	   non-zero dash (and a non-zero offset) becomes +Infinity -> solid
	   stroke. Negative values were rejected at parse (error -> ignored). */
	if (attr->hasPathLength && scale > 0.0f) {
		float userLen = msvg__pathsLength(shape->paths);
		if (userLen > 0.0f) {
			if (attr->pathLength == 0.0f) {
				for (i = 0; i < shape->strokeDashCount; i++)
					shape->strokeDashArray[i] =
						(shape->strokeDashArray[i] > 0.0f) ? INFINITY : 0.0f;
				if (shape->strokeDashOffset > 0.0f)
					shape->strokeDashOffset = INFINITY;
			} else {
				float factor = (userLen / scale) / attr->pathLength;
				shape->strokeDashOffset *= factor;
				for (i = 0; i < shape->strokeDashCount; i++)
					shape->strokeDashArray[i] *= factor;
			}
		}
	}

	// Set fill
	if (attr->hasFill == 0) {
		shape->fill.type = MSVG_PAINT_NONE;
	} else if (attr->hasFill == 1 && attr->fillCtx) {
		shape->fill.type = (attr->fillCtx == 1) ? MSVG_PAINT_CONTEXT_FILL : MSVG_PAINT_CONTEXT_STROKE;
	} else if (attr->hasFill == 1) {
		shape->fill.type = MSVG_PAINT_COLOR;
		shape->fill.color = msvg__packPaint(attr->hasFillCC ? msvg__ccColor(p, attr, attr->fillSpecIdx) : attr->fillColor, attr->fillOpacity, attr->hasFillCC);
	} else if (attr->hasFill == 2) {
		shape->fill.type = MSVG_PAINT_UNDEF;
	}
	if (attr->imageRef != NULL && attr->imageRef[0] != '\0') {
		// <image> element: the raster content IS the fill.
		shape->fill.type = MSVG_PAINT_IMAGE;
		shape->fill.image = NULL;
	}

	// Set stroke
	if (attr->hasStroke == 0) {
		shape->stroke.type = MSVG_PAINT_NONE;
	} else if (attr->hasStroke == 1 && attr->strokeCtx) {
		shape->stroke.type = (attr->strokeCtx == 1) ? MSVG_PAINT_CONTEXT_FILL : MSVG_PAINT_CONTEXT_STROKE;
	} else if (attr->hasStroke == 1) {
		shape->stroke.type = MSVG_PAINT_COLOR;
		shape->stroke.color = msvg__packPaint(attr->hasStrokeCC ? msvg__ccColor(p, attr, attr->strokeSpecIdx) : attr->strokeColor, attr->strokeOpacity, attr->hasStrokeCC);
	} else if (attr->hasStroke == 2) {
		shape->stroke.type = MSVG_PAINT_UNDEF;
	}

	// Nearest-explicit paint spec indices (for <use> shadow-tree
	// re-inheritance, SVG 2 §5.11.3).
	shape->fillSpecIdx = attr->fillSpecIdx;
	shape->strokeSpecIdx = attr->strokeSpecIdx;
	shape->strokeWidthSpecIdx = attr->strokeWidthSpecIdx;
	shape->fillFallback = attr->fillFallback;
	shape->strokeFallback = attr->strokeFallback;

	// Capture the computed 'color' property + currentColor markers so a
	// SMIL 'color' property animation can update the paint at apply time.
	shape->color = attr->color;
	shape->hasFillCC = attr->hasFillCC;
	shape->hasStrokeCC = attr->hasStrokeCC;

	// Set flags. Content inside <defs>/<symbol>/<pattern>/<marker> is parsed
	// for reference but never rendered in place (the rasterizer skips
	// non-visible shapes).
	/* Rendered-in-place visibility AND the computed hidden state. Template
	   content (defs/mask/clip/pattern/marker) is parsed with !VISIBLE but
	   keeps the HIDDEN bit honest: only display:none/visibility:hidden
	   content must be excluded when the template is instantiated. */
	shape->flags = (char)((((attr->visible && attr->visibility && !p->defsFlag && !p->patternFlag && !p->clipFlag && !p->maskFlag && !p->markerFlag && !p->switchSkip && !p->foreignSkip && !p->nsSkip)
		? MSVG_FLAGS_VISIBLE : 0x00)
		| ((attr->visible && attr->visibility) ? 0x00 : MSVG_FLAGS_HIDDEN))
		/* keep folded-enclosing clip/mask provenance bits (set earlier
		   at the subtree-promotion fold site) */
		| (shape->flags & (MSVG_FLAGS_ENCSUB_CLIP | MSVG_FLAGS_ENCSUB_MASK)));
	/* Conditional-processing attributes evaluated on ANY element (SVG 1.1
	   §5.11): failure makes THIS element render nothing. Recorded as its
	   own flag (not a display change) so <use> instantiation and image
	   bounds still see the geometry. */
	shape->condFail = msvg__getAttr(p)->condFailed;

	/* FillPaint/StrokePaint filter inputs (§15.4): when the shape itself
	   carries the filter, its own computed paint is the paint source.
	   Captured here, after fill/stroke are fully resolved. */
	if (shape->filterRef[0] != '\0' && shape->groupDepth > 0) {
		MSVGgroupChain* fpChain = &shape->groupChain[shape->groupDepth - 1];
		if (fpChain->kind == MSVG_CHAIN_FILTER) {
			fpChain->fpFillKind = (char)(shape->fill.type == MSVG_PAINT_COLOR ? 1
				: shape->fill.type == MSVG_PAINT_NONE ? 0 : 2);				fpChain->fpFillColor = shape->fill.color;
				/* fill-opacity is baked into the packed paint's alpha byte
				   (premultiplied RGBA) — that is the surrogate alpha the
				   gradient path needs. */
				fpChain->fpFillOpacity =
					((shape->fill.color >> 24) & 0xff) / 255.0f;
				fpChain->fpStrokeKind = (char)(shape->stroke.type == MSVG_PAINT_COLOR ? 1
					: shape->stroke.type == MSVG_PAINT_NONE ? 0 : 2);
				fpChain->fpStrokeColor = shape->stroke.color;
				fpChain->fpStrokeOpacity =
					((shape->stroke.color >> 24) & 0xff) / 255.0f;
			memcpy(fpChain->fpFillRef, shape->fillGradient, sizeof fpChain->fpFillRef);
			memcpy(fpChain->fpStrokeRef, shape->strokeGradient, sizeof fpChain->fpStrokeRef);
		}
	}

	if (p->maskFlag && p->curMask != NULL) {
		// <mask> content: owned by the mask (never in the image's shape
		// list), baked into referencing space when the element closes.
		// Still registered in open defs: a <use> may reference graphics
		// elements defined inside a mask (SVG 1.1 §14.9.2 content model).
		msvg__defRegisterShape(p, shape);
		if (p->curMask->shapesTail)
			p->curMask->shapesTail->next = shape;
		else
			p->curMask->shapes = shape;
		p->curMask->shapesTail = shape;
		shape->next = NULL;
		return;
	}

	if (p->clipFlag && p->curClip != NULL) {
		// <clipPath> content: owned by the clip (never in the image's shape
		// list), baked into referencing space when the element closes.
		// Still registered in open defs: a <use> inside a clipPath may
		// reference graphics elements defined inside another clipPath
		// (SVG 1.1 §14.3.4 content model, masking-path-07-b).
		msvg__defRegisterShape(p, shape);
		if (p->curClip->shapesTail)
			p->curClip->shapesTail->next = shape;
		else
			p->curClip->shapes = shape;
		p->curClip->shapesTail = shape;
		shape->next = NULL;
		return;
	}

	if (p->patternFlag && p->curPattern != NULL) {
		// <pattern> content: owned by the pattern (never in the image's
		// shape list so viewBox scaling and image bounds skip it), and it
		// is baked into pattern space when the pattern element closes.
		// Still registered in open defs (a <use> may reference pattern
		// content, SVG 1.1 §13.3.2 content model).
		msvg__defRegisterShape(p, shape);
		if (p->curPattern->shapesTail)
			p->curPattern->shapesTail->next = shape;
		else
			p->curPattern->shapes = shape;
		p->curPattern->shapesTail = shape;
		shape->next = NULL;
		return;
	}

	if (p->markerFlag && p->curMarker != NULL) {
		// <marker> content: owned by the marker (never in the image's shape
		// list), baked into marker user space when the element closes.
		// Still registered in open defs (a <use> may reference marker
		// content, SVG 1.1 §11.6.2 content model).
		msvg__defRegisterShape(p, shape);
		if (p->curMarker->shapesTail)
			p->curMarker->shapesTail->next = shape;
		else
			p->curMarker->shapes = shape;
		p->curMarker->shapesTail = shape;
		shape->next = NULL;
		return;
	}

	// Register in open defs (so <use> can clone it).
	msvg__defRegisterShape(p, shape);

	// Add to tail. Defs/symbol content stays in the list (so msvgDelete frees
	// it) but is invisible and excluded from bounds/image-size computation.
	if (p->image->shapes == NULL)
		p->image->shapes = shape;
	else
		p->shapesTail->next = shape;
	p->shapesTail = shape;

	return;

error:
	if (shape) free(shape);
}

static void msvg__addPath(MSVGparser* p, char closed)
{
	MSVGattrib* attr = msvg__getAttr(p);
	MSVGpath* path = NULL;
	float bounds[4];
	float* curve;
	int i;

	if (p->npts < 4)
		return;

	if (closed)
		msvg__lineTo(p, p->pts[0], p->pts[1]);

	// Expect 1 + N*3 points (N = number of cubic bezier segments).
	if ((p->npts % 3) != 1)
		return;

	path = (MSVGpath*)malloc(sizeof(MSVGpath));
	if (path == NULL) goto error;
	memset(path, 0, sizeof(MSVGpath));

	path->pts = (float*)malloc(p->npts*2*sizeof(float));
	if (path->pts == NULL) goto error;
	path->closed = closed;
	path->npts = p->npts;

	// Transform path.
	for (i = 0; i < p->npts; ++i)
		msvg__xformPoint(&path->pts[i*2], &path->pts[i*2+1], p->pts[i*2], p->pts[i*2+1], attr->xform);

	// Find bounds
	for (i = 0; i < path->npts-1; i += 3) {
		curve = &path->pts[i*2];
		msvg__curveBounds(bounds, curve);
		if (i == 0) {
			path->bounds[0] = bounds[0];
			path->bounds[1] = bounds[1];
			path->bounds[2] = bounds[2];
			path->bounds[3] = bounds[3];
		} else {
			path->bounds[0] = msvg__minf(path->bounds[0], bounds[0]);
			path->bounds[1] = msvg__minf(path->bounds[1], bounds[1]);
			path->bounds[2] = msvg__maxf(path->bounds[2], bounds[2]);
			path->bounds[3] = msvg__maxf(path->bounds[3], bounds[3]);
		}
	}

	path->next = p->plist;
	p->plist = path;

	return;

error:
	if (path != NULL) {
		if (path->pts != NULL) free(path->pts);
		free(path);
	}
}

// We roll our own string to float because the std library one uses locale and messes things up.
/* String-to-double for SVG numbers. Accumulates digits directly into a
   double (no 64-bit integer part, so arbitrarily long digit runs don't
   overflow), then applies the fraction scale and exponent. Locale
   independent (SVG always uses '.'). Non-finite results (overflow,
   malformed exponent) clamp to 0.0 so a bad number can never poison
   geometry with NaN/Inf (error tolerance). */
static double msvg__atof(const char* s)
{
	const char* cur = s;
	double res = 0.0, sign = 1.0;
	double fracScale = 1.0;
	int fracDigits = 0;
	int hasIntPart = 0, hasFracPart = 0;

	// Parse optional sign
	if (*cur == '+') {
		cur++;
	} else if (*cur == '-') {
		sign = -1.0;
		cur++;
	}

	// Parse integer part (accumulate in double; precision beyond 2^53 is
	// irrelevant since double has ~15-17 significant digits anyway).
	while (msvg__isdigit(*cur)) {
		res = res * 10.0 + (double)(*cur - '0');
		hasIntPart = 1;
		cur++;
	}

	// Parse fractional part.
	if (*cur == '.') {
		cur++; // Skip '.'
		while (msvg__isdigit(*cur)) {
			if (fracDigits < 400) {
				res = res * 10.0 + (double)(*cur - '0');
				fracDigits++;
				fracScale *= 10.0;
			}
			hasFracPart = 1;
			cur++;
		}
		res /= fracScale;
	}

	// A valid number should have integer or fractional part.
	if (!hasIntPart && !hasFracPart)
		return 0.0;

	// Parse optional exponent
	if (*cur == 'e' || *cur == 'E') {
		int expSign = 1;
		long expPart = 0;
		cur++; // skip 'e'
		if (*cur == '+')
			cur++;
		else if (*cur == '-') {
			expSign = -1;
			cur++;
		}
		while (msvg__isdigit(*cur)) {
			if (expPart < 1000000)
				expPart = expPart * 10 + (long)(*cur - '0');
			cur++;
		}
		if (expPart != 0) {
			// Clamp the exponent to keep pow() finite; overflow then
			// resolves to 0.0 below (error tolerance).
			if (expSign * expPart > 308)
				return 0.0;
			if (expSign * expPart < -320)
				return 0.0;
			res *= pow(10.0, (double)(expSign * expPart));
		}
	}

	// Error tolerance: never return NaN/Inf from degenerate input.
	if (res != res || res > 1.7e308 || res < -1.7e308)
		return 0.0;
	return res * sign;
}


static const char* msvg__parseNumber(const char* s, char* it, const int size)
{
	const int last = size-1;
	int i = 0;

	// sign
	if (*s == '-' || *s == '+') {
		if (i < last) it[i++] = *s;
		s++;
	}
	// integer part
	while (*s && msvg__isdigit(*s)) {
		if (i < last) it[i++] = *s;
		s++;
	}
	if (*s == '.') {
		// decimal point
		if (i < last) it[i++] = *s;
		s++;
		// fraction part
		while (*s && msvg__isdigit(*s)) {
			if (i < last) it[i++] = *s;
			s++;
		}
	}
	// exponent
	if ((*s == 'e' || *s == 'E') && (s[1] != 'm' && s[1] != 'x')) {
		if (i < last) it[i++] = *s;
		s++;
		if (*s == '-' || *s == '+') {
			if (i < last) it[i++] = *s;
			s++;
		}
		while (*s && msvg__isdigit(*s)) {
			if (i < last) it[i++] = *s;
			s++;
		}
	}
	it[i] = '\0';

	return s;
}

static const char* msvg__getNextPathItemWhenArcFlag(const char* s, char* it)
{
	it[0] = '\0';
	while (*s && (msvg__isspace(*s) || *s == ',')) s++;
	if (!*s) return s;
	if (*s == '0' || *s == '1') {
		it[0] = *s++;
		it[1] = '\0';
		return s;
	}
	return s;
}

static const char* msvg__getNextPathItem(const char* s, char* it)
{
	it[0] = '\0';
	// Skip white spaces and commas
	while (*s && (msvg__isspace(*s) || *s == ',')) s++;
	if (!*s) return s;
	if (*s == '-' || *s == '+' || *s == '.' || msvg__isdigit(*s)) {
		s = msvg__parseNumber(s, it, 64);
	} else {
		// Parse command
		it[0] = *s++;
		it[1] = '\0';
		return s;
	}

	return s;
}

static unsigned int msvg__parseColorHex(const char* str)
{
	unsigned int r=0, g=0, b=0, a=255;
	int i, n = 0;
	char buf[16];

	// Count hex digits after '#'.
	for (i = 1; str[i] && i < 10 && ((str[i] >= '0' && str[i] <= '9') ||
		 (str[i] >= 'a' && str[i] <= 'f') || (str[i] >= 'A' && str[i] <= 'F')); i++)
		n++;

	if (n == 3 || n == 4) {
		// #RGB or #RGBA: expand each digit.
		buf[0] = str[1]; buf[1] = str[1]; buf[2] = '\0';
		buf[3] = str[2]; buf[4] = str[2]; buf[5] = '\0';
		buf[6] = str[3]; buf[7] = str[3]; buf[8] = '\0';
		r = (unsigned int)strtoul(buf, NULL, 16);
		g = (unsigned int)strtoul(buf+3, NULL, 16);
		b = (unsigned int)strtoul(buf+6, NULL, 16);
		if (n == 4) {
			buf[0] = str[4]; buf[1] = str[4]; buf[2] = '\0';
			a = (unsigned int)strtoul(buf, NULL, 16);
		}
	} else if (n == 6 || n == 8) {
		buf[0] = str[1]; buf[1] = str[2]; buf[2] = '\0';
		buf[3] = str[3]; buf[4] = str[4]; buf[5] = '\0';
		buf[6] = str[5]; buf[7] = str[6]; buf[8] = '\0';
		r = (unsigned int)strtoul(buf, NULL, 16);
		g = (unsigned int)strtoul(buf+3, NULL, 16);
		b = (unsigned int)strtoul(buf+6, NULL, 16);
		if (n == 8) {
			buf[0] = str[7]; buf[1] = str[8]; buf[2] = '\0';
			a = (unsigned int)strtoul(buf, NULL, 16);
		}
	} else {
		return MSVG_RGB(128, 128, 128);
	}
	return MSVG_RGBA(r, g, b, a);
}

// ---- CSS Color 4 / SVG2 color parsing -------------------------------------
// Supports: #RGB #RGBA #RRGGBB #RRGGBBAA, rgb()/rgba() (comma and space
// syntax with slash alpha), hsl()/hsla(), hwb(), lab()/lch(), oklab()/oklch(),
// color() with predefined spaces, all CSS named colors, and 'transparent'.
// 'currentColor' and 'none' are handled by the caller (they need context).

// Clamp to [0,1].
static float msvg__colorClamp01(float x)
{
	return x < 0.0f ? 0.0f : (x > 1.0f ? 1.0f : x);
}

// Float channel (0..1) to 8-bit, with rounding.
static unsigned int msvg__colorToByte(float v)
{
	return (unsigned int)(roundf(msvg__colorClamp01(v) * 255.0f));
}

// Hue (degrees) to RGB helper for hsl().
static float msvg__hueToRgb(float p, float q, float t)
{
	if (t < 0.0f) t += 1.0f;
	if (t > 1.0f) t -= 1.0f;
	if (t < 1.0f/6.0f) return p + (q - p) * 6.0f * t;
	if (t < 1.0f/2.0f) return q;
	if (t < 2.0f/3.0f) return p + (q - p) * (2.0f/3.0f - t) * 6.0f;
	return p;
}

static void msvg__hslToRgb(float h, float s, float l, float* r, float* g, float* b)
{
	if (s <= 0.0f) {
		*r = *g = *b = l;
		return;
	}
	{
		float q = l < 0.5f ? l * (1.0f + s) : l + s - l * s;
		float p = 2.0f * l - q;
		h = h / 360.0f;
		*r = msvg__hueToRgb(p, q, h + 1.0f/3.0f);
		*g = msvg__hueToRgb(p, q, h);
		*b = msvg__hueToRgb(p, q, h - 1.0f/3.0f);
	}
}

static void msvg__hwbToRgb(float h, float w, float bl, float* r, float* g, float* b)
{
	if (w + bl >= 1.0f) {
		float gray = w / (w + bl);
		*r = *g = *b = gray;
		return;
	}
	msvg__hslToRgb(h, 1.0f, 0.5f, r, g, b);
	{
		float f = 1.0f - w - bl;
		*r = *r * f + w;
		*g = *g * f + w;
		*b = *b * f + w;
	}
}

// Lab (D50) -> XYZ (D50).
static void msvg__labToXyz(float L, float a, float b, float* x, float* y, float* z)
{
	float fy = (L + 16.0f) / 116.0f;
	float fx = fy + a / 500.0f;
	float fz = fy - b / 200.0f;
	float f3, xr, yr, zr;

	f3 = fx*fx*fx; xr = f3 > 216.0f/24389.0f ? f3 : (116.0f*fx - 16.0f)/903.3f;
	f3 = fy*fy*fy; yr = f3 > 216.0f/24389.0f ? f3 : (116.0f*fy - 16.0f)/903.3f;
	f3 = fz*fz*fz; zr = f3 > 216.0f/24389.0f ? f3 : (116.0f*fz - 16.0f)/903.3f;
	*x = xr * 0.96422f;
	*y = yr * 1.0f;
	*z = zr * 0.82521f;
}

// XYZ (D50) -> linear sRGB, with Bradford chromatic adaptation D50->D65
// (matrix from CSS Color 4, https://www.w3.org/TR/css-color-4/).
static void msvg__xyzD50ToLinearSrgb(float x, float y, float z, float* r, float* g, float* b)
{
	float x2 =  0.9555766f*x - 0.0230393f*y + 0.0631636f*z;
	float y2 = -0.0282895f*x + 1.0099416f*y + 0.0210077f*z;
	float z2 =  0.0122982f*x - 0.0204830f*y + 1.3299098f*z;
	*r =  3.2409699419f*x2 - 1.5373831776f*y2 - 0.4986107603f*z2;
	*g = -0.9692436363f*x2 + 1.8759675015f*y2 + 0.0415550574f*z2;
	*b =  0.0556300797f*x2 - 0.2039769589f*y2 + 1.0569715142f*z2;
}

// XYZ (D65) -> linear sRGB.
static void msvg__xyzD65ToLinearSrgb(float x, float y, float z, float* r, float* g, float* b)
{
	*r =  3.2409699419f*x - 1.5373831776f*y - 0.4986107603f*z;
	*g = -0.9692436363f*x + 1.8759675015f*y + 0.0415550574f*z;
	*b =  0.0556300797f*x - 0.2039769589f*y + 1.0569715142f*z;
}

// Oklab -> linear sRGB (D65).
static void msvg__oklabToLinearSrgb(float L, float a, float b, float* r, float* g, float* bl)
{
	float l_ = L + 0.3963377774f*a + 0.2158037573f*b;
	float m_ = L - 0.1055613458f*a - 0.0638541728f*b;
	float s_ = L - 0.0894841775f*a - 1.2914855480f*b;
	float l3 = l_*l_*l_, m3 = m_*m_*m_, s3 = s_*s_*s_;
	*r  =  4.0767416621f*l3 - 3.3077115913f*m3 + 0.2309699292f*s3;
	*g  = -1.2684380046f*l3 + 2.6097574011f*m3 - 0.3413193965f*s3;
	*bl = -0.0041960863f*l3 - 0.7034186147f*m3 + 1.7076147010f*s3;
}

static float msvg__linearToGamma(float c)
{
	c = msvg__colorClamp01(c);
	return c <= 0.0031308f ? 12.92f * c : 1.055f * powf(c, 1.0f/2.4f) - 0.055f;
}

// Reads a number (with optional sign/decimal/exponent). On success advances s
// past it and returns 1. Percent handling is caller's job.
static int msvg__readNumber(const char** s, float* out)
{
	const char* p = *s;
	char buf[64];
	const char* after;
	while (msvg__isspace(*p)) p++;
	if (*p != '-' && *p != '+' && *p != '.' && !msvg__isdigit(*p))
		return 0;
	after = msvg__parseNumber(p, buf, 64);
	if (after == p) return 0;
	*out = (float)msvg__atof(buf);
	*s = after;
	return 1;
}

// Reads a component: <number> or <percentage>; for rgb legacy form also
// accepts integers 0-255 when legacy=1. Returns value scaled to 0..1.
static int msvg__readComponent(const char** s, float* out, int legacy)
{
	const char* p = *s;
	float v;
	while (msvg__isspace(*p)) p++;
	if (!msvg__readNumber(&p, &v)) return 0;
	if (*p == '%') {
		p++;
		v = v / 100.0f;
	} else if (legacy) {
		v = v / 255.0f;
	}
	*s = p;
	*out = v;
	return 1;
}

// Reads an alpha value: <number> or <percentage>, clamped to 0..1.
static int msvg__readAlpha(const char** s, float* out)
{
	const char* p = *s;
	float v;
	while (msvg__isspace(*p)) p++;
	if (!msvg__readNumber(&p, &v)) return 0;
	if (*p == '%') { p++; v = v / 100.0f; }
	*s = p;
	*out = msvg__colorClamp01(v);
	return 1;
}

// Reads a hue angle: <number> [deg|grad|rad|turn]. Returns degrees.
static int msvg__readHue(const char** s, float* out)
{
	const char* p = *s;
	float v;
	while (msvg__isspace(*p)) p++;
	if (!msvg__readNumber(&p, &v)) return 0;
	if (p[0] == 'd' && p[1] == 'e' && p[2] == 'g') {
		p += 3;
	} else if (p[0] == 'g' && p[1] == 'r' && p[2] == 'a' && p[3] == 'd') {
		p += 4;
		v = v * 0.9f;
	} else if (p[0] == 'r' && p[1] == 'a' && p[2] == 'd') {
		p += 3;
		v = v * 180.0f / MSVG_PI;
	} else if (p[0] == 't' && p[1] == 'u' && p[2] == 'r' && p[3] == 'n') {
		p += 4;
		v = v * 360.0f;
	}
	*s = p;
	*out = v;
	return 1;
}

// Parses hsl()/hsla() with both legacy comma syntax (including an optional
// 4th alpha component) and modern space syntax with '/ alpha'.
static int msvg__parseHslSyntax(const char* str, float* r, float* g, float* b, float* a);

// Parses the inside of a functional color: components separated by commas or
// whitespace. Returns channels in 0..1 (except hue in degrees).
static int msvg__parseRgbSyntax(const char* str, float* r, float* g, float* b, float* a)
{
	const char* p = str;
	int legacy = 0;
	*a = 1.0f;

	// Determine legacy (comma) vs modern (space) syntax by scanning for commas.
	{
		const char* q = p;
		int commas = 0;
		while (*q && *q != ')') {
			if (*q == ',') commas++;
			q++;
		}
		legacy = (commas > 0);
	}

	if (!msvg__readComponent(&p, r, legacy)) return 0;
	if (legacy) {
		while (*p == ',' || msvg__isspace(*p)) p++;
	} else {
		while (msvg__isspace(*p)) p++;
	}
	if (!msvg__readComponent(&p, g, legacy)) return 0;
	if (legacy) {
		while (*p == ',' || msvg__isspace(*p)) p++;
	} else {
		while (msvg__isspace(*p)) p++;
	}
	if (!msvg__readComponent(&p, b, legacy)) return 0;

	// Optional 4th component (legacy rgba) or slash alpha (modern).
	while (msvg__isspace(*p) || *p == ',') p++;
	if (legacy) {
		if (*p != ')') {
			if (!msvg__readAlpha(&p, a)) return 0;
			while (msvg__isspace(*p) || *p == ',') p++;
		}
	} else {
		if (*p == '/') {
			p++;
			if (!msvg__readAlpha(&p, a)) return 0;
		}
	}

	while (msvg__isspace(*p)) p++;
	if (*p != ')') return 0;
	return 1;
}

static int msvg__parseHslSyntax(const char* str, float* r, float* g, float* b, float* a)
{
	const char* p = str;
	float h, s, l;
	int legacy = 0;
	*a = 1.0f;
	{
		const char* q = p;
		while (*q && *q != ')') { if (*q == ',') { legacy = 1; break; } q++; }
	}
	if (!msvg__readHue(&p, &h)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &s, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &l, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (legacy) {
		if (*p != ')') {
			if (!msvg__readAlpha(&p, a)) return 0;
			while (msvg__isspace(*p) || *p == ',') p++;
		}
	} else {
		if (*p == '/') {
			p++;
			if (!msvg__readAlpha(&p, a)) return 0;
			while (msvg__isspace(*p) || *p == ',') p++;
		}
	}
	if (*p != ')') return 0;
	msvg__hslToRgb(h, msvg__colorClamp01(s), msvg__colorClamp01(l), r, g, b);
	return 1;
}

static int msvg__parseHwbSyntax(const char* str, float* r, float* g, float* b, float* a)
{
	const char* p = str;
	float h, w, bl;
	*a = 1.0f;
	if (!msvg__readHue(&p, &h)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &w, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &bl, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (*p == '/') {
		p++;
		if (!msvg__readAlpha(&p, a)) return 0;
		while (msvg__isspace(*p) || *p == ',') p++;
	}
	if (*p != ')') return 0;
	msvg__hwbToRgb(h, msvg__colorClamp01(w), msvg__colorClamp01(bl), r, g, b);
	return 1;
}

// Reads a lab/oklab component: <number> or <percentage>.
// For lab, L is 0..100 (100% == 100) and a/b are -125..125 (100% == 125).
// For oklab, L is 0..1 (100% == 1) and a/b are -0.4..0.4 (100% == 0.4).
static int msvg__readLabComponent(const char** s, float* out, int oklab, int isAorB)
{
	const char* p = *s;
	float v;
	while (msvg__isspace(*p)) p++;
	if (!msvg__readNumber(&p, &v)) return 0;
	if (*p == '%') {
		p++;
		if (oklab) {
			if (isAorB) v = v / 100.0f * 0.4f;
			else v = v / 100.0f;
		} else {
			if (isAorB) v = v / 100.0f * 125.0f;
			// L stays as-is (0..100)
		}
	}
	*s = p;
	*out = v;
	return 1;
}

// Parses lab()/lch()/oklab()/oklch() into gamma-encoded sRGB channels.
static int msvg__parseLabLike(const char* str, int oklab, int cylindrical, float* r, float* g, float* b, float* a)
{
	const char* p = str;
	float c1, c2, c3;
	*a = 1.0f;
	if (!msvg__readLabComponent(&p, &c1, oklab, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readLabComponent(&p, &c2, oklab, 1)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readLabComponent(&p, &c3, oklab, 1)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (*p == '/') {
		p++;
		if (!msvg__readAlpha(&p, a)) return 0;
		while (msvg__isspace(*p) || *p == ',') p++;
	}
	if (*p != ')') return 0;

	if (cylindrical) {
		// lch/oklch: L, C, H(deg)
		float L = c1, C = c2, H = c3 * MSVG_PI / 180.0f;
		c2 = C * cosf(H);
		c3 = C * sinf(H);
		c1 = L;
	}

	if (oklab) {
		float lr, lg, lb;
		msvg__oklabToLinearSrgb(c1, c2, c3, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr);
		*g = msvg__linearToGamma(lg);
		*b = msvg__linearToGamma(lb);
	} else {
		float x, y, z, lr, lg, lb;
		msvg__labToXyz(c1, c2, c3, &x, &y, &z);
		msvg__xyzD50ToLinearSrgb(x, y, z, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr);
		*g = msvg__linearToGamma(lg);
		*b = msvg__linearToGamma(lb);
	}
	return 1;
}

// Parses color() with predefined color spaces.
static int msvg__parseColorFunc(const char* str, const char* space, int spaceLen, float* r, float* g, float* b, float* a)
{
	const char* p = str;
	float c1, c2, c3;
	*a = 1.0f;
	if (!msvg__readComponent(&p, &c1, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &c2, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (!msvg__readComponent(&p, &c3, 0)) return 0;
	while (msvg__isspace(*p) || *p == ',') p++;
	if (*p == '/') {
		p++;
		if (!msvg__readAlpha(&p, a)) return 0;
		while (msvg__isspace(*p) || *p == ',') p++;
	}
	if (*p != ')') return 0;

	if (spaceLen == 3 && strncmp(space, "srgb", 4) == 0) {
		*r = msvg__colorClamp01(c1); *g = msvg__colorClamp01(c2); *b = msvg__colorClamp01(c3);
	} else if (spaceLen == 11 && strncmp(space, "srgb-linear", 11) == 0) {
		*r = msvg__linearToGamma(c1); *g = msvg__linearToGamma(c2); *b = msvg__linearToGamma(c3);
	} else if (spaceLen == 9 && strncmp(space, "display-p3", 10) == 0) {
		// Display-P3 -> linear sRGB via XYZ D65.
		float lr, lg, lb, x, y, z;
		x = 0.4865709486f*c1 + 0.2656676932f*c2 + 0.1982172852f*c3;
		y = 0.2289745641f*c1 + 0.6917385218f*c2 + 0.0792869141f*c3;
		z = 0.0f*c1 + 0.0451133818f*c2 + 1.0439443689f*c3;
		msvg__xyzD65ToLinearSrgb(x, y, z, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else if (spaceLen == 10 && strncmp(space, "a98-rgb", 7) == 0) {
		float lr, lg, lb;
		lr = powf(msvg__colorClamp01(c1), 563.0f/256.0f);
		lg = powf(msvg__colorClamp01(c2), 563.0f/256.0f);
		lb = powf(msvg__colorClamp01(c3), 563.0f/256.0f);
		*r = msvg__linearToGamma( 2.4934969119f*lr - 0.9313836179f*lg - 0.4027107845f*lb);
		*g = msvg__linearToGamma(-0.8294889696f*lr + 1.7626640603f*lg + 0.0236246858f*lb);
		*b = msvg__linearToGamma( 0.0358458302f*lr - 0.0761723893f*lg + 0.9568845240f*lb);
	} else if (spaceLen == 13 && strncmp(space, "prophoto-rgb", 12) == 0) {
		float lr, lg, lb, x, y, z;
		lr = powf(msvg__colorClamp01(c1), 1.8f);
		lg = powf(msvg__colorClamp01(c2), 1.8f);
		lb = powf(msvg__colorClamp01(c3), 1.8f);
		x =  0.7977604897f*lr + 0.1351858372f*lg + 0.0313493496f*lb;
		y =  0.2880711282f*lr + 0.7118432178f*lg + 0.0000856530f*lb;
		z =  0.0f*lr + 0.0f*lg + 0.8251046025f*lb;
		msvg__xyzD65ToLinearSrgb(x, y, z, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else if (spaceLen == 6 && strncmp(space, "rec2020", 7) == 0) {
		float lr, lg, lb, x, y, z;
		lr = powf(msvg__colorClamp01(c1), 1.0f/0.45f);
		lg = powf(msvg__colorClamp01(c2), 1.0f/0.45f);
		lb = powf(msvg__colorClamp01(c3), 1.0f/0.45f);
		x =  0.6369580483f*lr + 0.1446169036f*lg + 0.1688809752f*lb;
		y =  0.2627002120f*lr + 0.6779980715f*lg + 0.0593017165f*lb;
		z =  0.0000000000f*lr + 0.0280726930f*lg + 1.0609850577f*lb;
		msvg__xyzD65ToLinearSrgb(x, y, z, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else if (spaceLen == 7 && strncmp(space, "xyz-d50", 7) == 0) {
		float lr, lg, lb;
		msvg__xyzD50ToLinearSrgb(c1, c2, c3, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else if (spaceLen == 7 && strncmp(space, "xyz-d65", 7) == 0) {
		float lr, lg, lb;
		msvg__xyzD65ToLinearSrgb(c1, c2, c3, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else if (spaceLen == 7 && strncmp(space, "xyz", 3) == 0) {
		float lr, lg, lb;
		msvg__xyzD65ToLinearSrgb(c1, c2, c3, &lr, &lg, &lb);
		*r = msvg__linearToGamma(lr); *g = msvg__linearToGamma(lg); *b = msvg__linearToGamma(lb);
	} else {
		return 0; // unknown color space
	}
	return 1;
}

// Forward declaration (named-color table is defined below).
static unsigned int msvg__parseColorName2(const char* str, int* found);

// Full color parse: returns packed RGBA (alpha in top byte) or 0 on failure.
// 'ok' is set to 1 on success (so a legitimately-zero color such as
// 'transparent' is distinguishable from a parse failure).
static unsigned int msvg__parseColorFull(const char* str, int* ok)
{
	float r, g, b, a;
	size_t len = 0;
	const char* s = str;
	*ok = 0;
	while (*s == ' ' || *s == '	') s++;
	len = strlen(s);

	if (len >= 1 && s[0] == '#') {
		unsigned int c = msvg__parseColorHex(s);
		int n = 0, i;
		for (i = 1; s[i] && i < 10 && ((s[i]>='0'&&s[i]<='9')||(s[i]>='a'&&s[i]<='f')||(s[i]>='A'&&s[i]<='F')); i++) n++;
		if (n == 3 || n == 4 || n == 6 || n == 8) {
			*ok = 1;
			return c;
		}
		return 0;
	}

	if (len >= 4 && s[0] == 'r' && s[1] == 'g' && s[2] == 'b' && s[3] == '(') {
		if (msvg__parseRgbSyntax(s + 4, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 5 && s[0] == 'r' && s[1] == 'g' && s[2] == 'b' && s[3] == 'a' && s[4] == '(') {
		if (msvg__parseRgbSyntax(s + 5, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 4 && s[0] == 'h' && s[1] == 's' && s[2] == 'l' && s[3] == '(') {
		if (msvg__parseHslSyntax(s + 4, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 5 && s[0] == 'h' && s[1] == 's' && s[2] == 'l' && s[3] == 'a' && s[4] == '(') {
		if (msvg__parseHslSyntax(s + 5, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 4 && s[0] == 'h' && s[1] == 'w' && s[2] == 'b' && s[3] == '(') {
		if (msvg__parseHwbSyntax(s + 4, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 5 && s[0] == 'l' && s[1] == 'a' && s[2] == 'b' && s[3] == '(') {
		if (msvg__parseLabLike(s + 4, 0, 0, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 5 && s[0] == 'l' && s[1] == 'c' && s[2] == 'h' && s[3] == '(') {
		if (msvg__parseLabLike(s + 4, 0, 1, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 7 && s[0] == 'o' && s[1] == 'k' && s[2] == 'l' && s[3] == 'a' && s[4] == 'b' && s[5] == '(') {
		if (msvg__parseLabLike(s + 6, 1, 0, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 7 && s[0] == 'o' && s[1] == 'k' && s[2] == 'l' && s[3] == 'c' && s[4] == 'h' && s[5] == '(') {
		if (msvg__parseLabLike(s + 6, 1, 1, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len >= 7 && s[0] == 'c' && s[1] == 'o' && s[2] == 'l' && s[3] == 'o' && s[4] == 'r' && s[5] == '(') {
		const char* p = s + 6;
		const char* spaceStart = p;
		int spaceLen = 0;
		while (*p && !msvg__isspace(*p) && *p != ',' && *p != ')') { p++; spaceLen++; }
		if (spaceLen == 0) return 0;
		while (msvg__isspace(*p) || *p == ',') p++;
		if (msvg__parseColorFunc(p, spaceStart, spaceLen, &r, &g, &b, &a)) {
			*ok = 1;
			return MSVG_RGBA(msvg__colorToByte(r), msvg__colorToByte(g), msvg__colorToByte(b), msvg__colorToByte(a));
		}
		return 0;
	}
	if (len == 11 && strcmp(s, "transparent") == 0) {
		*ok = 1;
		return MSVG_RGBA(0, 0, 0, 0);
	}

	{
		int found = 0;
		unsigned int c = msvg__parseColorName2(s, &found);
		if (found) {
			*ok = 1;
			return MSVG_RGBA(c & 0xff, (c >> 8) & 0xff, (c >> 16) & 0xff, 255);
		}
	}
	return 0;
}

