/* ---- vertex markers: rasterization (SVG 2 §Painting 'Rendering markers') */

#define MSVG__PI_F 3.14159265358979323846f

// Computes the viewBox->viewport transform B (content -> viewport space) for
// a marker and the aligned reference-point position refPos (viewport space).
// When the marker has no viewBox, B is identity and refPos is (refX, refY)
// (the spec's assumed default viewBox coincides with the viewport).
static void msvg__markerViewbox(MSVGmarkerData* mk, float* b, float* refPos)
{
	float sx, sy, ax = 0.0f, ay = 0.0f;
	if (!mk->hasViewBox || mk->viewBox[2] <= 0.0f || mk->viewBox[3] <= 0.0f) {
		msvg__xformIdentity(b);
		refPos[0] = mk->refX;
		refPos[1] = mk->refY;
		return;
	}
	{
		float vw = mk->viewBox[2], vh = mk->viewBox[3];
		float mw = mk->markerWidth, mh = mk->markerHeight;
		sx = mw / vw;
		sy = mh / vh;
		if (mk->alignType == MSVG_ALIGN_MEET || mk->alignType == MSVG_ALIGN_SLICE) {
			float s = (mk->alignType == MSVG_ALIGN_MEET) ? msvg__minf(sx, sy) : msvg__maxf(sx, sy);
			sx = sy = s;
		}
		ax = msvg__viewAlign(vw * sx, mw, mk->alignX);
		ay = msvg__viewAlign(vh * sy, mh, mk->alignY);
	}
	// B = T(ax,ay) * S(sx,sy) * T(-minx,-miny): T(-minx) applies to the
	// point first, then the scale, then the alignment translation.
	// msvg__xformMultiply(b,t) appends t AFTER b in application order
	// (b' = b∘t), so append the point-first transforms in order.
	{
		float t[6];
		msvg__xformIdentity(b);
		msvg__xformSetTranslation(t, -mk->viewBox[0], -mk->viewBox[1]);
		msvg__xformMultiply(b, t);
		msvg__xformSetScale(t, sx, sy);
		msvg__xformMultiply(b, t);
		msvg__xformSetTranslation(t, ax, ay);
		msvg__xformMultiply(b, t);
	}
	msvg__xformPoint(&refPos[0], &refPos[1], mk->refX, mk->refY, b);
	if (getenv("MSVG_DBG_MK") != NULL)
		fprintf(stderr, "[MKB] s=(%.4f,%.4f) ax=%.4f ay=%.4f B=[%.4f %.4f %.4f; %.4f %.4f %.4f] refPos=(%.4f,%.4f)\n",
			sx, sy, ax, ay, b[0], b[2], b[4], b[1], b[3], b[5], refPos[0], refPos[1]);
}

// Direction of segment i (unit vector); zero-length segments return (0,0)
// (no directionality).
static void msvg__segDir(const float* v, int i, float* dx, float* dy)
{
	float ex = v[(i+1)*2] - v[i*2];
	float ey = v[(i+1)*2+1] - v[i*2+1];
	float len = sqrtf(ex*ex + ey*ey);
	if (len > 1e-6f) { *dx = ex / len; *dy = ey / len; }
	else { *dx = 0.0f; *dy = 0.0f; }
}

// First non-zero segment direction scanning forward from 'from' — the
// directionality of a zero-length segment's end point (SVG 1.1
// implementation notes: go forward until a segment with directionality).
static void msvg__dirForward(const float* v, int nseg, int from, float* dx, float* dy)
{
	int i;
	float dd0, dd1;
	for (i = from; i < nseg; i++) {
		msvg__segDir(v, i, &dd0, &dd1);
		if (dd0 != 0.0f || dd1 != 0.0f) { *dx = dd0; *dy = dd1; return; }
	}
	*dx = 0.0f; *dy = 0.0f;
}

// First non-zero segment direction scanning backward from 'from' — the
// directionality of a zero-length segment's start point.
static void msvg__dirBackward(const float* v, int nseg, int from, float* dx, float* dy)
{
	int i;
	float dd0, dd1;
	(void)nseg;
	for (i = from; i >= 0; i--) {
		msvg__segDir(v, i, &dd0, &dd1);
		if (dd0 != 0.0f || dd1 != 0.0f) { *dx = dd0; *dy = dd1; return; }
	}
	*dx = 0.0f; *dy = 0.0f;
}

// Marker orientation (degrees) from the incoming/outgoing directions: the
// bisector ("half way between the direction at the end of the preceding
// segment and the direction at the start of the following segment") as the
// normalized sum of the two unit vectors; if the sum is zero the marker is
// oriented in the incoming direction; without directionality it aligns with
// the positive x-axis (0 degrees).
static float msvg__markerAngle(float inx, float iny, float outx, float outy)
{
	float sx = inx + outx, sy = iny + outy;
	float len = sqrtf(sx*sx + sy*sy);
	if (len > 1e-6f) return atan2f(sy, sx) * (180.0f / MSVG__PI_F);
	if (inx != 0.0f || iny != 0.0f) return atan2f(iny, inx) * (180.0f / MSVG__PI_F);
	if (outx != 0.0f || outy != 0.0f) return atan2f(outy, outx) * (180.0f / MSVG__PI_F);
	return 0.0f;
}

// Renders the marker's content into a viewport-sized tile. 'resScale' is the
// canvas resolution in markerUnits (scale * strokeWidth-or-1). 'uniform' is
// 1 when the viewBox transform is a uniform scale + translation (no viewBox,
// meet/slice, or align=none with matching ratios): content is rendered
// directly in marker user space, so gradients/clips/masks stay native.
// Non-uniform viewBoxes (preserveAspectRatio="none" with mismatched ratios)
// clone content into viewport space with B applied, transforming gradient
// xforms and clip/mask geometry accordingly.
static void msvg__initMarkerTile(MSVGrasterizer* r, MSVGmarkerData* mk, float resScale,
								 MSVGshape* contextShape, float vx, float vy, float angle, float sfac)
{
	float b[6], refPos[2];
	int uniform;
	int tw, th;
	float mw = mk->markerWidth, mh = mk->markerHeight;

	msvg__markerViewbox(mk, b, refPos);
	uniform = 1;
	if (mk->hasViewBox && mk->viewBox[2] > 0.0f && mk->viewBox[3] > 0.0f
		&& mk->alignType == MSVG_ALIGN_NONE) {
		float sx = mw / mk->viewBox[2];
		float sy = mh / mk->viewBox[3];
		if (fabsf(sx - sy) > 1e-4f) uniform = 0;
	}

	// Compute the overflow tile state BEFORE the cache check: composite
	// sampling reads it even on a cache hit.
	r->markerOvValid = 0;
	if (mk->overflowVisible && mk->shapes != NULL && mw > 0.0f && mh > 0.0f) {
		float ub[4], ovb[4];
		MSVGshape* cs;
		int have = 0;
		for (cs = mk->shapes; cs != NULL; cs = cs->next) {
			float cb[4];
			if (cs->flags & MSVG_FLAGS_HIDDEN)
				continue;
			msvg__getLocalBounds(cb, cs, mk->bakeXform);
			if (!have) { memcpy(ub, cb, sizeof(cb)); have = 1; }
			else {
				ub[0] = msvg__minf(ub[0], cb[0]);
				ub[1] = msvg__minf(ub[1], cb[1]);
				ub[2] = msvg__maxf(ub[2], cb[2]);
				ub[3] = msvg__maxf(ub[3], cb[3]);
			}
		}
		if (have) {
			// user-space bounds -> viewport units via B (B is axis-aligned
			// scale+translate, so corners suffice)
			float cx[4], cy[4];
			int ci;
			cx[0] = ub[0]; cy[0] = ub[1];
			cx[1] = ub[2]; cy[1] = ub[1];
			cx[2] = ub[0]; cy[2] = ub[3];
			cx[3] = ub[2]; cy[3] = ub[3];
			for (ci = 0; ci < 4; ci++) {
				float px, py;
				msvg__xformPoint(&px, &py, cx[ci], cy[ci], b);
				if (ci == 0) { ovb[0] = ovb[2] = px; ovb[1] = ovb[3] = py; }
				else {
					ovb[0] = msvg__minf(ovb[0], px);
					ovb[1] = msvg__minf(ovb[1], py);
					ovb[2] = msvg__maxf(ovb[2], px);
					ovb[3] = msvg__maxf(ovb[3], py);
				}
			}
			// UNION with the viewport rect [0,mw]x[0,mh]: the tile always
			// covers the viewport, plus whatever content sticks out.
			ovb[0] = msvg__minf(ovb[0], 0.0f);
			ovb[1] = msvg__minf(ovb[1], 0.0f);
			ovb[2] = msvg__maxf(ovb[2], mw);
			ovb[3] = msvg__maxf(ovb[3], mh);
			// clamp the overshoot so oversized content can't blow up the
			// tile; the viewport is always fully included
			if (ovb[0] < -mw) ovb[0] = -mw;
			if (ovb[1] < -mh) ovb[1] = -mh;
			if (ovb[2] > 2.0f * mw) ovb[2] = 2.0f * mw;
			if (ovb[3] > 2.0f * mh) ovb[3] = 2.0f * mh;
			memcpy(r->markerOvB, ovb, sizeof(float) * 4);
			r->markerOvValid = 1;
		}
	}

	// Context-dependent markers (content uses context-fill/context-stroke)
	// vary per referencing element: never reuse the cached tile.
	if (r->markerKey == mk && r->markerKeyRes == resScale && !mk->usesContext)
		return;	// tile already cached for this marker + resolution

	if (!(mw > 0.0f) || !(mh > 0.0f)) {
		// Zero viewport size renders nothing; negative is an error.
		if (r->markerTile != NULL) { free(r->markerTile); r->markerTile = NULL; }
		r->markerTW = r->markerTH = 0;
		r->markerKey = mk;
		r->markerKeyRes = resScale;
		r->markerRefX = refPos[0];
		r->markerRefY = refPos[1];
		r->markerOvValid = 0;
		return;
	}

	// Tile size: the full overflow tile rect (union of viewport + content
	// overshoot, computed above). Without overflow it is the viewport.
	{
		float x0 = 0.0f, y0 = 0.0f, x1 = mw, y1 = mh;
		if (r->markerOvValid) { x0 = r->markerOvB[0]; y0 = r->markerOvB[1]; x1 = r->markerOvB[2]; y1 = r->markerOvB[3]; }
		tw = (int)ceilf((x1 - x0) * resScale);
		th = (int)ceilf((y1 - y0) * resScale);
		if (tw < 1) tw = 1;
		if (th < 1) th = 1;
		if (tw > MSVG__MAX_PATTERN_TILE) tw = MSVG__MAX_PATTERN_TILE;
		if (th > MSVG__MAX_PATTERN_TILE) th = MSVG__MAX_PATTERN_TILE;
	}

	{
		unsigned char* tile = (unsigned char*)malloc(tw * th * 4);
		if (tile == NULL) {
			r->markerTW = r->markerTH = 0;
			r->markerKey = mk;
			r->markerKeyRes = resScale;
			return;
		}
		memset(tile, 0, tw * th * 4);
		{
			MSVGrasterizer* tr = msvgCreateRasterizer();
			if (tr != NULL) {
				MSVGimage tmp;
				MSVGshape* head = NULL;
				MSVGshape* tail = NULL;
				MSVGshape* s;
				tr->markerRendering = 1;	// no nested markers in marker tiles
				tr->markerDepth = r->markerDepth + 1;

				memset(&tmp, 0, sizeof(tmp));
				if (r->curImage != NULL) {
					tmp.imageLoader = r->curImage->imageLoader;
					tmp.imageLoaderData = r->curImage->imageLoaderData;
				}

				/* Tile px -> context user space, for context paints (SVG 2
				   §13.2: paint-server context paints use the context
				   element's coordinate space so the gradient stays
				   continuous with the referencing shape). tile px ->
				   viewport units (/resScale) -> user space via
				   T(-refPos)·S(s)·R(angle)·T(vertex). */
				{
					float m[6], t2[6];
					msvg__xformIdentity(m);
					msvg__xformSetScale(t2, 1.0f / resScale, 1.0f / resScale);
					msvg__xformMultiply(m, t2);
					msvg__xformSetTranslation(t2, -refPos[0], -refPos[1]);
					msvg__xformMultiply(m, t2);
					msvg__xformSetScale(t2, sfac, sfac);
					msvg__xformMultiply(m, t2);
					msvg__xformSetRotation(t2, angle * MSVG__PI_F / 180.0f);
					msvg__xformMultiply(m, t2);
					msvg__xformSetTranslation(t2, vx, vy);
					msvg__xformMultiply(m, t2);
					memcpy(tr->markerTileToUser, m, sizeof(float) * 6);
					tr->markerTileToUserSet = 1;
				}

				if (uniform) {
					// Content stays in marker user space; position it so the
					// tile covers viewport-rect(0,0)..(mw,mh) mapped through B
					// (plus any overflow overshoot from markerOvB). The tile
					// origin is viewport point (ovx0, ovy0); tile px =
					// resScale * (B(p) - (ovx0, ovy0)). Clones are shallow
					// (paths/paints shared with the stored content).
					float s_uni, ax, ay, minx, miny;
					float ovx0 = 0.0f, ovy0 = 0.0f;
					float txr, tyr, scale_r;
					if (r->markerOvValid) { ovx0 = r->markerOvB[0]; ovy0 = r->markerOvB[1]; }
					(void)txr; (void)tyr;
					minx = miny = 0.0f; ax = ay = 0.0f; s_uni = 1.0f;
					if (mk->hasViewBox && mk->viewBox[2] > 0.0f && mk->viewBox[3] > 0.0f) {
						s_uni = mw / mk->viewBox[2];
						if (mk->alignType != MSVG_ALIGN_NONE) {
							float sy2 = mh / mk->viewBox[3];
							s_uni = (mk->alignType == MSVG_ALIGN_MEET)
								? msvg__minf(s_uni, sy2) : msvg__maxf(s_uni, sy2);
						}
						ax = msvg__viewAlign(mk->viewBox[2] * s_uni, mw, mk->alignX);
						ay = msvg__viewAlign(mk->viewBox[3] * s_uni, mh, mk->alignY);
						minx = mk->viewBox[0];
						miny = mk->viewBox[1];
					}
					scale_r = resScale * s_uni;
					txr = resScale * (ax - s_uni * minx - ovx0);
					tyr = resScale * (ay - s_uni * miny - ovy0);
					if (getenv("MSVG_DBG_MK") != NULL)
						fprintf(stderr, "[MKU] uniform=1 s_uni=%.4f ax=%.4f ay=%.4f scale_r=%.4f txr=%.4f tyr=%.4f\n", s_uni, ax, ay, scale_r, txr, tyr);
					for (s = mk->shapes; s != NULL; s = s->next) {
						/* display:none / visibility:hidden marker content
						   contributes nothing to the tile (SVG 1.1 §11.1). */
						if (s->flags & MSVG_FLAGS_HIDDEN)
							continue;
						MSVGshape* copy = (MSVGshape*)malloc(sizeof(MSVGshape));
						if (copy == NULL) break;
						memcpy(copy, s, sizeof(MSVGshape));
						copy->next = NULL;
						copy->flags = (char)((copy->flags & ~MSVG_FLAGS_HIDDEN) | MSVG_FLAGS_VISIBLE);
						copy->context = contextShape;	// for context-fill/stroke
						if (tail) tail->next = copy;
						else head = copy;
						tail = copy;
					}
					tmp.shapes = head;
					msvgRasterize(tr, &tmp, txr, tyr, scale_r, tile, tw, th, tw*4);
					while (head != NULL) {
						MSVGshape* n = head->next;
						free(head);
						head = n;
					}
				} else {
					// Non-uniform viewBox: clone content into viewport space
					// with B; gradients need xform g*B^-1 (viewport ->
					// gradient space) and clip/mask geometry clones with B.
					float invB[6], t[6];
					float ovx0n = 0.0f, ovyn0 = 0.0f;
					if (r->markerOvValid) { ovx0n = r->markerOvB[0]; ovyn0 = r->markerOvB[1]; }
					msvg__xformInverse(invB, b);
					for (s = mk->shapes; s != NULL; s = s->next) {
						if (s->flags & MSVG_FLAGS_HIDDEN)
							continue;
						MSVGshape* copy = msvg__cloneShape(s, b);
						if (copy == NULL) break;
						copy->next = NULL;
						copy->flags = (char)((copy->flags & ~MSVG_FLAGS_HIDDEN) | MSVG_FLAGS_VISIBLE);
						copy->context = contextShape;	// for context-fill/stroke
						if (copy->fill.type == MSVG_PAINT_LINEAR_GRADIENT || copy->fill.type == MSVG_PAINT_RADIAL_GRADIENT) {
							MSVGgradient* g = copy->fill.gradient;
							MSVGgradient* g2 = (MSVGgradient*)malloc(sizeof(MSVGgradient));
							if (g2 != NULL) {
								/* the stop array is borrowed (shared) — copy the struct only */
								memcpy(g2, g, sizeof(MSVGgradient));
								memcpy(t, g2->xform, sizeof(float)*6);
								msvg__xformMultiply(t, invB);
								memcpy(g2->xform, t, sizeof(float)*6);
								copy->fill.gradient = g2;
							}
						}
						if (copy->stroke.type == MSVG_PAINT_LINEAR_GRADIENT || copy->stroke.type == MSVG_PAINT_RADIAL_GRADIENT) {
							MSVGgradient* g = copy->stroke.gradient;
							MSVGgradient* g2 = (MSVGgradient*)malloc(sizeof(MSVGgradient));
							if (g2 != NULL) {
								/* the stop array is borrowed (shared) — copy the struct only */
								memcpy(g2, g, sizeof(MSVGgradient));
								memcpy(t, g2->xform, sizeof(float)*6);
								msvg__xformMultiply(t, invB);
								memcpy(g2->xform, t, sizeof(float)*6);
								copy->stroke.gradient = g2;
							}
						}
						if (copy->clipShapes != NULL) {
							MSVGshape* ch = NULL, *ct = NULL, *cs;
							for (cs = copy->clipShapes; cs != NULL; cs = cs->next) {
								MSVGshape* cc = msvg__cloneShape(cs, b);
								if (cc == NULL) break;
								cc->next = NULL;
								if (ct) ct->next = cc;
								else ch = cc;
								ct = cc;
							}
							copy->clipShapes = ch;
						}
						if (copy->maskShapes != NULL) {
							MSVGshape* mh2 = NULL, *mt = NULL, *ms;
							for (ms = copy->maskShapes; ms != NULL; ms = ms->next) {
								MSVGshape* mc = msvg__cloneShape(ms, b);
								if (mc == NULL) break;
								mc->next = NULL;
								if (mt) mt->next = mc;
								else mh2 = mc;
								mt = mc;
							}
							copy->maskShapes = mh2;
							msvg__xformPoint(&copy->maskRect[0], &copy->maskRect[1],
											 copy->maskRect[0], copy->maskRect[1], b);
							msvg__xformPoint(&copy->maskRect[2], &copy->maskRect[3],
											 copy->maskRect[2], copy->maskRect[3], b);
						}
						if (tail) tail->next = copy;
						else head = copy;
						tail = copy;
					}
					tmp.shapes = head;
					msvgRasterize(tr, &tmp, -ovx0n * resScale, -ovyn0 * resScale, resScale, tile, tw, th, tw*4);
					while (head != NULL) {
						MSVGshape* n = head->next;
						msvg__deletePaths(head->paths);
						msvg__deletePaint(&head->fill);
						msvg__deletePaint(&head->stroke);
						if (head->clipShapes != NULL)
							msvg__deleteShapeList(head->clipShapes);
						if (head->maskShapes != NULL)
							msvg__deleteShapeList(head->maskShapes);
						free(head);
						head = n;
					}
				}
				msvgDeleteRasterizer(tr);
			}
		}
		if (r->markerTile != NULL) free(r->markerTile);
		r->markerTile = tile;
		r->markerTW = tw;
		r->markerTH = th;
		r->markerKey = mk;
		r->markerKeyRes = resScale;
		r->markerRefX = refPos[0];
		r->markerRefY = refPos[1];
		if (getenv("MSVG_DBG_MK") != NULL) {
			static int mkSeq = 0;
			char pbuf[64];
			FILE* df;
			snprintf(pbuf, sizeof pbuf, "/tmp/mktile_%d.raw", ++mkSeq);
			df = fopen(pbuf, "wb");
			if (df) { fwrite(tile, 1, (size_t)tw*th*4, df); fclose(df); }
			df = fopen("/tmp/marker_tile.raw", "wb");
			if (df) { fwrite(tile, 1, (size_t)tw*th*4, df); fclose(df);
				fprintf(stderr, "[MKTILE] seq=%d tw=%d th=%d resScale=%.3f refPos=(%.3f,%.3f)\n", mkSeq, tw, th, resScale, refPos[0], refPos[1]); }
		}
	}
}

// Composites one placed marker instance over the bitmap: the viewport rect is
// transformed to canvas space (T(v)*R*S(markerUnits)), and each covered pixel
// samples the pre-rendered viewport tile through the inverse placement
// (canvas -> viewport -> tile), bilinearly filtered, clipped to the viewport
// and gated by the referencing shape's clip/mask. 'v' is the vertex in user
// space; 'angle' the orientation in degrees; 's' the markerUnits factor
// (stroke-width or 1); 'resScale' = scale*s.
static void msvg__compositeMarkerInstance(MSVGrasterizer* r, MSVGmarkerData* mk,
										  float vx, float vy, float angle,
										  float resScale, float s,
										  float tx, float ty, float scale)
{
	int w = r->width;
	int h = r->height;
	int tw = r->markerTW, th = r->markerTH;
	unsigned char* tile = r->markerTile;
	float c, st;
	float mw = mk->markerWidth, mh = mk->markerHeight;
	int x0, y0, x1, y1, x, y;
	int i;
	if (tile == NULL || tw < 1 || th < 1) return;
	if (!(mw > 0.0f) || !(mh > 0.0f)) return;
	if (getenv("MSVG_DBG_MK") != NULL)
		fprintf(stderr, "[MKC] tw=%d th=%d mw=%.2f mh=%.2f resScale=%.3f s=%.3f angle=%.1f vx=%.2f vy=%.2f scale=%.3f ov=%d ovB=[%.2f %.2f %.2f %.2f]\n",
			tw, th, mw, mh, resScale, s, angle, vx, vy, scale,
			r->markerOvValid, r->markerOvB[0], r->markerOvB[1], r->markerOvB[2], r->markerOvB[3]);
	int painted = 0;
	int dbgMaxA = 0;
	float dbgUMin = 1e9f, dbgUMax = -1e9f, dbgVMin = 1e9f, dbgVMax = -1e9f;

	c = cosf(angle * MSVG__PI_F / 180.0f);
	st = sinf(angle * MSVG__PI_F / 180.0f);

	// Canvas-space bounds of the rotated/scaled viewport rect: the vertex is
	// the aligned reference point, so each viewport corner v is placed at
	// v + R*((corner - refPos) * s).
	{
		const float cx[4] = {0.0f, mw, 0.0f, mw};
		const float cy[4] = {0.0f, 0.0f, mh, mh};
		float rfx = r->markerRefX, rfy = r->markerRefY;
		// overflow="visible": the tile extends past the viewport by the
		// overshoot, so expand the corner set by the overshoot extents
		// (canvas-space conservative bounds).
		float ovdx0 = 0.0f, ovdy0 = 0.0f, ovdx1 = 0.0f, ovdy1 = 0.0f;
		if (r->markerOvValid) {
			ovdx0 = r->markerOvB[0];	// negative side overshoot in viewport x
			ovdy0 = r->markerOvB[1];
			ovdx1 = r->markerOvB[2] - mw;	// positive side overshoot
			ovdy1 = r->markerOvB[3] - mh;
		}
		float minx = 1e30f, miny = 1e30f, maxx = -1e30f, maxy = -1e30f;
		for (i = 0; i < 4; i++) {
			float ex0 = (i & 1) ? ovdx1 : ovdx0;	// x overshoot for this column
			float ey0 = (i & 2) ? ovdy1 : ovdy0;	// y overshoot for this row
			float rx = (c * (cx[i]-rfx+ex0) - st * (cy[i]-rfy+ey0)) * s;
			float ry = (st * (cx[i]-rfx+ex0) + c * (cy[i]-rfy+ey0)) * s;
			float px = tx + (vx + rx) * scale;
			float py = ty + (vy + ry) * scale;
			minx = msvg__minf(minx, px);
			miny = msvg__minf(miny, py);
			maxx = msvg__maxf(maxx, px);
			maxy = msvg__maxf(maxy, py);
		}
		x0 = (int)floorf(minx) - 1;
		y0 = (int)floorf(miny) - 1;
		x1 = (int)ceilf(maxx) + 1;
		y1 = (int)ceilf(maxy) + 1;
		if (x0 < 0) x0 = 0;
		if (y0 < 0) y0 = 0;
		if (x1 >= w) x1 = w - 1;
		if (y1 >= h) y1 = h - 1;
		if (x0 > x1 || y0 > y1) return;
	}

	for (y = y0; y <= y1; y++) {
		unsigned char* dstrow = &r->bitmap[y * r->stride];
		/* Gate by the CURRENT shape's clip/mask only (curClipGate/curMaskGate
		   are NULL when this shape has none). clipmask/maskalpha are the
		   persistent buffers and hold stale coverage from previously painted
		   shapes — gating through them clipped marker tiles to unrelated
		   geometry (painting-marker-02-f tests 3/4 painted nothing). */
		const unsigned char* cliprow = r->curClipGate ? r->curClipGate + y * w : NULL;
		const unsigned char* maskrow = r->curMaskGate ? r->curMaskGate + y * w : NULL;
		for (x = x0; x <= x1; x++) {
			float ux, uy, u, v, fu, fv, sx0, sy0;
			int ix0, iy0, ix1, iy1;
			int cr, cg, cb, ca, a, ia;
			// canvas px -> user -> viewport (inverse placement: undo the
			// vertex translation, rotation and markerUnits scale, then the
			// reference-point translation) -> tile px. Sample at pixel
			// centers (+0.5): without it, rotating a marker 180deg shifts
			// it one pixel (the tile's half-open edge flips sides). For
			// sub-pixel content this softly spreads coverage across the
			// two boundary rows but conserves total alpha exactly.
			ux = ((float)x + 0.5f - tx) / scale - vx;
			uy = ((float)y + 0.5f - ty) / scale - vy;				u = (c * ux + st * uy) / s + r->markerRefX;
				v = (-st * ux + c * uy) / s + r->markerRefY;
				// overflow="visible" tile: the tile origin sits at viewport
				// point (ovB.x0, ovB.y0), not the viewport origin; shift the
				// sample coordinates to match (SVG 2 §11.3.3).
				if (r->markerOvValid) {
					u -= r->markerOvB[0];
					v -= r->markerOvB[1];
				}
				fu = u * resScale;
			fv = v * resScale;
			if (u < dbgUMin) dbgUMin = u;
			if (u > dbgUMax) dbgUMax = u;
			if (v < dbgVMin) dbgVMin = v;
			if (v > dbgVMax) dbgVMax = v;
			if (getenv("MSVG_DBG_MK") != NULL && x == 30 && y == 190)
				fprintf(stderr, "[MKX] x=30 y=190 ux=%.3f uy=%.3f u=%.3f v=%.3f fu=%.3f fv=%.3f tx=%.2f ty=%.2f vx=%.2f vy=%.2f s=%.2f scale=%.2f\n",
					ux, uy, u, v, fu, fv, tx, ty, vx, vy, s, scale);
			if (getenv("MSVG_DBG_MK") != NULL && x == 30 && y == 190)
				fprintf(stderr, "[MKG] cliprow=%d maskrow=%d clipmask=%d maskalpha=%d sampled ca pre-gate next line\n",
					cliprow ? (int)cliprow[x] : -1, maskrow ? (int)maskrow[x] : -1,
					r->clipmask != NULL, r->maskalpha != NULL);
			if (fu < 0.0f || fv < 0.0f || fu >= (float)tw || fv >= (float)th)
				continue;	// outside the viewport: clipped (overflow hidden)
			ix0 = (int)fu;
			iy0 = (int)fv;
			ix1 = ix0 + 1;
			iy1 = iy0 + 1;
			if (ix1 >= tw) ix1 = tw - 1;
			if (iy1 >= th) iy1 = th - 1;
			sx0 = fu - ix0;
			sy0 = fv - iy0;
			{
				const unsigned char* t00 = &tile[(iy0 * tw + ix0) * 4];
				const unsigned char* t10 = &tile[(iy0 * tw + ix1) * 4];
				const unsigned char* t01 = &tile[(iy1 * tw + ix0) * 4];
				const unsigned char* t11 = &tile[(iy1 * tw + ix1) * 4];
				cr = (int)((t00[0]*(1.0f-sx0) + t10[0]*sx0)*(1.0f-sy0)
						+ (t01[0]*(1.0f-sx0) + t11[0]*sx0)*sy0);
				cg = (int)((t00[1]*(1.0f-sx0) + t10[1]*sx0)*(1.0f-sy0)
						+ (t01[1]*(1.0f-sx0) + t11[1]*sx0)*sy0);
				cb = (int)((t00[2]*(1.0f-sx0) + t10[2]*sx0)*(1.0f-sy0)
						+ (t01[2]*(1.0f-sx0) + t11[2]*sx0)*sy0);
				ca = (int)((t00[3]*(1.0f-sx0) + t10[3]*sx0)*(1.0f-sy0)
						+ (t01[3]*(1.0f-sx0) + t11[3]*sx0)*sy0);
			}
			// Gate by the referencing shape's clip-path and mask.
			if (cliprow != NULL) ca = (ca * cliprow[x]) / 255;
			if (maskrow != NULL) ca = (ca * maskrow[x]) / 255;
			a = ca;
			ia = 255 - a;
			{
				unsigned char* d = &dstrow[x*4];
				/* Premultiply with true round-to-nearest (see scanlineSolid). */
				int r0 = msvg__div255rnd(cr * a);
				int g0 = msvg__div255rnd(cg * a);
				int b0 = msvg__div255rnd(cb * a);
				r0 += msvg__div255(ia * (int)d[0]);
				g0 += msvg__div255(ia * (int)d[1]);
				b0 += msvg__div255(ia * (int)d[2]);
				a += msvg__div255(ia * (int)d[3]);
				d[0] = (unsigned char)r0;
				d[1] = (unsigned char)g0;
				d[2] = (unsigned char)b0;
				d[3] = (unsigned char)a;
				painted++;
				if (ca > dbgMaxA) dbgMaxA = ca;
			}
		}
	}
	if (getenv("MSVG_DBG_MK") != NULL)
		fprintf(stderr, "[MKP] painted=%d maxA=%d u=[%.2f..%.2f] v=[%.2f..%.2f] x=[%d..%d] y=[%d..%d]\n", painted, dbgMaxA, dbgUMin, dbgUMax, dbgVMin, dbgVMax, x0, x1, y0, y1);
	if (getenv("MSVG_DBG_MK") != NULL) {
		int qi;
		fprintf(stderr, "[MKS] tile probe a:");
		for (qi = 0; qi < 16; qi += 3) fprintf(stderr, " %d", tile[(8 * tw + qi) * 4 + 3]);
		fprintf(stderr, " | row8:\n");
	}
}

// Draws one marker instance: resolves the markerUnits factor, computes the
// resolution, initializes (or reuses) the viewport tile and composites it.
// 'isStart' selects the auto-start-reverse 180° flip.
static void msvg__markerInstance(MSVGrasterizer* r, MSVGshape* shape, MSVGmarkerData* mk,
								 float vx, float vy, float angle, int isStart,
								 float tx, float ty, float scale)
{
	float s, resScale;
	int dbgM = getenv("MSVG_DBG_MK") != NULL;
	if (mk == NULL) return;
	/* display:none does not gate marker rendering — markers render only
	   via marker-* references (SVG 1.1 §11.6.2). */
	if (mk->units == MSVG_MARKER_UNITS_STROKEWIDTH)
		s = shape->strokeWidth;
	else
		s = 1.0f;
	if (!(s > 0.0f)) return;
	resScale = scale * s;
	if (dbgM) fprintf(stderr, "[MK] shape=%s vx=%.2f vy=%.2f angle=%.1f s=%.3f resScale=%.3f tx=%.2f ty=%.2f scale=%.3f mw=%.1f mh=%.1f vb=%g,%g,%g,%g refX=%g refY=%g\n",
		shape->id[0] ? shape->id : "?", vx, vy, angle, s, resScale, tx, ty, scale,
		mk->markerWidth, mk->markerHeight, mk->viewBox[0], mk->viewBox[1], mk->viewBox[2], mk->viewBox[3], mk->refX, mk->refY);
	if (mk->orient == MSVG_ORIENT_AUTO_START_REVERSE && isStart)
		angle += 180.0f;
	if (mk->orient == MSVG_ORIENT_ANGLE)
		angle = mk->orientAngle;
	msvg__initMarkerTile(r, mk, resScale, shape, vx, vy, angle, s);
	msvg__compositeMarkerInstance(r, mk, vx, vy, angle, resScale, s, tx, ty, scale);
}

// Draws a shape's vertex markers (SVG 2 §Painting: marker-start/mid/end).
// The vertex list and orientation follow the spec's rules: marker-start only
// on the first vertex of the path data, marker-end only on the final vertex,
// marker-mid on every other vertex; closed subpaths draw two markers at their
// first/last vertex (leftmost: mid over start; middle: two mids; rightmost:
// end over mid); non-path closed shapes (rect/circle/ellipse/polygon) draw
// start+end at the final (=first) vertex. auto orientation: path direction at
// open endpoints, otherwise the bisector of the incoming/outgoing directions
// (zero-length segments resolved per the SVG 1.1 directionality algorithm).
static void msvg__drawMarkers(MSVGrasterizer* r, MSVGshape* shape,
							  float tx, float ty, float scale)
{
	MSVGpath* sp;
	int nsub = 0, nclosed = 0, si;

	if (r->markerRendering) return;
	if (r->markerDepth > 8) return;
	if (shape->paths == NULL) return;
	if (shape->markerStart == NULL && shape->markerMid == NULL && shape->markerEnd == NULL)
		return;

	for (sp = shape->paths; sp != NULL; sp = sp->next) {
		nsub++;
		if (sp->closed) nclosed++;
	}

	for (sp = shape->paths, si = 0; sp != NULL; sp = sp->next, si++) {
		int nseg = (sp->npts - 1) / 3;
		int vi;
		int closedIdx = -1;	// index of this subpath among closed subpaths
		float* v;
		if (nseg < 1) continue;
		if (sp->closed) {
			int k = 0;
			MSVGpath* q;
			for (q = shape->paths; q != sp; q = q->next)
				if (q->closed) k++;
			closedIdx = k;
		}
		v = (float*)malloc((nseg + 1) * 2 * sizeof(float));
		if (v == NULL) return;
		// Paths store 2 floats per point; a cubic segment contributes 3
		// points (start + ctrl1 + ctrl2 + end), so vertex i sits at point
		// index 3*i == float index 6*i.
		for (vi = 0; vi <= nseg; vi++) {
			v[vi*2] = sp->pts[vi*6];
			v[vi*2+1] = sp->pts[vi*6+1];
		}

		if (sp->closed) {
			// Distinct vertices are v[0..nseg-1]; v[nseg] == v[0] is the
			// closing point, handled at vi==0.
			for (vi = 0; vi < nseg; vi++) {
				float inx, iny, outx, outy;
				if (vi == 0) {
					// Closing vertex: incoming from the final segment,
					// outgoing from the first segment.
					msvg__dirForward(v, nseg, nseg-1, &inx, &iny);
					msvg__dirBackward(v, nseg, 0, &outx, &outy);
				} else {
					msvg__dirForward(v, nseg, vi-1, &inx, &iny);
					msvg__dirBackward(v, nseg, vi, &outx, &outy);
				}
				if (shape->elemType == MSVG_ELEM_CLOSEDSHAPE) {
					// Shape rule: marker-start + marker-end at the final
					// (=first) vertex, marker-mid on the others.
					if (vi == 0) {
						float ang = msvg__markerAngle(inx, iny, outx, outy);
						msvg__markerInstance(r, shape, shape->markerStart, v[0], v[1], ang, 1, tx, ty, scale);
						msvg__markerInstance(r, shape, shape->markerEnd, v[0], v[1], ang, 0, tx, ty, scale);
					} else {
						float ang = msvg__markerAngle(inx, iny, outx, outy);
						msvg__markerInstance(r, shape, shape->markerMid, v[vi*2], v[vi*2+1], ang, 0, tx, ty, scale);
					}
				} else {
					if (vi == 0) {
						float ang = msvg__markerAngle(inx, iny, outx, outy);
						// Leftmost closed subpath: mid over start; middle:
						// two mids; rightmost: end over mid.
						if (closedIdx == 0)
							msvg__markerInstance(r, shape, shape->markerStart, v[0], v[1], ang, 1, tx, ty, scale);
						msvg__markerInstance(r, shape, shape->markerMid, v[0], v[1], ang, 0, tx, ty, scale);
						if (closedIdx != 0 && closedIdx != nclosed - 1)
							msvg__markerInstance(r, shape, shape->markerMid, v[0], v[1], ang, 0, tx, ty, scale);
						if (closedIdx == nclosed - 1)
							msvg__markerInstance(r, shape, shape->markerEnd, v[0], v[1], ang, 0, tx, ty, scale);
					} else {
						float ang = msvg__markerAngle(inx, iny, outx, outy);
						msvg__markerInstance(r, shape, shape->markerMid, v[vi*2], v[vi*2+1], ang, 0, tx, ty, scale);
					}
				}
			}
		} else {
			for (vi = 0; vi <= nseg; vi++) {
				float inx, iny, outx, outy;
				if (si == 0 && vi == 0) {
					// Start of an open subpath: path direction (start of
					// first segment, resolved through zero-lengths).
					msvg__dirForward(v, nseg, 0, &inx, &iny);
					outx = inx; outy = iny;
				} else if (si == nsub-1 && vi == nseg) {
					// End of an open subpath: direction of the last segment.
					msvg__dirBackward(v, nseg, nseg-1, &inx, &iny);
					outx = inx; outy = iny;
				} else {
					msvg__dirForward(v, nseg, vi-1, &inx, &iny);
					msvg__dirBackward(v, nseg, vi, &outx, &outy);
				}
				if (si == 0 && vi == 0)
					msvg__markerInstance(r, shape, shape->markerStart, v[0], v[1],
										 msvg__markerAngle(inx, iny, outx, outy), 1, tx, ty, scale);
				else if (si == nsub-1 && vi == nseg)
					msvg__markerInstance(r, shape, shape->markerEnd, v[vi*2], v[vi*2+1],
										 msvg__markerAngle(inx, iny, outx, outy), 0, tx, ty, scale);
				else
					msvg__markerInstance(r, shape, shape->markerMid, v[vi*2], v[vi*2+1],
										 msvg__markerAngle(inx, iny, outx, outy), 0, tx, ty, scale);
			}
		}
		free(v);
	}
}

/* ------------------------------------------------------------------ */
/* Text layout + glyph generation (rasterize time)                     */
/* ------------------------------------------------------------------ */

// Returns the number of UTF-8 codepoints in a NUL-terminated string.
static int msvg__utf8Len(const unsigned char* s)
{
	int n = 0;
	while (*s) {
		unsigned int cp;
		int l = msvg__utf8Decode(s, &cp);
		if (l <= 0) { s++; continue; }
		n++;
		s += l;
	}
	return n;
}

// True when 'name' appears in a comma/space-separated glyph-name list
// (SVG 1.1 §20.7: g1/g2 are comma-separated lists of glyph names).
static int msvg__glyphNameInList(const char* list, const char* name)
{
	const char* p = list;
	size_t nl = strlen(name);
	if (list == NULL || name == NULL) return 0;
	while (*p) {
		const char* start = p;
		while (*p && *p != ',' && !msvg__isspace(*p)) p++;
		if ((size_t)(p - start) == nl && strncmp(start, name, nl) == 0)
			return 1;
		while (*p && (*p == ',' || msvg__isspace(*p))) p++;
	}
	return 0;
}

// Decodes one UTF-8 sequence (returns byte length, 0 on invalid input).
static int msvg__utf8Decode(const unsigned char* s, unsigned int* cp)
{
	if (s[0] < 0x80) {
		*cp = s[0];
		return 1;
	}
	if ((s[0] & 0xE0) == 0xC0 && (s[1] & 0xC0) == 0x80) {
		*cp = ((unsigned int)(s[0] & 0x1F) << 6) | (unsigned int)(s[1] & 0x3F);
		return 2;
	}
	if ((s[0] & 0xF0) == 0xE0 && (s[1] & 0xC0) == 0x80 && (s[2] & 0xC0) == 0x80) {
		*cp = ((unsigned int)(s[0] & 0x0F) << 12) | ((unsigned int)(s[1] & 0x3F) << 6)
			| (unsigned int)(s[2] & 0x3F);
		return 3;
	}
	if ((s[0] & 0xF8) == 0xF0 && (s[1] & 0xC0) == 0x80 &&
		(s[2] & 0xC0) == 0x80 && (s[3] & 0xC0) == 0x80) {
		*cp = ((unsigned int)(s[0] & 0x07) << 18) | ((unsigned int)(s[1] & 0x3F) << 12)
			| ((unsigned int)(s[2] & 0x3F) << 6) | (unsigned int)(s[3] & 0x3F);
		return 4;
	}
	return 0;
}

// Deep-copies a path list (no transform).
static MSVGpath* msvg__copyPaths(MSVGpath* src)
{
	MSVGpath* head = NULL;
	MSVGpath* tail = NULL;
	while (src != NULL) {
		MSVGpath* np = (MSVGpath*)malloc(sizeof(MSVGpath));
		if (np == NULL) { msvg__deletePaths(head); return NULL; }
		memset(np, 0, sizeof(MSVGpath));
		np->npts = src->npts;
		np->closed = src->closed;
		np->pts = (float*)malloc((size_t)src->npts * 2 * sizeof(float));
		if (np->pts == NULL) { free(np); msvg__deletePaths(head); return NULL; }
		memcpy(np->pts, src->pts, (size_t)src->npts * 2 * sizeof(float));
		memcpy(np->bounds, src->bounds, sizeof(float) * 4);
		if (tail)
			tail->next = np;
		else
			head = np;
		tail = np;
		src = src->next;
	}
	return head;
}

/* ------------------------------------------------------------------ */
/* Bidi (Unicode Bidirectional Algorithm, UAX#9) — SVG 1.1 §10.7.4,
   SVG 2 §11.11. Compact BMP class table + Bidi_Mirrored pairs.
   Class codes: 0=L 1=R 2=AL 3=EN 4=AN 5=ES 6=CS 7=ET 8=ON 9=NSM
   10=BN 11=LRE 12=LRO 13=RLE 14=RLO 15=PDF 16=LRI 17=RLI 18=FSI
   19=PDI 20=B 21=S 22=WS. Generated from the Unicode Character
   Database (bidi classes) and BidiMirroring.txt (mirror pairs).
   ------------------------------------------------------------------ */
/* Bidi classes, BMP only: 57 distinct 256-char blocks + 256-byte high-byte index.
   Class codes: 0=L 1=R 2=AL 3=EN 4=AN 5=ES 6=CS 7=ET 8=ON 9=NSM 10=BN
   11=LRE 12=LRO 13=RLE 14=RLO 15=PDF 16=LRI 17=RLI 18=FSI 19=PDI
   20=B 21=S 22=WS */
